INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C1','math',6,2,'u4',2,'비의 성질 — 비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 같은 수로 나누어도 비율은 같음을 알고(같은 수를 더하는 것은 성질이 아님), 전항·후항·비율을 바르게 읽기',ARRAY['6수04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C2','math',6,2,'u4',3,'자연수의 비를 간단한 자연수의 비로 나타내기 — 두 항의 공약수로 더 나눌 수 없을 때까지(최대공약수로) 나누기',ARRAY['6수04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C3','math',6,2,'u4',3,'소수의 비를 간단한 자연수의 비로 나타내기 — 두 항이 모두 자연수가 되도록 10·100을 곱한 뒤 공약수로 나누기',ARRAY['6수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C4','math',6,2,'u4',3,'분수의 비와 소수·분수가 섞인 비를 간단한 자연수의 비로 나타내기 — 두 분모의 공배수를 곱하거나, 한쪽을 소수(분수)로 바꾸어 같은 꼴로 만든 뒤 나타내기',ARRAY['6수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C5','math',6,2,'u4',4,'비례식과 외항·내항 — 비율이 같은 두 비를 등호로 이은 식을 비례식이라 하고, 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라 하며, 비례식인지는 수의 모양이 아니라 비율로 판단하기',ARRAY['6수04-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C6','math',6,2,'u4',5,'비례식의 성질 — 비례식에서 외항의 곱과 내항의 곱이 같음을 알고, 이를 이용하여 □가 있는 비례식을 풀거나 비례식인지 확인하기',ARRAY['6수04-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C7','math',6,2,'u4',6,'비례식을 세워 생활 문제 해결하기 — 함께 같은 비율로 변하는 두 양에서 구하려는 것을 □로 두고 대응이 맞게 비례식을 세운 뒤 비례식의 성질이나 비의 성질로 풀기',ARRAY['6수04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C8','math',6,2,'u4',7,'비례배분 — 전체를 가：나로 배분할 때 전체를 (가+나)칸으로 갈라 전체 × (가 ÷ (가+나)), 전체 × (나 ÷ (가+나))로 구하기',ARRAY['6수04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u4-C9','math',6,2,'u4',8,'비례배분 활용 — 먼저 전체에서 우리 몫을 비례배분한 뒤 그 몫을 다시 정한 기준(낸 금액·만든 수 등)의 비로 나누고, 기준에 따라 몫이 달라짐을 알기',ARRAY['6수04-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X01','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C5']::text[],'전항과 후항에 같은 수를 더하거나 빼도 비율이 같다고 본다(2：3에 2를 더해 4：5)','더하기는 비의 성질이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X02','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'전항과 후항 가운데 한 항에만 곱하거나 한 항만 나눈다','두 항을 똑같이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X03','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5']::text[],'전항과 후항(비교하는 양과 기준량)을 바꾸어 쓰거나 비율의 기준량을 잘못 잡는다','「무엇에 대한」 쪽이 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X04','math',6,'u4',ARRAY['M6-2-u4-C1']::text[],'전항과 후항에 0을 곱하거나 0으로 나누어도 된다고 본다','0이 아닌 같은 수만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X05','math',6,'u4',ARRAY['M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4']::text[],'공약수로 끝까지 나누지 않아 가장 간단한 자연수의 비가 아닌 채로 멈춘다','더 나눌 공약수가 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X06','math',6,'u4',ARRAY['M6-2-u4-C3','M6-2-u4-C4']::text[],'소수의 비에서 곱하는 수를 잘못 정해(한 자리 수에만 맞춰 10만 곱하는 등) 자연수가 되지 않거나 비가 달라진다','두 항이 모두 자연수가 되도록') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X07','math',6,'u4',ARRAY['M6-2-u4-C4']::text[],'분수의 비에서 분모끼리 또는 분자끼리만 떼어 비로 쓴다(⟨1/5⟩：⟨1/7⟩을 5：7이나 1：1로)','두 분모의 공배수를 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X09','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C6']::text[],'두 비의 수 모양만 보고(같은 수가 들어 있으면) 비례식이라고 판단한다(7：4 = 4：7)','비율을 견주어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X10','math',6,'u4',ARRAY['M6-2-u4-C5','M6-2-u4-C6']::text[],'외항과 내항을 바꾸어 안다(안쪽 두 수를 외항으로)','바깥 둘이 외항') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X11','math',6,'u4',ARRAY['M6-2-u4-C6','M6-2-u4-C7']::text[],'외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱한다','바깥끼리, 안쪽끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X12','math',6,'u4',ARRAY['M6-2-u4-C6','M6-2-u4-C7']::text[],'외항의 곱과 내항의 곱을 같게 놓은 뒤 □를 구하지 않고 곱한 값을 답으로 쓰거나 나눗셈을 잘못한다','곱 ÷ 아는 수 = □') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X13','math',6,'u4',ARRAY['M6-2-u4-C7']::text[],'비례식을 세울 때 대응을 어긋나게 놓는다(2：8000 = 40000：★처럼 무게와 값의 자리를 바꿈)','같은 종류끼리 같은 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X14','math',6,'u4',ARRAY['M6-2-u4-C7']::text[],'두 양이 같은 비율로 변하는지 보지 않고 차이(더하기·빼기)로 늘린다','몇 배가 되었는지 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X15','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분에서 전체를 비의 한 항(가 또는 나)으로 나눈다(1200을 2：3으로 → 1200 ÷ 2)','한 묶음은 (가+나)칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X16','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분에서 (가 ÷ (가+나)) 대신 (가 ÷ 나)를 곱하거나 한 칸의 양을 답으로 쓴다','분모는 가+나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X17','math',6,'u4',ARRAY['M6-2-u4-C8','M6-2-u4-C9']::text[],'비례배분한 두 몫 가운데 다른 쪽의 몫을 답으로 쓴다','누구의 몫을 묻나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X18','math',6,'u4',ARRAY['M6-2-u4-C9']::text[],'두 번 나누어야 할 때 첫 단계(전체에서 우리 몫)를 건너뛰고 전체를 바로 나눈다','먼저 우리 몫부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X19','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5','M6-2-u4-C6','M6-2-u4-C7','M6-2-u4-C8','M6-2-u4-C9']::text[],'묻는 말을 거꾸로 읽는다 — 알맞은↔알맞지 않은, 외항↔내항, 큰↔작은','물음의 「않은·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u4-X20','math',6,'u4',ARRAY['M6-2-u4-C1','M6-2-u4-C2','M6-2-u4-C3','M6-2-u4-C4','M6-2-u4-C5','M6-2-u4-C6','M6-2-u4-C7','M6-2-u4-C8','M6-2-u4-C9']::text[],'곱셈·나눗셈·약분 계산을 잘못한다','거꾸로 곱해서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#1','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'mc','auto','비 3：4에서 후항은 어느 수인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"mc","stem":"비 3：4에서 후항은 어느 수인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M6-2-u4-X03"},{"t":"7","mis":"M6-2-u4-X20"},{"t":"12","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","3：4에서 전항은 3, 후항은 4예요.","그래서 후항은 4예요."],"variant_rule":{"alt":[{"stem":"비 5：8에서 전항은 어느 수인가요?","options":[{"t":"5","correct":true},{"t":"8","mis":"M6-2-u4-X03"},{"t":"13","mis":"M6-2-u4-X20"},{"t":"40","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 전항은 5예요."]},{"stem":"비 7：2에서 후항은 어느 수인가요?","options":[{"t":"2","correct":true},{"t":"7","mis":"M6-2-u4-X03"},{"t":"9","mis":"M6-2-u4-X20"},{"t":"14","mis":"M6-2-u4-X20"}],"explanation":["기호 ：의 앞에 있는 수를 전항, 뒤에 있는 수를 후항이라고 해요.","7：2에서 전항은 7, 후항은 2예요.","그래서 후항은 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#2','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'mc','auto','학생 7명 중에서 안경을 쓴 학생은 2명이에요. 전체 학생 수에 대한 안경을 쓴 학생 수의 비율은 얼마인가요?',ARRAY['M6-2-u4-X03']::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"mc","stem":"학생 7명 중에서 안경을 쓴 학생은 2명이에요. 전체 학생 수에 대한 안경을 쓴 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨7/2⟩","mis":"M6-2-u4-X03"},{"t":"⟨2/9⟩","mis":"M6-2-u4-X03"},{"t":"⟨7/9⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","2：7에서 비교하는 양은 2, 기준량은 7이에요.","비율은 2 ÷ 7 = ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"학생 8명 중에서 우산을 가져온 학생은 3명이에요. 전체 학생 수에 대한 우산을 가져온 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨3/8⟩","correct":true},{"t":"⟨8/3⟩","mis":"M6-2-u4-X03"},{"t":"⟨3/11⟩","mis":"M6-2-u4-X03"},{"t":"⟨8/11⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","3：8에서 비교하는 양은 3, 기준량은 8이에요.","비율은 3 ÷ 8 = ⟨3/8⟩이에요."]},{"stem":"학생 9명 중에서 자전거를 타는 학생은 4명이에요. 전체 학생 수에 대한 자전거를 타는 학생 수의 비율은 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨9/4⟩","mis":"M6-2-u4-X03"},{"t":"⟨4/13⟩","mis":"M6-2-u4-X03"},{"t":"⟨9/13⟩","mis":"M6-2-u4-X03"}],"explanation":["비율은 (비교하는 양) ÷ (기준량)이에요.","4：9에서 비교하는 양은 4, 기준량은 9예요.","비율은 4 ÷ 9 = ⟨4/9⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#3','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'sa','auto','7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."],"variant_rule":{"alt":[{"stem":"3：4의 전항과 후항에 똑같이 6을 곱했어요. 18：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 6을 곱해 18이 되었으니 후항 4에도 6을 곱해요.","4 × 6 = 24 — 18：24예요."]},{"stem":"2：3의 전항과 후항에 똑같이 7을 곱했어요. 14：□에서 □에 알맞은 수는 얼마인가요?","answer":["21"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 2에 7을 곱해 14가 되었으니 후항 3에도 7을 곱해요.","3 × 7 = 21 — 14：21이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#4','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',1,'sa','auto','45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."],"variant_rule":{"alt":[{"stem":"12：20의 전항과 후항을 똑같이 4로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 12를 4로 나누면 3이에요.","후항도 20 ÷ 4 = 5 — 3：5예요."]},{"stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#5','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'sa','auto','비눗방울 용액과 물을 2：1로 섞어요. 용액을 4컵 넣으면 물은 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"비눗방울 용액과 물을 2：1로 섞어요. 용액을 4컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["2"],"explanation":["2：1에서 앞의 수 2가 4가 되었으니 2배예요.","비율이 같으려면 뒤의 수도 똑같이 2배 해야 해요.","1 × 2 = 2예요."],"variant_rule":{"alt":[{"stem":"비눗방울 용액과 물을 2：1로 섞어요. 용액을 6컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["3"],"explanation":["2：1에서 앞의 수 2가 6이 되었으니 3배예요.","비율이 같으려면 뒤의 수도 똑같이 3배 해야 해요.","1 × 3 = 3이에요."]},{"stem":"비눗방울 용액과 물을 3：1로 섞어요. 용액을 9컵 넣으면 물은 몇 컵을 넣어야 하나요?","answer":["3"],"explanation":["3：1에서 앞의 수 3이 9가 되었으니 3배예요.","비율이 같으려면 뒤의 수도 똑같이 3배 해야 해요.","1 × 3 = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#6','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','2：3과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#7','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','14：10과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":7,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"14：10과 비율이 같은 비는 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"12：8","mis":"M6-2-u4-X01"},{"t":"5：7","mis":"M6-2-u4-X03"},{"t":"7：10","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","14：10의 두 항을 똑같이 2로 나누면 7：5예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"12：20과 비율이 같은 비는 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"8：16","mis":"M6-2-u4-X01"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","12：20의 두 항을 똑같이 4로 나누면 3：5예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."]},{"stem":"18：12와 비율이 같은 비는 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"12：6","mis":"M6-2-u4-X01"},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"3：12","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","18：12의 두 항을 똑같이 6으로 나누면 3：2예요.","같은 수를 빼거나 순서를 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#8','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'sa','auto','꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 14장이면 빨간 색종이는 몇 장이 필요한가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 14장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["21"],"explanation":["2：3에서 앞의 수 2가 14가 되었으니 7배예요.","비율이 같으려면 뒤의 수도 똑같이 7배 해야 해요.","3 × 7 = 21이에요."],"variant_rule":{"alt":[{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 10장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["15"],"explanation":["2：3에서 앞의 수 2가 10이 되었으니 5배예요.","비율이 같으려면 뒤의 수도 똑같이 5배 해야 해요.","3 × 5 = 15예요."]},{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 초록 색종이가 16장이면 빨간 색종이는 몇 장이 필요한가요?","answer":["24"],"explanation":["2：3에서 앞의 수 2가 16이 되었으니 8배예요.","비율이 같으려면 뒤의 수도 똑같이 8배 해야 해요.","3 × 8 = 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#9','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',2,'mc','auto','6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"6：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 2를 더해 8：6을 구한다","correct":true},{"t":"전항과 후항에 2를 곱해 12：8을 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항을 2로 나누어 3：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 3을 곱해 18：12를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 0이 아닌 같은 수를 곱하거나 나누어 만들어요.","12：8, 3：2, 18：12는 모두 비율이 ⟨3/2⟩이에요.","8：6은 비율이 ⟨4/3⟩ — 같은 수를 더하는 것은 비의 성질이 아니에요."],"variant_rule":{"alt":[{"stem":"9：6과 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에서 3을 빼서 6：3을 구한다","correct":true},{"t":"전항과 후항을 3으로 나누어 3：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 2를 곱해 18：12를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 4를 곱해 36：24를 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 같은 수를 곱하거나 나누어 만들어요.","3：2, 18：12, 36：24는 모두 비율이 ⟨3/2⟩이에요.","6：3은 비율이 2 — 같은 수를 빼는 것은 비의 성질이 아니에요."]},{"stem":"10：4와 비율이 같은 비를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"전항과 후항에 5를 더해 15：9를 구한다","correct":true},{"t":"전항과 후항을 2로 나누어 5：2를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 3을 곱해 30：12를 구한다","mis":"M6-2-u4-X19"},{"t":"전항과 후항에 10을 곱해 100：40을 구한다","mis":"M6-2-u4-X19"}],"explanation":["비율이 같은 비는 두 항에 같은 수를 곱하거나 나누어 만들어요.","5：2, 30：12, 100：40은 모두 비율이 ⟨5/2⟩예요.","15：9는 비율이 ⟨5/3⟩ — 더하기는 비의 성질이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_basic#10','math',6,2,'u4','L02','g6_2_math_u4_L02_basic','lesson_basic','M6-2-u4-C1',3,'ox','auto','2：3의 전항과 후항에 똑같이 0을 곱해도 비율은 그대로예요.',ARRAY['M6-2-u4-X04']::text[],true,'{"seq":10,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"2：3의 전항과 후항에 똑같이 0을 곱해도 비율은 그대로예요.","answer":"X","reason_options":[{"t":"0을 곱하면 0：0이 되어 비율을 말할 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"mis":"M6-2-u4-X04","explanation":["비의 성질은 0이 아닌 같은 수를 곱할 때만 써요.","2：3에 0을 곱하면 0：0이 돼요.","0：0은 비율을 나타낼 수 없어요."],"variant_rule":{"alt":[{"stem":"6：9의 전항과 후항을 똑같이 0으로 나누어도 비율은 그대로예요.","answer":"X","reason_options":[{"t":"어떤 수도 0으로는 나눌 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"explanation":["비의 성질은 0이 아닌 같은 수로 나눌 때만 써요.","0으로 나누는 계산은 할 수 없어요.","그래서 6：9를 0으로 나눌 수 없어요."]},{"stem":"4：5의 전항과 후항에 0이 아닌 같은 수를 곱해야 비율이 그대로예요.","answer":"O","reason_options":[{"t":"0을 곱하면 0：0이 되어 비율을 말할 수 없기 때문에","correct":true},{"t":"0도 같은 수이니 곱하거나 나누어도 비율이 그대로이기 때문에","mis":"M6-2-u4-X04"}],"explanation":["4：5에 3을 곱한 12：15는 비율이 ⟨4/5⟩로 같아요.","0을 곱하면 0：0이 돼요.","그래서 「0이 아닌」 같은 수라는 조건이 붙어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#1','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',2,'sa','auto','4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":2,"kind":"sa","stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."],"variant_rule":{"alt":[{"stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."]},{"stem":"8：3의 전항과 후항에 똑같이 5를 곱했어요. 40：□에서 □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 8에 5를 곱해 40이 되었으니 후항 3에도 5를 곱해요.","3 × 5 = 15 — 40：15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#2','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',2,'mc','auto','24：36의 전항과 후항을 똑같이 12로 나누면 어떤 비가 되나요?',ARRAY['M6-2-u4-X02','M6-2-u4-X01','M6-2-u4-X03']::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"24：36의 전항과 후항을 똑같이 12로 나누면 어떤 비가 되나요?","options":[{"t":"2：3","correct":true},{"t":"2：36","mis":"M6-2-u4-X02"},{"t":"12：24","mis":"M6-2-u4-X01"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 12로 나누어요.","24 ÷ 12 = 2, 36 ÷ 12 = 3이에요.","그래서 2：3 — 비율은 그대로예요."],"variant_rule":{"alt":[{"stem":"28：21의 전항과 후항을 똑같이 7로 나누면 어떤 비가 되나요?","options":[{"t":"4：3","correct":true},{"t":"4：21","mis":"M6-2-u4-X02"},{"t":"21：14","mis":"M6-2-u4-X01"},{"t":"3：4","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 7로 나누어요.","28 ÷ 7 = 4, 21 ÷ 7 = 3이에요.","그래서 4：3 — 비율은 그대로예요."]},{"stem":"40：64의 전항과 후항을 똑같이 8로 나누면 어떤 비가 되나요?","options":[{"t":"5：8","correct":true},{"t":"5：64","mis":"M6-2-u4-X02"},{"t":"32：56","mis":"M6-2-u4-X01"},{"t":"8：5","mis":"M6-2-u4-X03"}],"explanation":["전항과 후항을 똑같이 8로 나누어요.","40 ÷ 8 = 5, 64 ÷ 8 = 8이에요.","그래서 5：8 — 비율은 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#3','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'mc','auto','화면의 가로와 세로의 비가 16：9예요. 이와 비율이 같은 화면은 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":3,"kind":"mc","stem":"화면의 가로와 세로의 비가 16：9예요. 이와 비율이 같은 화면은 어느 것인가요?","options":[{"t":"가로 32 cm, 세로 18 cm","correct":true},{"t":"가로 20 cm, 세로 13 cm","mis":"M6-2-u4-X01"},{"t":"가로 18 cm, 세로 32 cm","mis":"M6-2-u4-X03"},{"t":"가로 32 cm, 세로 9 cm","mis":"M6-2-u4-X02"}],"explanation":["16：9에 같은 수를 곱한 비를 찾아요.","16：9의 두 항에 2를 곱하면 32：18이에요.","같은 수를 더하거나 가로·세로를 바꾼 것은 비율이 달라요."],"variant_rule":{"alt":[{"stem":"화면의 가로와 세로의 비가 4：3이에요. 이와 비율이 같은 화면은 어느 것인가요?","options":[{"t":"가로 20 cm, 세로 15 cm","correct":true},{"t":"가로 6 cm, 세로 5 cm","mis":"M6-2-u4-X01"},{"t":"가로 15 cm, 세로 20 cm","mis":"M6-2-u4-X03"},{"t":"가로 20 cm, 세로 3 cm","mis":"M6-2-u4-X02"}],"explanation":["4：3에 같은 수를 곱한 비를 찾아요.","4：3의 두 항에 5를 곱하면 20：15예요.","같은 수를 더하거나 가로·세로를 바꾼 것은 비율이 달라요."]},{"stem":"사진의 가로와 세로의 비가 3：2예요. 이와 비율이 같은 사진은 어느 것인가요?","options":[{"t":"가로 12 cm, 세로 8 cm","correct":true},{"t":"가로 5 cm, 세로 4 cm","mis":"M6-2-u4-X01"},{"t":"가로 8 cm, 세로 12 cm","mis":"M6-2-u4-X03"},{"t":"가로 12 cm, 세로 2 cm","mis":"M6-2-u4-X02"}],"explanation":["3：2에 같은 수를 곱한 비를 찾아요.","3：2의 두 항에 4를 곱하면 12：8이에요.","같은 수를 더하거나 가로·세로를 바꾼 것은 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#4','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'error','auto','5：2와 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X19']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"error","stem":"5：2와 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「두 항에 3을 더한 8：5도 비율이 같아.」","correct":true,"mis_target":"M6-2-u4-X01"},{"t":"나린 — 「두 항에 2를 곱한 10：4는 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"지호 — 「두 항에 4를 곱한 20：8도 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"유진 — 「비율은 모두 ⟨5/2⟩야.」","mis":"M6-2-u4-X19"}],"explanation":["10：4와 20：8은 두 항에 같은 수를 곱해 비율이 ⟨5/2⟩예요.","8：5는 비율이 ⟨8/5⟩로 달라요.","같은 수를 더하는 것은 비의 성질이 아니에요 — 가온이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"12：8과 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「두 항에서 4를 뺀 8：4도 비율이 같아.」","correct":true,"mis_target":"M6-2-u4-X01"},{"t":"하린 — 「두 항을 4로 나눈 3：2는 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"도윤 — 「두 항에 2를 곱한 24：16도 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"민준 — 「비율은 모두 ⟨3/2⟩이야.」","mis":"M6-2-u4-X19"}],"explanation":["3：2와 24：16은 비율이 ⟨3/2⟩이에요.","8：4는 비율이 2로 달라요.","같은 수를 빼는 것은 비의 성질이 아니에요 — 수아가 잘못 말했어요."]},{"stem":"3：7과 비율이 같은 비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「두 항에 10을 더한 13：17도 비율이 같아.」","correct":true,"mis_target":"M6-2-u4-X01"},{"t":"지호 — 「두 항에 10을 곱한 30：70은 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"가온 — 「두 항에 2를 곱한 6：14도 비율이 같아.」","mis":"M6-2-u4-X19"},{"t":"나린 — 「비율은 모두 ⟨3/7⟩이야.」","mis":"M6-2-u4-X19"}],"explanation":["30：70과 6：14는 비율이 ⟨3/7⟩이에요.","13：17은 비율이 ⟨13/17⟩으로 달라요.","같은 수를 더하는 것은 비의 성질이 아니에요 — 서아가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#5','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'mc','auto','꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 꽃다발 4개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X02','M6-2-u4-X03']::text[],true,'{"seq":5,"concept":"M6-2-u4-C1","difficulty":3,"kind":"mc","stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 꽃다발 4개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"8：12","correct":true},{"t":"6：7","mis":"M6-2-u4-X01"},{"t":"8：3","mis":"M6-2-u4-X02"},{"t":"12：8","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 4개면 초록도 빨강도 4배가 돼요.","초록 8장, 빨강 12장 — 8：12예요.","비율은 여전히 ⟨2/3⟩예요."],"variant_rule":{"alt":[{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 꽃다발 5개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"10：15","correct":true},{"t":"7：8","mis":"M6-2-u4-X01"},{"t":"10：3","mis":"M6-2-u4-X02"},{"t":"15：10","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 5개면 초록도 빨강도 5배가 돼요.","초록 10장, 빨강 15장 — 10：15예요.","비율은 여전히 ⟨2/3⟩예요."]},{"stem":"꽃다발 하나에 초록 색종이 2장과 빨간 색종이 3장이 들어가요. 꽃다발 3개를 만들 때 필요한 초록 색종이 수와 빨간 색종이 수의 비는 어느 것인가요?","options":[{"t":"6：9","correct":true},{"t":"5：6","mis":"M6-2-u4-X01"},{"t":"6：3","mis":"M6-2-u4-X02"},{"t":"9：6","mis":"M6-2-u4-X03"}],"explanation":["꽃다발 3개면 초록도 빨강도 3배가 돼요.","초록 6장, 빨강 9장 — 6：9예요.","비율은 여전히 ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#6','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'ox','auto','4：6과 6：9는 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":6,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"4：6과 6：9는 비율이 같아요.","answer":"O","reason_options":[{"t":"둘 다 2：3의 두 항에 같은 수(2와 3)를 곱한 비라서","correct":true},{"t":"4：6의 두 항에 2와 3을 더한 비가 6：9라서","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["4：6을 2로 나누면 2：3이에요.","6：9를 3으로 나누면 2：3이에요.","그래서 비율은 모두 ⟨2/3⟩로 같아요."],"variant_rule":{"alt":[{"stem":"3：5와 5：7은 비율이 같아요.","answer":"X","reason_options":[{"t":"5：7은 3：5에 2를 더했을 뿐 같은 수를 곱한 비가 아니라서","correct":true},{"t":"두 항에 똑같이 2를 더했으니 비율이 같아서","mis":"M6-2-u4-X01"}],"explanation":["3：5의 비율은 ⟨3/5⟩이에요.","5：7의 비율은 ⟨5/7⟩예요.","같은 수를 더하면 비율이 달라져요."]},{"stem":"6：8과 9：12는 비율이 같아요.","answer":"O","reason_options":[{"t":"둘 다 3：4의 두 항에 같은 수(2와 3)를 곱한 비라서","correct":true},{"t":"6：8의 두 항에 3과 4를 더한 비가 9：12라서","mis":"M6-2-u4-X01"}],"explanation":["6：8을 2로 나누면 3：4예요.","9：12를 3으로 나누면 3：4예요.","그래서 비율은 모두 ⟨3/4⟩으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#7','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',3,'match','auto','비율이 같은 비끼리 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C1","difficulty":3,"kind":"match","stem":"비율이 같은 비끼리 이으세요.","pairs":[{"l":"2：3","r":"8：12"},{"l":"3：4","r":"9：12"},{"l":"5：2","r":"15：6"}],"mis":"M6-2-u4-X01","explanation":["2：3에 4를 곱하면 8：12예요.","3：4에 3을 곱하면 9：12예요.","5：2에 3을 곱하면 15：6이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율이 같은 비끼리 이으세요.","pairs":[{"l":"4：5","r":"12：15"},{"l":"1：3","r":"5：15"},{"l":"7：2","r":"14：4"}],"explanation":["4：5에 3을 곱하면 12：15예요.","1：3에 5를 곱하면 5：15예요.","7：2에 2를 곱하면 14：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#8','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'mc','auto','비율이 ⟨3/4⟩이고 전항과 후항의 합이 28인 비는 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X20','M6-2-u4-X02']::text[],true,'{"seq":8,"concept":"M6-2-u4-C1","difficulty":4,"kind":"mc","stem":"비율이 ⟨3/4⟩이고 전항과 후항의 합이 28인 비는 어느 것인가요?","options":[{"t":"12：16","correct":true},{"t":"16：12","mis":"M6-2-u4-X03"},{"t":"9：12","mis":"M6-2-u4-X20"},{"t":"3：25","mis":"M6-2-u4-X02"}],"explanation":["3：4의 두 항에 같은 수를 곱해도 비율은 ⟨3/4⟩이에요.","3 + 4 = 7이고 28은 7의 4배예요.","두 항에 4를 곱하면 12：16 — 합이 28이에요."],"variant_rule":{"alt":[{"stem":"비율이 ⟨2/5⟩이고 전항과 후항의 합이 35인 비는 어느 것인가요?","options":[{"t":"10：25","correct":true},{"t":"25：10","mis":"M6-2-u4-X03"},{"t":"8：20","mis":"M6-2-u4-X20"},{"t":"2：33","mis":"M6-2-u4-X02"}],"explanation":["2：5의 두 항에 같은 수를 곱해도 비율은 ⟨2/5⟩예요.","2 + 5 = 7이고 35는 7의 5배예요.","두 항에 5를 곱하면 10：25 — 합이 35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#9','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'essay','teacher','순달이는 비눗방울 용액과 물을 2：1로 섞어요. 용액을 6컵 넣으면 물은 몇 컵을 넣어야 하는지 구하고, 그렇게 해도 진하기가 그대로인 까닭을 비의 성질로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C1","difficulty":4,"kind":"essay","stem":"순달이는 비눗방울 용액과 물을 2：1로 섞어요. 용액을 6컵 넣으면 물은 몇 컵을 넣어야 하는지 구하고, 그렇게 해도 진하기가 그대로인 까닭을 비의 성질로 설명해 보세요.","answer_guide":{"answer":"예: 용액 2컵과 물 1컵을 한 묶음으로 보면 용액 6컵은 3묶음이므로 물은 3컵이다. 2：1의 전항과 후항에 똑같이 3을 곱해 6：3이 되었고, 0이 아닌 같은 수를 곱하면 비율이 같으므로 진하기가 그대로이다.","scoring_points":["물 3컵을 구했는가","두 항에 똑같이 3을 곱했음을 밝혔는가","같은 수를 곱하면 비율이 같다는 까닭을 썼는가"]},"explanation":["용액 6컵은 2컵의 3배예요.","물도 1컵의 3배 — 3컵이에요.","6：3은 2：1과 비율이 같아 진하기가 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L02_challenge#10','math',6,2,'u4','L02','g6_2_math_u4_L02_challenge','lesson_challenge','M6-2-u4-C1',4,'essay','teacher','6：4와 비율이 같은 비를 두 개 만들고, 친구가 만든 8：6이 6：4와 비율이 같지 않은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C1","difficulty":4,"kind":"essay","stem":"6：4와 비율이 같은 비를 두 개 만들고, 친구가 만든 8：6이 6：4와 비율이 같지 않은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 6：4의 두 항에 2를 곱하면 12：8, 2로 나누면 3：2이다. 8：6은 두 항에 2를 더한 것인데, 같은 수를 더하는 것은 비의 성질이 아니므로 비율이 ⟨4/3⟩로 ⟨3/2⟩과 다르다.","scoring_points":["비율이 같은 비 두 개를 바르게 만들었는가","8：6은 같은 수를 더한 것임을 밝혔는가","두 비의 비율을 견주어 다름을 보였는가"]},"explanation":["12：8, 3：2는 비율이 ⟨3/2⟩이에요.","8：6은 2를 더한 비예요.","8：6의 비율은 ⟨4/3⟩ — 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#1','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C2',1,'mc','auto','28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":1,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"4：63","mis":"M6-2-u4-X02"},{"t":"28：9","mis":"M6-2-u4-X02"}],"explanation":["28과 63의 최대공약수는 7이에요.","전항과 후항을 똑같이 7로 나누면 4：9예요.","4와 9는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"18：9","mis":"M6-2-u4-X05"},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：27","mis":"M6-2-u4-X02"}],"explanation":["54와 27의 최대공약수는 27이에요.","전항과 후항을 똑같이 27로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"6：10","mis":"M6-2-u4-X05"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["12와 20의 최대공약수는 4예요.","전항과 후항을 똑같이 4로 나누면 3：5예요.","3과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#2','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',1,'sa','auto','0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.8：0.4에 10을 곱하면 8：4예요.","두 항을 4로 나누면 2：1이에요."],"variant_rule":{"alt":[{"stem":"3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","3.5：4.9에 10을 곱하면 35：49예요.","두 항을 7로 나누면 5：7이에요."]},{"stem":"0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.6：1.5에 10을 곱하면 6：15예요.","두 항을 3으로 나누면 2：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#3','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',1,'sa','auto','2.5：3의 전항과 후항에 똑같이 2를 곱했어요. 5：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"2.5：3의 전항과 후항에 똑같이 2를 곱했어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["소수가 있는 비도 두 항에 같은 수를 곱하면 비율이 같아요.","2.5 × 2 = 5예요.","3 × 2 = 6 — 5：6이에요."],"variant_rule":{"alt":[{"stem":"1.5：2의 전항과 후항에 똑같이 2를 곱했어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["소수가 있는 비도 두 항에 같은 수를 곱하면 비율이 같아요.","1.5 × 2 = 3이에요.","2 × 2 = 4 — 3：4예요."]},{"stem":"3.5：4의 전항과 후항에 똑같이 2를 곱했어요. 7：□에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["소수가 있는 비도 두 항에 같은 수를 곱하면 비율이 같아요.","3.5 × 2 = 7이에요.","4 × 2 = 8 — 7：8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#4','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C2',1,'sa','auto','45：18을 간단한 자연수의 비로 나타내면 5：□예요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u4-C2","difficulty":1,"kind":"sa","stem":"45：18을 간단한 자연수의 비로 나타내면 5：□예요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["45와 18의 최대공약수는 9예요.","두 항을 똑같이 9로 나눠요.","18 ÷ 9 = 2 — 5：2예요."],"variant_rule":{"alt":[{"stem":"36：48을 간단한 자연수의 비로 나타내면 3：□예요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["36과 48의 최대공약수는 12예요.","두 항을 똑같이 12로 나눠요.","48 ÷ 12 = 4 — 3：4예요."]},{"stem":"35：14를 간단한 자연수의 비로 나타내면 5：□예요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["35와 14의 최대공약수는 7이에요.","두 항을 똑같이 7로 나눠요.","14 ÷ 7 = 2 — 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#5','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',2,'mc','auto','고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."],"variant_rule":{"alt":[{"stem":"1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"14：12","mis":"M6-2-u4-X05"},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"14：1.2","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 14：12예요.","14와 12의 최대공약수 2로 나누면 7：6이에요.","그래서 가장 간단한 자연수의 비는 7：6이에요."]},{"stem":"0.5：1.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"5：15","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"5：1.5","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 5：15예요.","5와 15의 최대공약수 5로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#6','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'mc','auto','⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03']::text[],true,'{"seq":6,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"},{"t":"9：14","mis":"M6-2-u4-X03"}],"explanation":["두 분모 3과 7의 공배수 21을 전항과 후항에 똑같이 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 가장 간단한 자연수의 비는 14：9예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["두 분모 6과 4의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 가장 간단한 자연수의 비는 2：3이에요."]},{"stem":"⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"9：10","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"10：9","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨3/4⟩ × 12 = 9, ⟨5/6⟩ × 12 = 10이에요.","그래서 가장 간단한 자연수의 비는 9：10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#7','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'mc','auto','민규는 책 전체의 ⟨1/5⟩, 세아는 ⟨1/7⟩을 읽었어요. 두 사람이 읽은 쪽수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":7,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"민규는 책 전체의 ⟨1/5⟩, 세아는 ⟨1/7⟩을 읽었어요. 두 사람이 읽은 쪽수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"5：7","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"8：5","mis":"M6-2-u4-X20"}],"explanation":["두 분모 5와 7의 공배수 35를 전항과 후항에 똑같이 곱해요.","⟨1/5⟩ × 35 = 7, ⟨1/7⟩ × 35 = 5예요.","그래서 가장 간단한 자연수의 비는 7：5예요."],"variant_rule":{"alt":[{"stem":"하린이는 책 전체의 ⟨1/4⟩, 도윤이는 ⟨1/6⟩을 읽었어요. 두 사람이 읽은 쪽수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/4⟩ × 12 = 3, ⟨1/6⟩ × 12 = 2예요.","그래서 가장 간단한 자연수의 비는 3：2예요."]},{"stem":"수아는 책 전체의 ⟨1/3⟩, 지호는 ⟨1/8⟩을 읽었어요. 두 사람이 읽은 쪽수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：3","correct":true},{"t":"3：8","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"9：3","mis":"M6-2-u4-X20"}],"explanation":["두 분모 3과 8의 공배수 24를 전항과 후항에 똑같이 곱해요.","⟨1/3⟩ × 24 = 8, ⟨1/8⟩ × 24 = 3이에요.","그래서 가장 간단한 자연수의 비는 8：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#8','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C4',2,'mc','auto','0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":8,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"7：2","mis":"M6-2-u4-X06"},{"t":"8：4","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.7：0.4예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 7：4예요."],"variant_rule":{"alt":[{"stem":"0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X06"},{"t":"4：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨1/2⟩을 소수 0.5로 바꾸면 0.3：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：5예요."]},{"stem":"0.9：⟨3/5⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"9：3","mis":"M6-2-u4-X06"},{"t":"4：2","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨3/5⟩을 소수 0.6으로 바꾸면 0.9：0.6이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#9','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C3',2,'mc','auto','0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X06']::text[],true,'{"seq":9,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"25：75","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"2.5：7.5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 25：75예요.","25와 75의 최대공약수 25로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."],"variant_rule":{"alt":[{"stem":"0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：5","correct":true},{"t":"12：30","mis":"M6-2-u4-X05"},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"1.2：3","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 12：30이에요.","12와 30의 최대공약수 6으로 나누면 2：5예요.","그래서 가장 간단한 자연수의 비는 2：5예요."]},{"stem":"1.25：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"125：50","mis":"M6-2-u4-X05"},{"t":"2：5","mis":"M6-2-u4-X03"},{"t":"12.5：5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 125：50이에요.","125와 50의 최대공약수 25로 나누면 5：2예요.","그래서 가장 간단한 자연수의 비는 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_basic#10','math',6,2,'u4','L03','g6_2_math_u4_L03_basic','lesson_basic','M6-2-u4-C2',3,'mc','auto','0.5：1.5에 10을 곱하면 5：15예요. 이것을 가장 간단한 자연수의 비라고 할 수 없는 까닭은 무엇인가요?',ARRAY['M6-2-u4-X06','M6-2-u4-X03']::text[],true,'{"seq":10,"concept":"M6-2-u4-C2","difficulty":3,"kind":"mc","stem":"0.5：1.5에 10을 곱하면 5：15예요. 이것을 가장 간단한 자연수의 비라고 할 수 없는 까닭은 무엇인가요?","options":[{"t":"5와 15를 5로 더 나눌 수 있어서","correct":true},{"t":"5：15는 자연수의 비가 아니어서","mis":"M6-2-u4-X06"},{"t":"10 대신 100을 곱해야 해서","mis":"M6-2-u4-X06"},{"t":"전항과 후항을 바꾸어야 해서","mis":"M6-2-u4-X03"}],"explanation":["5：15는 두 항이 모두 자연수예요.","그런데 5와 15는 공약수 5가 있어요.","5로 나누면 1：3 — 이것이 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"0.4：1.2에 10을 곱하면 4：12예요. 이것을 가장 간단한 자연수의 비라고 할 수 없는 까닭은 무엇인가요?","options":[{"t":"4와 12를 4로 더 나눌 수 있어서","correct":true},{"t":"4：12는 자연수의 비가 아니어서","mis":"M6-2-u4-X06"},{"t":"10 대신 100을 곱해야 해서","mis":"M6-2-u4-X06"},{"t":"전항과 후항을 바꾸어야 해서","mis":"M6-2-u4-X03"}],"explanation":["4：12는 두 항이 모두 자연수예요.","그런데 4와 12는 공약수 4가 있어요.","4로 나누면 1：3 — 이것이 가장 간단한 자연수의 비예요."]},{"stem":"0.6：0.9에 10을 곱하면 6：9예요. 이것을 가장 간단한 자연수의 비라고 할 수 없는 까닭은 무엇인가요?","options":[{"t":"6과 9를 3으로 더 나눌 수 있어서","correct":true},{"t":"6：9는 자연수의 비가 아니어서","mis":"M6-2-u4-X06"},{"t":"10 대신 100을 곱해야 해서","mis":"M6-2-u4-X06"},{"t":"전항과 후항을 바꾸어야 해서","mis":"M6-2-u4-X03"}],"explanation":["6：9는 두 항이 모두 자연수예요.","그런데 6과 9는 공약수 3이 있어요.","3으로 나누면 2：3 — 이것이 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#1','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C2',2,'mc','auto','84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":1,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：3","correct":true},{"t":"42：18","mis":"M6-2-u4-X05"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：36","mis":"M6-2-u4-X02"}],"explanation":["84와 36의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 7：3이에요.","7과 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"24：36","mis":"M6-2-u4-X05"},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"2：72","mis":"M6-2-u4-X02"}],"explanation":["48과 72의 최대공약수는 24예요.","전항과 후항을 똑같이 24로 나누면 2：3이에요.","2와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"45：27","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：54","mis":"M6-2-u4-X02"}],"explanation":["90과 54의 최대공약수는 18이에요.","전항과 후항을 똑같이 18로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#2','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',2,'mc','auto','⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X06"},{"t":"16：16","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨3/4⟩을 소수 0.75로 바꾸면 0.75：0.8이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 15：16이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：6","correct":true},{"t":"6：5","mis":"M6-2-u4-X03"},{"t":"1：3","mis":"M6-2-u4-X06"},{"t":"6：6","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨1/4⟩을 소수 0.25로 바꾸면 0.25：0.3이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 5：6이에요."]},{"stem":"⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-2-u4-X03"},{"t":"2：5","mis":"M6-2-u4-X06"},{"t":"5：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.4：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 4：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#3','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',3,'sa','auto','꿀 ⟨3/40⟩컵을 넣어 꿀물 ⟨3/5⟩컵을 만들었어요. 넣은 꿀의 양과 만든 꿀물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C4","difficulty":3,"kind":"sa","stem":"꿀 ⟨3/40⟩컵을 넣어 꿀물 ⟨3/5⟩컵을 만들었어요. 넣은 꿀의 양과 만든 꿀물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?","answer":["8"],"explanation":["두 분모 40과 5의 공배수 40을 곱하면 3：24예요.","두 항을 3으로 나누면 1：8이에요.","그래서 □는 8이에요."],"variant_rule":{"alt":[{"stem":"소금 ⟨1/20⟩컵을 넣어 소금물 ⟨1/2⟩컵을 만들었어요. 넣은 소금의 양과 만든 소금물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?","answer":["10"],"explanation":["두 분모 20과 2의 공배수 20을 곱하면 1：10이에요.","전항이 1이라 이미 가장 간단한 자연수의 비예요.","그래서 □는 10이에요."]},{"stem":"설탕 ⟨2/15⟩컵을 넣어 설탕물 ⟨2/3⟩컵을 만들었어요. 넣은 설탕의 양과 만든 설탕물의 양의 비를 간단한 자연수의 비 1：□로 나타내면 □는 얼마인가요?","answer":["5"],"explanation":["두 분모 15와 3의 공배수 15를 곱하면 2：10이에요.","두 항을 2로 나누면 1：5예요.","그래서 □는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#4','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',3,'error','auto','0.6：0.9를 간단한 자연수의 비로 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X19']::text[],true,'{"seq":4,"concept":"M6-2-u4-C3","difficulty":3,"kind":"error","stem":"0.6：0.9를 간단한 자연수의 비로 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「10을 곱한 6：9가 가장 간단한 자연수의 비야.」","correct":true,"mis_target":"M6-2-u4-X05"},{"t":"도윤 — 「두 항에 10을 곱하면 6：9가 돼.」","mis":"M6-2-u4-X19"},{"t":"수아 — 「6：9를 3으로 나누면 2：3이야.」","mis":"M6-2-u4-X19"},{"t":"지호 — 「가장 간단한 자연수의 비는 2：3이야.」","mis":"M6-2-u4-X19"}],"explanation":["0.6：0.9에 10을 곱하면 6：9예요.","6과 9는 아직 공약수 3으로 더 나눌 수 있어요.","그래서 가장 간단한 자연수의 비는 2：3 — 하린의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"0.4：1.2를 간단한 자연수의 비로 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「10을 곱한 4：12가 가장 간단한 자연수의 비야.」","correct":true,"mis_target":"M6-2-u4-X05"},{"t":"서아 — 「두 항에 10을 곱하면 4：12가 돼.」","mis":"M6-2-u4-X19"},{"t":"가온 — 「4：12를 4로 나누면 1：3이야.」","mis":"M6-2-u4-X19"},{"t":"나린 — 「가장 간단한 자연수의 비는 1：3이야.」","mis":"M6-2-u4-X19"}],"explanation":["0.4：1.2에 10을 곱하면 4：12예요.","4와 12는 아직 공약수 4로 더 나눌 수 있어요.","그래서 가장 간단한 자연수의 비는 1：3 — 민준의 말이 잘못되었어요."]},{"stem":"1.6：2.4를 간단한 자연수의 비로 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유진 — 「10을 곱한 16：24가 가장 간단한 자연수의 비야.」","correct":true,"mis_target":"M6-2-u4-X05"},{"t":"하린 — 「두 항에 10을 곱하면 16：24가 돼.」","mis":"M6-2-u4-X19"},{"t":"도윤 — 「16：24를 8로 나누면 2：3이야.」","mis":"M6-2-u4-X19"},{"t":"수아 — 「가장 간단한 자연수의 비는 2：3이야.」","mis":"M6-2-u4-X19"}],"explanation":["1.6：2.4에 10을 곱하면 16：24예요.","16과 24는 아직 공약수 8로 더 나눌 수 있어요.","그래서 가장 간단한 자연수의 비는 2：3 — 유진의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#5','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',3,'mc','auto','고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 지방량에 대한 단백질량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C3","difficulty":3,"kind":"mc","stem":"고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 지방량에 대한 단백질량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."],"variant_rule":{"alt":[{"stem":"고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 단백질량에 대한 지방량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：3","correct":true},{"t":"56：21","mis":"M6-2-u4-X05"},{"t":"3：8","mis":"M6-2-u4-X03"},{"t":"56：2.1","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 56：21이에요.","56과 21의 최대공약수 7로 나누면 8：3이에요.","그래서 가장 간단한 자연수의 비는 8：3이에요."]},{"stem":"고소한 해바라기씨 간식 한 봉지에 탄수화물 19 g, 단백질 2.1 g, 지방 5.6 g이 들어 있어요. 지방량에 대한 탄수화물량의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"95：28","correct":true},{"t":"190：56","mis":"M6-2-u4-X05"},{"t":"28：95","mis":"M6-2-u4-X03"},{"t":"190：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 190：56이에요.","190과 56의 최대공약수 2로 나누면 95：28이에요.","그래서 가장 간단한 자연수의 비는 95：28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#6','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C2',3,'mc','auto','간단한 자연수의 비로 나타냈을 때 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":3,"kind":"mc","stem":"간단한 자연수의 비로 나타냈을 때 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"⟨2/5⟩：⟨3/4⟩","correct":true},{"t":"1.2：1.8","mis":"M6-2-u4-X19"},{"t":"⟨1/3⟩：⟨1/2⟩","mis":"M6-2-u4-X19"},{"t":"10：15","mis":"M6-2-u4-X19"}],"explanation":["1.2：1.8, ⟨1/3⟩：⟨1/2⟩, 10：15를 간단히 하면 모두 2：3이에요.","⟨2/5⟩：⟨3/4⟩을 간단히 하면 8：15예요.","그래서 ⟨2/5⟩：⟨3/4⟩이 다른 하나예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 간단한 자연수의 비로 나타냈을 때 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"1.5：2.5","correct":true},{"t":"0.9：1.2","mis":"M6-2-u4-X19"},{"t":"⟨1/4⟩：⟨1/3⟩","mis":"M6-2-u4-X19"},{"t":"15：20","mis":"M6-2-u4-X19"}],"explanation":["0.9：1.2, ⟨1/4⟩：⟨1/3⟩, 15：20을 간단히 하면 모두 3：4예요.","1.5：2.5를 간단히 하면 3：5예요.","그래서 1.5：2.5가 다른 하나예요."]},{"stem":"이번에는 다른 보기예요. 간단한 자연수의 비로 나타냈을 때 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"⟨1/2⟩：⟨1/5⟩","correct":true},{"t":"0.4：1","mis":"M6-2-u4-X19"},{"t":"⟨1/5⟩：⟨1/2⟩","mis":"M6-2-u4-X19"},{"t":"6：15","mis":"M6-2-u4-X19"}],"explanation":["0.4：1, ⟨1/5⟩：⟨1/2⟩, 6：15를 간단히 하면 모두 2：5예요.","⟨1/2⟩：⟨1/5⟩을 간단히 하면 5：2예요.","그래서 ⟨1/2⟩：⟨1/5⟩이 다른 하나예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#7','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',3,'match','auto','비와 간단한 자연수의 비를 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C4","difficulty":3,"kind":"match","stem":"비와 간단한 자연수의 비를 알맞게 이으세요.","pairs":[{"l":"0.3：0.5","r":"3：5"},{"l":"⟨1/2⟩：⟨1/3⟩","r":"3：2"},{"l":"24：32","r":"3：4"}],"mis":"M6-2-u4-X05","explanation":["0.3：0.5에 10을 곱하면 3：5예요.","⟨1/2⟩：⟨1/3⟩에 6을 곱하면 3：2예요.","24：32를 8로 나누면 3：4예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비와 간단한 자연수의 비를 알맞게 이으세요.","pairs":[{"l":"0.7：0.2","r":"7：2"},{"l":"⟨1/4⟩：⟨1/5⟩","r":"5：4"},{"l":"18：45","r":"2：5"}],"explanation":["0.7：0.2에 10을 곱하면 7：2예요.","⟨1/4⟩：⟨1/5⟩에 20을 곱하면 5：4예요.","18：45를 9로 나누면 2：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#8','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',4,'mc','auto','어떤 비의 전항은 0.6이에요. 이 비를 간단한 자연수의 비로 나타내면 3：4예요. 후항은 얼마인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03','M6-2-u4-X06']::text[],true,'{"seq":8,"concept":"M6-2-u4-C4","difficulty":4,"kind":"mc","stem":"어떤 비의 전항은 0.6이에요. 이 비를 간단한 자연수의 비로 나타내면 3：4예요. 후항은 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"4","mis":"M6-2-u4-X07"},{"t":"0.45","mis":"M6-2-u4-X03"},{"t":"8","mis":"M6-2-u4-X06"}],"explanation":["0.6：□의 비율은 3：4와 같아야 해요.","0.6은 3의 0.2배이니 □도 4의 0.2배예요.","□ = 0.8이에요."],"variant_rule":{"alt":[{"stem":"어떤 비의 전항은 1.2예요. 이 비를 간단한 자연수의 비로 나타내면 3：5예요. 후항은 얼마인가요?","options":[{"t":"2","correct":true},{"t":"5","mis":"M6-2-u4-X07"},{"t":"0.72","mis":"M6-2-u4-X03"},{"t":"20","mis":"M6-2-u4-X06"}],"explanation":["1.2：□의 비율은 3：5와 같아야 해요.","1.2는 3의 0.4배이니 □도 5의 0.4배예요.","□ = 2예요."]},{"stem":"어떤 비의 전항은 0.8이에요. 이 비를 간단한 자연수의 비로 나타내면 2：3이에요. 후항은 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"3","mis":"M6-2-u4-X07"},{"t":"⟨8/15⟩","mis":"M6-2-u4-X03"},{"t":"12","mis":"M6-2-u4-X06"}],"explanation":["0.8：□의 비율은 2：3과 같아야 해요.","0.8은 2의 0.4배이니 □도 3의 0.4배예요.","□ = 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#9','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C3',4,'essay','teacher','해바라기씨 간식의 단백질은 2.1 g, 지방은 5.6 g이에요. 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내는 과정을 쓰고, 왜 먼저 10을 곱하는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C3","difficulty":4,"kind":"essay","stem":"해바라기씨 간식의 단백질은 2.1 g, 지방은 5.6 g이에요. 단백질량과 지방량의 비를 간단한 자연수의 비로 나타내는 과정을 쓰고, 왜 먼저 10을 곱하는지 설명해 보세요.","answer_guide":{"answer":"예: 2.1：5.6의 두 항에 10을 곱하면 21：56이고, 21과 56의 최대공약수 7로 나누면 3：8이다. 두 항이 소수 한 자리 수라서 10을 곱해야 둘 다 자연수가 되고, 두 항에 같은 수를 곱하면 비율이 변하지 않기 때문이다.","scoring_points":["21：56을 만들었는가","7로 나누어 3：8을 구했는가","10을 곱해야 두 항이 자연수가 되고 비율은 그대로라는 까닭을 썼는가"]},"explanation":["10을 곱하면 21：56이에요.","7로 나누면 3：8이에요.","같은 수를 곱해도 비율은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L03_challenge#10','math',6,2,'u4','L03','g6_2_math_u4_L03_challenge','lesson_challenge','M6-2-u4-C4',4,'essay','teacher','0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내는 방법을 두 가지로 쓰고, 두 방법의 답이 같은지 확인해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":4,"kind":"essay","stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내는 방법을 두 가지로 쓰고, 두 방법의 답이 같은지 확인해 보세요.","answer_guide":{"answer":"예: ① 후항 ⟨2/5⟩를 0.4로 바꾸면 0.7：0.4이고 10을 곱하면 7：4이다. ② 전항 0.7을 ⟨7/10⟩로 바꾸면 ⟨7/10⟩：⟨2/5⟩이고 두 분모의 공배수 10을 곱하면 7：4이다. 두 방법 모두 7：4로 같다.","scoring_points":["소수로 바꾸는 방법으로 7：4를 구했는가","분수로 바꾸는 방법으로 7：4를 구했는가","두 답이 같음을 확인했는가"]},"explanation":["⟨2/5⟩ = 0.4 → 0.7：0.4 → 7：4예요.","0.7 = ⟨7/10⟩ → 10을 곱하면 7：4예요.","두 길 모두 7：4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#1','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'mc','auto','비례식 56：21 = 8：3에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":1,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."],"variant_rule":{"alt":[{"stem":"비례식 8：5 = 16：10에서 외항은 어느 것인가요?","options":[{"t":"8과 10","correct":true},{"t":"5와 16","mis":"M6-2-u4-X10"},{"t":"8과 5","mis":"M6-2-u4-X10"},{"t":"16과 10","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","8：5 = 16：10에서 바깥쪽은 8과 10, 안쪽은 5와 16이에요.","그래서 외항은 8과 10이에요."]},{"stem":"비례식 6：8 = 9：12에서 외항은 어느 것인가요?","options":[{"t":"6과 12","correct":true},{"t":"8과 9","mis":"M6-2-u4-X10"},{"t":"6과 8","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","6：8 = 9：12에서 바깥쪽은 6과 12, 안쪽은 8과 9예요.","그래서 외항은 6과 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#2','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'mc','auto','비례식 9：12 = 3：4에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":2,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 9：12 = 3：4에서 내항은 어느 것인가요?","options":[{"t":"12와 3","correct":true},{"t":"9와 4","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"},{"t":"3과 4","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","9：12 = 3：4에서 바깥쪽은 9와 4, 안쪽은 12와 3이에요.","그래서 내항은 12와 3이에요."],"variant_rule":{"alt":[{"stem":"비례식 5：7 = 10：14에서 내항은 어느 것인가요?","options":[{"t":"7과 10","correct":true},{"t":"5와 14","mis":"M6-2-u4-X10"},{"t":"5와 7","mis":"M6-2-u4-X10"},{"t":"10과 14","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","5：7 = 10：14에서 바깥쪽은 5와 14, 안쪽은 7과 10이에요.","그래서 내항은 7과 10이에요."]},{"stem":"비례식 7：9 = 14：18에서 내항은 어느 것인가요?","options":[{"t":"9와 14","correct":true},{"t":"7과 18","mis":"M6-2-u4-X10"},{"t":"7과 9","mis":"M6-2-u4-X10"},{"t":"14와 18","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","7：9 = 14：18에서 바깥쪽은 7과 18, 안쪽은 9와 14예요.","그래서 내항은 9와 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#3','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'sa','auto','48：32의 전항과 후항을 16으로 나누어 비례식 48：32 = 3：□를 만들었어요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":1,"kind":"sa","stem":"48：32의 전항과 후항을 16으로 나누어 비례식 48：32 = 3：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["전항과 후항을 같은 수로 나누어도 비율은 같아요.","48 ÷ 16 = 3, 32 ÷ 16 = 2예요.","그래서 48：32 = 3：2예요."],"variant_rule":{"alt":[{"stem":"45：30의 전항과 후항을 15로 나누어 비례식 45：30 = 3：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["전항과 후항을 같은 수로 나누어도 비율은 같아요.","45 ÷ 15 = 3, 30 ÷ 15 = 2예요.","그래서 45：30 = 3：2예요."]},{"stem":"56：21의 전항과 후항을 7로 나누어 비례식 56：21 = 8：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["전항과 후항을 같은 수로 나누어도 비율은 같아요.","56 ÷ 7 = 8, 21 ÷ 7 = 3이에요.","그래서 56：21 = 8：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#4','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',1,'sa','auto','7：9의 전항과 후항에 2를 곱해 비례식 7：9 = 14：□를 만들었어요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u4-C5","difficulty":1,"kind":"sa","stem":"7：9의 전항과 후항에 2를 곱해 비례식 7：9 = 14：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["18"],"explanation":["전항과 후항에 같은 수를 곱해도 비율은 같아요.","7 × 2 = 14, 9 × 2 = 18이에요.","그래서 7：9 = 14：18이에요."],"variant_rule":{"alt":[{"stem":"8：5의 전항과 후항에 2를 곱해 비례식 8：5 = 16：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["전항과 후항에 같은 수를 곱해도 비율은 같아요.","8 × 2 = 16, 5 × 2 = 10이에요.","그래서 8：5 = 16：10이에요."]},{"stem":"3：4의 전항과 후항에 6을 곱해 비례식 3：4 = 18：□를 만들었어요. □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["전항과 후항에 같은 수를 곱해도 비율은 같아요.","3 × 6 = 18, 4 × 6 = 24예요.","그래서 3：4 = 18：24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#5','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"50：20 = 25：10","correct":true},{"t":"7：4 = 4：7","mis":"M6-2-u4-X09"},{"t":"5：8 = 10：24","mis":"M6-2-u4-X02"},{"t":"3：2 = 2：3","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","50：20과 25：10의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 6：15","correct":true},{"t":"2：5 = 5：2","mis":"M6-2-u4-X09"},{"t":"2：5 = 4：7","mis":"M6-2-u4-X01"},{"t":"2：5 = 4：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5와 6：15의 비율은 모두 ⟨2/5⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 4：3","correct":true},{"t":"8：6 = 6：8","mis":"M6-2-u4-X09"},{"t":"8：6 = 10：8","mis":"M6-2-u4-X01"},{"t":"8：6 = 16：6","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","8：6과 4：3의 비율은 모두 ⟨4/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#6','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','4：3과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X07','M6-2-u4-X01']::text[],true,'{"seq":6,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"4：3과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"⟨1/9⟩：⟨1/12⟩","correct":true},{"t":"6：8","mis":"M6-2-u4-X03"},{"t":"⟨1/4⟩：⟨1/3⟩","mis":"M6-2-u4-X07"},{"t":"7：6","mis":"M6-2-u4-X01"}],"explanation":["4：3의 비율은 ⟨4/3⟩예요.","⟨1/9⟩：⟨1/12⟩을 간단한 자연수의 비로 나타내면 4：3이에요.","그래서 4：3 = ⟨1/9⟩：⟨1/12⟩로 이을 수 있어요."],"variant_rule":{"alt":[{"stem":"2：5와 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"⟨1/5⟩：⟨1/2⟩","correct":true},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"⟨1/2⟩：⟨1/5⟩","mis":"M6-2-u4-X07"},{"t":"4：7","mis":"M6-2-u4-X01"}],"explanation":["2：5의 비율은 ⟨2/5⟩예요.","⟨1/5⟩：⟨1/2⟩을 간단한 자연수의 비로 나타내면 2：5예요.","그래서 2：5 = ⟨1/5⟩：⟨1/2⟩로 이을 수 있어요."]},{"stem":"3：2와 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"⟨1/2⟩：⟨1/3⟩","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"⟨1/3⟩：⟨1/2⟩","mis":"M6-2-u4-X07"},{"t":"5：4","mis":"M6-2-u4-X01"}],"explanation":["3：2의 비율은 ⟨3/2⟩이에요.","⟨1/2⟩：⟨1/3⟩을 간단한 자연수의 비로 나타내면 3：2예요.","그래서 3：2 = ⟨1/2⟩：⟨1/3⟩로 이을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#7','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'sa','auto','외항이 6과 12이고 두 비의 비율이 모두 ⟨3/4⟩인 비례식이에요. 6：□ = 9：12에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C5","difficulty":2,"kind":"sa","stem":"외항이 6과 12이고 두 비의 비율이 모두 ⟨3/4⟩인 비례식이에요. 6：□ = 9：12에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["9：12의 비율은 ⟨3/4⟩이에요.","6：□의 비율도 ⟨3/4⟩이어야 해요.","6 ÷ □ = ⟨3/4⟩이므로 □ = 8이에요."],"variant_rule":{"alt":[{"stem":"외항이 4와 15이고 두 비의 비율이 모두 ⟨2/3⟩인 비례식이에요. 4：□ = 10：15에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["10：15의 비율은 ⟨2/3⟩예요.","4：□의 비율도 ⟨2/3⟩이어야 해요.","4 ÷ □ = ⟨2/3⟩이므로 □ = 6이에요."]},{"stem":"외항이 10과 21이고 두 비의 비율이 모두 ⟨5/7⟩인 비례식이에요. 10：□ = 15：21에서 □에 알맞은 수는 얼마인가요?","answer":["14"],"explanation":["15：21의 비율은 ⟨5/7⟩예요.","10：□의 비율도 ⟨5/7⟩이어야 해요.","10 ÷ □ = ⟨5/7⟩이므로 □ = 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#8','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','비례식 8：5 = 16：10에서 외항과 내항을 바르게 짝지은 것은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],true,'{"seq":8,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 8：5 = 16：10에서 외항과 내항을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"외항 8과 10, 내항 5와 16","correct":true},{"t":"외항 5와 16, 내항 8과 10","mis":"M6-2-u4-X10"},{"t":"외항 8과 5, 내항 16과 10","mis":"M6-2-u4-X10"},{"t":"외항 8과 16, 내항 5와 10","mis":"M6-2-u4-X11"}],"explanation":["바깥쪽 두 수가 외항, 안쪽 두 수가 내항이에요.","8：5 = 16：10에서 바깥쪽은 8과 10이에요.","안쪽은 5와 16 — 내항이에요."],"variant_rule":{"alt":[{"stem":"비례식 7：9 = 14：18에서 외항과 내항을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"외항 7과 18, 내항 9와 14","correct":true},{"t":"외항 9와 14, 내항 7과 18","mis":"M6-2-u4-X10"},{"t":"외항 7과 9, 내항 14와 18","mis":"M6-2-u4-X10"},{"t":"외항 7과 14, 내항 9와 18","mis":"M6-2-u4-X11"}],"explanation":["바깥쪽 두 수가 외항, 안쪽 두 수가 내항이에요.","7：9 = 14：18에서 바깥쪽은 7과 18이에요.","안쪽은 9와 14 — 내항이에요."]},{"stem":"비례식 5：7 = 10：14에서 외항과 내항을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"외항 5와 14, 내항 7과 10","correct":true},{"t":"외항 7과 10, 내항 5와 14","mis":"M6-2-u4-X10"},{"t":"외항 5와 7, 내항 10과 14","mis":"M6-2-u4-X10"},{"t":"외항 5와 10, 내항 7과 14","mis":"M6-2-u4-X11"}],"explanation":["바깥쪽 두 수가 외항, 안쪽 두 수가 내항이에요.","5：7 = 10：14에서 바깥쪽은 5와 14예요.","안쪽은 7과 10 — 내항이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#9','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',2,'mc','auto','7：9와 비율이 같은 비를 찾아 비례식을 바르게 만든 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":9,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"7：9와 비율이 같은 비를 찾아 비례식을 바르게 만든 것은 어느 것인가요?","options":[{"t":"7：9 = 14：18","correct":true},{"t":"7：9 = 9：7","mis":"M6-2-u4-X09"},{"t":"7：9 = 9：11","mis":"M6-2-u4-X01"},{"t":"7：9 = 14：9","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","7：9와 14：18의 비율은 모두 ⟨7/9⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"3：5와 비율이 같은 비를 찾아 비례식을 바르게 만든 것은 어느 것인가요?","options":[{"t":"3：5 = 9：15","correct":true},{"t":"3：5 = 5：3","mis":"M6-2-u4-X09"},{"t":"3：5 = 5：7","mis":"M6-2-u4-X01"},{"t":"3：5 = 9：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","3：5와 9：15의 비율은 모두 ⟨3/5⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"4：7과 비율이 같은 비를 찾아 비례식을 바르게 만든 것은 어느 것인가요?","options":[{"t":"4：7 = 12：21","correct":true},{"t":"4：7 = 7：4","mis":"M6-2-u4-X09"},{"t":"4：7 = 6：9","mis":"M6-2-u4-X01"},{"t":"4：7 = 12：7","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","4：7과 12：21의 비율은 모두 ⟨4/7⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_basic#10','math',6,2,'u4','L04','g6_2_math_u4_L04_basic','lesson_basic','M6-2-u4-C5',3,'error','auto','비례식에 대해 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X19']::text[],true,'{"seq":10,"concept":"M6-2-u4-C5","difficulty":3,"kind":"error","stem":"비례식에 대해 잘못 설명한 친구는 누구인가요?","options":[{"t":"지호 — 「2：5와 24：15를 이어 2：5 = 24：15로 나타낼 수 있어.」","correct":true,"mis_target":"M6-2-u4-X09"},{"t":"유진 — 「6：8 = 9：12에서 외항은 6과 12, 내항은 8과 9야.」","mis":"M6-2-u4-X19"},{"t":"가온 — 「8：5 = 16：10에서 외항은 8과 10이야.」","mis":"M6-2-u4-X19"},{"t":"나린 — 「비례식은 비율이 같은 두 비를 등호로 이은 식이야.」","mis":"M6-2-u4-X19"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5의 비율은 ⟨2/5⟩, 24：15의 비율은 ⟨8/5⟩로 달라요 — 2：5와 24：15는 등호로 이을 수 없어요.","그래서 그 친구의 설명이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식에 대해 잘못 설명한 친구는 누구인가요?","options":[{"t":"하린 — 「3：4와 4：3은 같은 수로 되어 있으니 3：4 = 4：3이야.」","correct":true,"mis_target":"M6-2-u4-X09"},{"t":"도윤 — 「3：4 = 6：8에서 외항은 3과 8이야.」","mis":"M6-2-u4-X19"},{"t":"수아 — 「6：8의 비율도 ⟨3/4⟩이야.」","mis":"M6-2-u4-X19"},{"t":"민준 — 「비례식인지는 비율로 판단해.」","mis":"M6-2-u4-X19"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","3：4의 비율은 ⟨3/4⟩, 4：3의 비율은 ⟨4/3⟩로 달라요 — 수의 모양이 같아도 비례식이 아니에요.","그래서 그 친구의 설명이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 비례식에 대해 잘못 설명한 친구는 누구인가요?","options":[{"t":"서아 — 「5：2와 2：5는 같은 두 수로 되어 있어서 비례식을 만들 수 있어.」","correct":true,"mis_target":"M6-2-u4-X09"},{"t":"지호 — 「5：2 = 10：4에서 내항은 2와 10이야.」","mis":"M6-2-u4-X19"},{"t":"가온 — 「10：4의 비율도 ⟨5/2⟩야.」","mis":"M6-2-u4-X19"},{"t":"유진 — 「두 비의 비율을 견주어 비례식인지 알아.」","mis":"M6-2-u4-X19"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","5：2의 비율은 ⟨5/2⟩, 2：5의 비율은 ⟨2/5⟩로 달라요 — 수의 모양이 같아도 비례식이 아니에요.","그래서 그 친구의 설명이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#1','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',2,'mc','auto','비례식 56：21 = 8：3에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":1,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"비례식 56：21 = 8：3에서 내항은 어느 것인가요?","options":[{"t":"21과 8","correct":true},{"t":"56과 3","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 내항은 21과 8이에요."],"variant_rule":{"alt":[{"stem":"비례식 4：3 = 8：6에서 내항은 어느 것인가요?","options":[{"t":"3과 8","correct":true},{"t":"4와 6","mis":"M6-2-u4-X10"},{"t":"4와 3","mis":"M6-2-u4-X10"},{"t":"8과 6","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","4：3 = 8：6에서 바깥쪽은 4와 6, 안쪽은 3과 8이에요.","그래서 내항은 3과 8이에요."]},{"stem":"비례식 12：15 = 4：5에서 외항은 어느 것인가요?","options":[{"t":"12와 5","correct":true},{"t":"15와 4","mis":"M6-2-u4-X10"},{"t":"12와 15","mis":"M6-2-u4-X10"},{"t":"4와 5","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","12：15 = 4：5에서 바깥쪽은 12와 5, 안쪽은 15와 4예요.","그래서 외항은 12와 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#2','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":2,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"9：12 = 12：9","mis":"M6-2-u4-X09"},{"t":"9：12 = 10：13","mis":"M6-2-u4-X01"},{"t":"9：12 = 3：12","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","9：12와 3：4의 비율은 모두 ⟨3/4⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"6：4 = 3：2","correct":true},{"t":"6：4 = 4：6","mis":"M6-2-u4-X09"},{"t":"6：4 = 8：6","mis":"M6-2-u4-X01"},{"t":"6：4 = 3：4","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","6：4와 3：2의 비율은 모두 ⟨3/2⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"10：15 = 2：3","correct":true},{"t":"10：15 = 15：10","mis":"M6-2-u4-X09"},{"t":"10：15 = 12：17","mis":"M6-2-u4-X01"},{"t":"10：15 = 2：15","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","10：15와 2：3의 비율은 모두 ⟨2/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#3','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','⟨1/6⟩：⟨1/9⟩과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03','M6-2-u4-X20']::text[],true,'{"seq":3,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"⟨1/6⟩：⟨1/9⟩과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"300：200","correct":true},{"t":"6：9","mis":"M6-2-u4-X07"},{"t":"200：300","mis":"M6-2-u4-X03"},{"t":"1.5：1.2","mis":"M6-2-u4-X20"}],"explanation":["⟨1/6⟩：⟨1/9⟩의 비율은 ⟨3/2⟩이에요.","300：200을 간단한 자연수의 비로 나타내면 3：2예요.","그래서 ⟨1/6⟩：⟨1/9⟩ = 300：200으로 이을 수 있어요."],"variant_rule":{"alt":[{"stem":"⟨1/3⟩：⟨1/5⟩과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"1.5：0.9","correct":true},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"0.9：1.5","mis":"M6-2-u4-X03"},{"t":"1.5：1.2","mis":"M6-2-u4-X20"}],"explanation":["⟨1/3⟩：⟨1/5⟩의 비율은 ⟨5/3⟩예요.","1.5：0.9를 간단한 자연수의 비로 나타내면 5：3이에요.","그래서 ⟨1/3⟩：⟨1/5⟩ = 1.5：0.9로 이을 수 있어요."]},{"stem":"⟨1/2⟩：⟨1/8⟩과 비율이 같아서 비례식으로 이을 수 있는 비는 어느 것인가요?","options":[{"t":"2.4：0.6","correct":true},{"t":"2：8","mis":"M6-2-u4-X07"},{"t":"0.6：2.4","mis":"M6-2-u4-X03"},{"t":"2.4：0.8","mis":"M6-2-u4-X20"}],"explanation":["⟨1/2⟩：⟨1/8⟩의 비율은 4예요.","2.4：0.6을 간단한 자연수의 비로 나타내면 4：1이에요.","그래서 ⟨1/2⟩：⟨1/8⟩ = 2.4：0.6으로 이을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#4','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'ox','auto','7：4 = 4：7은 같은 수 7과 4로 이루어져 있으니 비례식이에요.',ARRAY['M6-2-u4-X09']::text[],true,'{"seq":4,"concept":"M6-2-u4-C5","difficulty":3,"kind":"ox","stem":"7：4 = 4：7은 같은 수 7과 4로 이루어져 있으니 비례식이에요.","answer":"X","reason_options":[{"t":"7：4의 비율은 ⟨7/4⟩, 4：7의 비율은 ⟨4/7⟩로 달라서","correct":true},{"t":"두 비에 같은 수가 들어 있으면 비례식이라서","mis":"M6-2-u4-X09"}],"mis":"M6-2-u4-X09","explanation":["비례식인지는 수의 모양이 아니라 비율로 판단해요.","7：4의 비율은 ⟨7/4⟩, 4：7의 비율은 ⟨4/7⟩예요.","비율이 다르니 비례식이 아니에요."],"variant_rule":{"alt":[{"stem":"3：2 = 2：3은 같은 수 3과 2로 이루어져 있으니 비례식이에요.","answer":"X","reason_options":[{"t":"3：2의 비율은 ⟨3/2⟩, 2：3의 비율은 ⟨2/3⟩로 달라서","correct":true},{"t":"두 비에 같은 수가 들어 있으면 비례식이라서","mis":"M6-2-u4-X09"}],"explanation":["비례식인지는 비율로 판단해요.","3：2의 비율은 ⟨3/2⟩, 2：3의 비율은 ⟨2/3⟩예요.","비율이 다르니 비례식이 아니에요."]},{"stem":"5：8 = 8：5는 같은 수 5와 8로 이루어져 있으니 비례식이에요.","answer":"X","reason_options":[{"t":"5：8의 비율은 ⟨5/8⟩, 8：5의 비율은 ⟨8/5⟩로 달라서","correct":true},{"t":"두 비에 같은 수가 들어 있으면 비례식이라서","mis":"M6-2-u4-X09"}],"explanation":["비례식인지는 비율로 판단해요.","5：8의 비율은 ⟨5/8⟩, 8：5의 비율은 ⟨8/5⟩이에요.","비율이 다르니 비례식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#5','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','학급 신문에 실을 철새 사진을 확대했어요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"학급 신문에 실을 철새 사진을 확대했어요. 확대하기 전 사진은 가로 8 cm, 세로 5 cm이고, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8：5 = 16：10","correct":true},{"t":"8：5 = 10：16","mis":"M6-2-u4-X03"},{"t":"8：5 = 16：5","mis":"M6-2-u4-X02"},{"t":"5：8 = 16：10","mis":"M6-2-u4-X03"}],"explanation":["확대하기 전은 8：5, 확대한 후는 16：10이에요.","두 비의 비율은 모두 1.6으로 같아요.","그래서 8：5 = 16：10이에요."],"variant_rule":{"alt":[{"stem":"학급 신문에 실을 철새 사진을 확대했어요. 확대하기 전 사진은 가로 6 cm, 세로 4 cm이고, 확대한 후 사진은 가로 9 cm, 세로 6 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6：4 = 9：6","correct":true},{"t":"6：4 = 6：9","mis":"M6-2-u4-X03"},{"t":"6：4 = 9：4","mis":"M6-2-u4-X02"},{"t":"4：6 = 9：6","mis":"M6-2-u4-X03"}],"explanation":["확대하기 전은 6：4, 확대한 후는 9：6이에요.","두 비의 비율은 모두 1.5로 같아요.","그래서 6：4 = 9：6이에요."]},{"stem":"학급 신문에 실을 철새 사진을 확대했어요. 확대하기 전 사진은 가로 10 cm, 세로 6 cm이고, 확대한 후 사진은 가로 15 cm, 세로 9 cm예요. 두 사진의 가로와 세로의 비를 비례식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10：6 = 15：9","correct":true},{"t":"10：6 = 9：15","mis":"M6-2-u4-X03"},{"t":"10：6 = 15：6","mis":"M6-2-u4-X02"},{"t":"6：10 = 15：9","mis":"M6-2-u4-X03"}],"explanation":["확대하기 전은 10：6, 확대한 후는 15：9예요.","두 비의 비율은 모두 ⟨5/3⟩로 같아요.","그래서 10：6 = 15：9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#6','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'mc','auto','외항이 4와 15, 내항이 5와 12인 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X09']::text[],true,'{"seq":6,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"외항이 4와 15, 내항이 5와 12인 비례식은 어느 것인가요?","options":[{"t":"4：5 = 12：15","correct":true},{"t":"5：4 = 15：12","mis":"M6-2-u4-X10"},{"t":"4：5 = 15：12","mis":"M6-2-u4-X09"},{"t":"12：4 = 15：5","mis":"M6-2-u4-X10"}],"explanation":["외항은 바깥쪽 두 수, 내항은 안쪽 두 수예요.","4：5 = 12：15에서 바깥쪽은 4와 15, 안쪽은 5와 12예요.","두 비의 비율도 0.8로 같아 비례식이에요."],"variant_rule":{"alt":[{"stem":"외항이 3과 20, 내항이 4와 15인 비례식은 어느 것인가요?","options":[{"t":"3：4 = 15：20","correct":true},{"t":"4：3 = 20：15","mis":"M6-2-u4-X10"},{"t":"3：4 = 20：15","mis":"M6-2-u4-X09"},{"t":"15：3 = 20：4","mis":"M6-2-u4-X10"}],"explanation":["외항은 바깥쪽 두 수, 내항은 안쪽 두 수예요.","3：4 = 15：20에서 바깥쪽은 3과 20, 안쪽은 4와 15예요.","두 비의 비율도 0.75로 같아 비례식이에요."]},{"stem":"외항이 2와 21, 내항이 3과 14인 비례식은 어느 것인가요?","options":[{"t":"2：3 = 14：21","correct":true},{"t":"3：2 = 21：14","mis":"M6-2-u4-X10"},{"t":"2：3 = 21：14","mis":"M6-2-u4-X09"},{"t":"14：2 = 21：3","mis":"M6-2-u4-X10"}],"explanation":["외항은 바깥쪽 두 수, 내항은 안쪽 두 수예요.","2：3 = 14：21에서 바깥쪽은 2와 21, 안쪽은 3과 14예요.","두 비의 비율도 ⟨2/3⟩로 같아 비례식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#7','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',3,'match','auto','비례식이 되도록 □에 알맞은 수를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C5","difficulty":3,"kind":"match","stem":"비례식이 되도록 □에 알맞은 수를 이으세요.","pairs":[{"l":"2：3 = 8：□","r":"12"},{"l":"5：4 = □：12","r":"15"},{"l":"3：7 = 9：□","r":"21"}],"mis":"M6-2-u4-X12","explanation":["2：3의 두 항에 4를 곱하면 8：12예요.","5：4의 두 항에 3을 곱하면 15：12예요.","3：7의 두 항에 3을 곱하면 9：21이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식이 되도록 □에 알맞은 수를 이으세요.","pairs":[{"l":"4：5 = 20：□","r":"25"},{"l":"2：9 = □：27","r":"6"},{"l":"6：5 = 18：□","r":"15"}],"explanation":["4：5의 두 항에 5를 곱하면 20：25예요.","2：9의 두 항에 3을 곱하면 6：27이에요.","6：5의 두 항에 3을 곱하면 18：15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#8','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'mc','auto','5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X07','M6-2-u4-X09']::text[],true,'{"seq":8,"concept":"M6-2-u4-C5","difficulty":4,"kind":"mc","stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = 2.4：2.1","mis":"M6-2-u4-X20"},{"t":"⟨1/5⟩：⟨1/6⟩ = 5：6","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"}],"explanation":["각 비의 비율을 견주어 봐요.","8：7 = 2.4：2.1의 두 비는 간단히 하면 모두 8：7이에요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"3：4 = 1.2：1.6","correct":true},{"t":"⟨1/3⟩：⟨1/4⟩ = 3：4","mis":"M6-2-u4-X07"},{"t":"3：4 = 9：8","mis":"M6-2-u4-X20"},{"t":"9：8 = 1.2：1.6","mis":"M6-2-u4-X20"}],"explanation":["각 비의 비율을 견주어 봐요.","3：4 = 1.2：1.6의 두 비는 간단히 하면 모두 3：4예요.","나머지는 비율이 서로 달라요."]},{"stem":"2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"2：5 = 0.4：1","correct":true},{"t":"⟨1/2⟩：⟨1/5⟩ = 2：5","mis":"M6-2-u4-X07"},{"t":"2：5 = 5：3","mis":"M6-2-u4-X20"},{"t":"⟨1/2⟩：⟨1/5⟩ = 0.4：1","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","2：5 = 0.4：1의 두 비는 간단히 하면 모두 2：5예요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#9','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'essay','teacher','친구가 「7：4 = 4：7은 같은 수로 되어 있으니 비례식이야」라고 했어요. 이 말이 맞는지 비율을 견주어 설명하고, 7：4와 비례식으로 이을 수 있는 비를 하나 만들어 비례식으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C5","difficulty":4,"kind":"essay","stem":"친구가 「7：4 = 4：7은 같은 수로 되어 있으니 비례식이야」라고 했어요. 이 말이 맞는지 비율을 견주어 설명하고, 7：4와 비례식으로 이을 수 있는 비를 하나 만들어 비례식으로 써 보세요.","answer_guide":{"answer":"예: 7：4의 비율은 ⟨7/4⟩, 4：7의 비율은 ⟨4/7⟩로 달라서 비례식이 아니다. 7：4의 두 항에 2를 곱한 14：8은 비율이 ⟨7/4⟩로 같으므로 7：4 = 14：8로 쓸 수 있다.","scoring_points":["두 비의 비율을 구해 다름을 보였는가","비례식이 아니라고 판단했는가","7：4와 비율이 같은 비로 비례식을 바르게 썼는가"]},"explanation":["7：4는 ⟨7/4⟩, 4：7은 ⟨4/7⟩예요.","비율이 다르니 비례식이 아니에요.","7：4 = 14：8처럼 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L04_challenge#10','math',6,2,'u4','L04','g6_2_math_u4_L04_challenge','lesson_challenge','M6-2-u4-C5',4,'essay','teacher','확대하기 전 철새 사진은 가로 8 cm, 세로 5 cm, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비로 비례식을 세우고, 외항과 내항을 각각 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C5","difficulty":4,"kind":"essay","stem":"확대하기 전 철새 사진은 가로 8 cm, 세로 5 cm, 확대한 후 사진은 가로 16 cm, 세로 10 cm예요. 두 사진의 가로와 세로의 비로 비례식을 세우고, 외항과 내항을 각각 써 보세요.","answer_guide":{"answer":"예: 두 비 8：5와 16：10은 비율이 ⟨8/5⟩로 같으므로 8：5 = 16：10이다. 외항은 바깥쪽의 8과 10, 내항은 안쪽의 5와 16이다.","scoring_points":["8：5 = 16：10을 세웠는가","외항 8과 10을 바르게 썼는가","내항 5와 16을 바르게 썼는가"]},"explanation":["8：5와 16：10은 비율이 같아요.","8：5 = 16：10이에요.","외항 8과 10, 내항 5와 16이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#1','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."]},{"stem":"비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?","answer":["24"],"explanation":["내항은 3과 8이에요.","내항의 곱은 3 × 8 = 24예요.","외항의 곱도 24로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#2','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."],"variant_rule":{"alt":[{"stem":"3：4 = 9：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 4 × 9 = 36이므로 3 × □ = 36이에요.","□ = 36 ÷ 3 = 12예요."]},{"stem":"2：5 = 6：□에서 □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 6 = 30이므로 2 × □ = 30이에요.","□ = 30 ÷ 2 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#3','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'sa','auto','3：11 = □：22에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."],"variant_rule":{"alt":[{"stem":"4：7 = □：21에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 4 × 21 = 84이므로 7 × □ = 84예요.","□ = 84 ÷ 7 = 12예요."]},{"stem":"5：9 = □：27에서 □에 알맞은 수는 얼마인가요?","answer":["15"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 5 × 27 = 135이므로 9 × □ = 135예요.","□ = 135 ÷ 9 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#4','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',1,'mc','auto','외항의 곱과 내항의 곱을 견주어 비례식인 것을 찾으면 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":1,"kind":"mc","stem":"외항의 곱과 내항의 곱을 견주어 비례식인 것을 찾으면 어느 것인가요?","options":[{"t":"5：2 = 10：4","correct":true},{"t":"7：14 = 6：13","mis":"M6-2-u4-X01"},{"t":"13：8 = 5：3","mis":"M6-2-u4-X20"},{"t":"3：5 = 4：6","mis":"M6-2-u4-X01"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","5：2와 10：4의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주어 비례식인 것을 찾으면 어느 것인가요?","options":[{"t":"4：6 = 10：15","correct":true},{"t":"4：6 = 6：4","mis":"M6-2-u4-X09"},{"t":"4：6 = 5：7","mis":"M6-2-u4-X01"},{"t":"4：6 = 8：10","mis":"M6-2-u4-X01"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","4：6과 10：15의 비율은 모두 ⟨2/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주어 비례식인 것을 찾으면 어느 것인가요?","options":[{"t":"3：8 = 9：24","correct":true},{"t":"3：8 = 8：3","mis":"M6-2-u4-X09"},{"t":"3：8 = 5：10","mis":"M6-2-u4-X01"},{"t":"3：8 = 6：8","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","3：8과 9：24의 비율은 모두 ⟨3/8⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#5','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','4：□ = 1：25에서 □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X10','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"4：□ = 1：25에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"100","correct":true},{"t":"29","mis":"M6-2-u4-X14"},{"t":"25","mis":"M6-2-u4-X10"},{"t":"200","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 4 × 25 = 100이므로 1 × □ = 100이에요.","□ = 100 ÷ 1 = 100이에요."],"variant_rule":{"alt":[{"stem":"3：□ = 1：40에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"120","correct":true},{"t":"43","mis":"M6-2-u4-X14"},{"t":"40","mis":"M6-2-u4-X10"},{"t":"240","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 40 = 120이므로 1 × □ = 120이에요.","□ = 120 ÷ 1 = 120이에요."]},{"stem":"6：□ = 1：30에서 □에 알맞은 수는 얼마인가요?","options":[{"t":"180","correct":true},{"t":"36","mis":"M6-2-u4-X14"},{"t":"30","mis":"M6-2-u4-X10"},{"t":"360","mis":"M6-2-u4-X20"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 6 × 30 = 180이므로 1 × □ = 180이에요.","□ = 180 ÷ 1 = 180이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#6','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','14：8 = 21：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X20','M6-2-u4-X10']::text[],true,'{"seq":6,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"14：8 = 21：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"외항의 곱 14 × □와 내항의 곱 8 × 21은 같아요","correct":true},{"t":"14：8과 21：□의 비율은 서로 달라요","mis":"M6-2-u4-X09"},{"t":"□에 알맞은 수는 6이에요","mis":"M6-2-u4-X20"},{"t":"내항은 14와 □예요","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 14와 □, 내항은 8과 21이에요.","14 × □ = 168이므로 □ = 12예요."],"variant_rule":{"alt":[{"stem":"6：4 = 9：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"외항의 곱 6 × □와 내항의 곱 4 × 9는 같아요","correct":true},{"t":"6：4와 9：□의 비율은 서로 달라요","mis":"M6-2-u4-X09"},{"t":"□에 알맞은 수는 3이에요","mis":"M6-2-u4-X20"},{"t":"내항은 6과 □예요","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 6과 □, 내항은 4와 9예요.","6 × □ = 36이므로 □ = 6이에요."]},{"stem":"10：4 = 15：□는 비례식이에요. 바르게 설명한 것은 어느 것인가요?","options":[{"t":"외항의 곱 10 × □와 내항의 곱 4 × 15는 같아요","correct":true},{"t":"10：4와 15：□의 비율은 서로 달라요","mis":"M6-2-u4-X09"},{"t":"□에 알맞은 수는 3이에요","mis":"M6-2-u4-X20"},{"t":"내항은 10과 □예요","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항은 10과 □, 내항은 4와 15예요.","10 × □ = 60이므로 □ = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#7','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','21：28 = 3：7은 비례식이 아니에요. 이 식의 외항의 곱은 얼마인가요?',ARRAY['M6-2-u4-X10','M6-2-u4-X11']::text[],true,'{"seq":7,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"21：28 = 3：7은 비례식이 아니에요. 이 식의 외항의 곱은 얼마인가요?","options":[{"t":"147","correct":true},{"t":"84","mis":"M6-2-u4-X10"},{"t":"63","mis":"M6-2-u4-X11"},{"t":"196","mis":"M6-2-u4-X11"}],"explanation":["외항은 바깥쪽 두 수 21과 7이에요.","외항의 곱은 21 × 7 = 147이에요.","내항의 곱은 28 × 3 = 84 — 두 곱이 달라 비례식이 아니에요."],"variant_rule":{"alt":[{"stem":"18：24 = 4：7은 비례식이 아니에요. 이 식의 외항의 곱은 얼마인가요?","options":[{"t":"126","correct":true},{"t":"96","mis":"M6-2-u4-X10"},{"t":"72","mis":"M6-2-u4-X11"},{"t":"168","mis":"M6-2-u4-X11"}],"explanation":["외항은 바깥쪽 두 수 18과 7이에요.","외항의 곱은 18 × 7 = 126이에요.","내항의 곱은 24 × 4 = 96 — 두 곱이 달라 비례식이 아니에요."]},{"stem":"25：15 = 6：4는 비례식이 아니에요. 이 식의 외항의 곱은 얼마인가요?","options":[{"t":"100","correct":true},{"t":"90","mis":"M6-2-u4-X10"},{"t":"150","mis":"M6-2-u4-X11"},{"t":"60","mis":"M6-2-u4-X11"}],"explanation":["외항은 바깥쪽 두 수 25와 4예요.","외항의 곱은 25 × 4 = 100이에요.","내항의 곱은 15 × 6 = 90 — 두 곱이 달라 비례식이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#8','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'sa','auto','8：6 = 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"8：6 = 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 8 × □ = 72예요.","□ = 72 ÷ 8 = 9예요."],"variant_rule":{"alt":[{"stem":"6：9 = 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 9 × 8 = 72이므로 6 × □ = 72예요.","□ = 72 ÷ 6 = 12예요."]},{"stem":"12：9 = 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 9 × 8 = 72이므로 12 × □ = 72예요.","□ = 72 ÷ 12 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#9','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',2,'mc','auto','4：★ = 1.2：☆에서 내항의 곱이 6이에요. ★에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u4-X12','M6-2-u4-X10']::text[],true,'{"seq":9,"concept":"M6-2-u4-C6","difficulty":2,"kind":"mc","stem":"4：★ = 1.2：☆에서 내항의 곱이 6이에요. ★에 알맞은 수는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"6","mis":"M6-2-u4-X12"},{"t":"1.2","mis":"M6-2-u4-X10"},{"t":"4","mis":"M6-2-u4-X10"}],"explanation":["내항은 안쪽의 ★과 1.2예요.","★ × 1.2 = 6이에요.","★ = 6 ÷ 1.2 = 5예요."],"variant_rule":{"alt":[{"stem":"5：★ = 0.8：☆에서 내항의 곱이 2예요. ★에 알맞은 수는 얼마인가요?","options":[{"t":"2.5","correct":true},{"t":"2","mis":"M6-2-u4-X12"},{"t":"0.8","mis":"M6-2-u4-X10"},{"t":"5","mis":"M6-2-u4-X10"}],"explanation":["내항은 안쪽의 ★과 0.8이에요.","★ × 0.8 = 2예요.","★ = 2 ÷ 0.8 = 2.5예요."]},{"stem":"3：★ = 1.5：☆에서 내항의 곱이 9예요. ★에 알맞은 수는 얼마인가요?","options":[{"t":"6","correct":true},{"t":"9","mis":"M6-2-u4-X12"},{"t":"1.5","mis":"M6-2-u4-X10"},{"t":"3","mis":"M6-2-u4-X10"}],"explanation":["내항은 안쪽의 ★과 1.5예요.","★ × 1.5 = 9예요.","★ = 9 ÷ 1.5 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_basic#10','math',6,2,'u4','L05','g6_2_math_u4_L05_basic','lesson_basic','M6-2-u4-C6',3,'mc','auto','8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":10,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."],"variant_rule":{"alt":[{"stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."]},{"stem":"6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 6 × 10으로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","6 × □ = 9 × 10이에요.","□ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#1','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',2,'sa','auto','□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."],"variant_rule":{"alt":[{"stem":"□：5 = 8：10에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 8 = 40이므로 10 × □ = 40이에요.","□ = 40 ÷ 10 = 4예요."]},{"stem":"□：7 = 12：21에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 7 × 12 = 84이므로 21 × □ = 84예요.","□ = 84 ÷ 21 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#2','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',2,'sa','auto','0.4：□ = 2：15에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"0.4：□ = 2：15에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 0.4 × 15 = 6이므로 2 × □ = 6이에요.","□ = 6 ÷ 2 = 3이에요."],"variant_rule":{"alt":[{"stem":"1.5：□ = 3：8에서 □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 1.5 × 8 = 12이므로 3 × □ = 12예요.","□ = 12 ÷ 3 = 4예요."]},{"stem":"0.6：□ = 3：10에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 0.6 × 10 = 6이므로 3 × □ = 6이에요.","□ = 6 ÷ 3 = 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#3','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'sa','auto','⟨1/2⟩：⟨1/3⟩ = □：4에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C6","difficulty":3,"kind":"sa","stem":"⟨1/2⟩：⟨1/3⟩ = □：4에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨1/2⟩ × 4 = 2이므로 ⟨1/3⟩ × □ = 2예요.","□ = 2 ÷ ⟨1/3⟩ = 6이에요."],"variant_rule":{"alt":[{"stem":"⟨1/4⟩：⟨1/5⟩ = □：8에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨1/4⟩ × 8 = 2이므로 ⟨1/5⟩ × □ = 2예요.","□ = 2 ÷ ⟨1/5⟩ = 10이에요."]},{"stem":"⟨2/3⟩：⟨1/2⟩ = □：6에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 ⟨2/3⟩ × 6 = 4이므로 ⟨1/2⟩ × □ = 4예요.","□ = 4 ÷ ⟨1/2⟩ = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#4','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'mc','auto','외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":4,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"6：9 = 3：5","correct":true},{"t":"6：9 = 2：3","mis":"M6-2-u4-X19"},{"t":"4：10 = 6：15","mis":"M6-2-u4-X19"},{"t":"12：8 = 3：2","mis":"M6-2-u4-X19"}],"explanation":["6：9 = 2：3은 18과 18, 4：10 = 6：15는 60과 60이에요.","12：8 = 3：2는 24와 24예요.","6：9 = 3：5는 외항의 곱 30, 내항의 곱 27로 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"5：4 = 15：13","correct":true},{"t":"5：4 = 15：12","mis":"M6-2-u4-X19"},{"t":"2：7 = 6：21","mis":"M6-2-u4-X19"},{"t":"9：3 = 6：2","mis":"M6-2-u4-X19"}],"explanation":["5：4 = 15：12는 60과 60, 2：7 = 6：21은 42와 42예요.","9：3 = 6：2는 18과 18이에요.","5：4 = 15：13은 외항의 곱 65, 내항의 곱 60으로 달라요."]},{"stem":"이번에는 다른 보기예요. 외항의 곱과 내항의 곱을 견주었을 때 비례식이 아닌 것은 어느 것인가요?","options":[{"t":"3：8 = 6：15","correct":true},{"t":"3：8 = 6：16","mis":"M6-2-u4-X19"},{"t":"10：4 = 5：2","mis":"M6-2-u4-X19"},{"t":"7：3 = 14：6","mis":"M6-2-u4-X19"}],"explanation":["3：8 = 6：16은 48과 48, 10：4 = 5：2는 20과 20이에요.","7：3 = 14：6은 42와 42예요.","3：8 = 6：15는 외항의 곱 45, 내항의 곱 48로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#5','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'mc','auto','비례식 3：5 = □：△에서 내항의 곱이 60이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u4-X12','M6-2-u4-X11','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"비례식 3：5 = □：△에서 내항의 곱이 60이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"12","correct":true},{"t":"60","mis":"M6-2-u4-X12"},{"t":"20","mis":"M6-2-u4-X11"},{"t":"36","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 5와 □예요.","5 × □ = 60이에요.","□ = 60 ÷ 5 = 12예요."],"variant_rule":{"alt":[{"stem":"비례식 2：7 = □：△에서 내항의 곱이 56이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"56","mis":"M6-2-u4-X12"},{"t":"28","mis":"M6-2-u4-X11"},{"t":"16","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 7과 □예요.","7 × □ = 56이에요.","□ = 56 ÷ 7 = 8이에요."]},{"stem":"비례식 4：9 = □：△에서 내항의 곱이 72예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"72","mis":"M6-2-u4-X12"},{"t":"18","mis":"M6-2-u4-X11"},{"t":"32","mis":"M6-2-u4-X20"}],"explanation":["내항은 안쪽의 9와 □예요.","9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#6','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'ox','auto','비례식 8：6 = 12：9에서 외항의 곱과 내항의 곱은 모두 72예요.',ARRAY['M6-2-u4-X11']::text[],true,'{"seq":6,"concept":"M6-2-u4-C6","difficulty":3,"kind":"ox","stem":"비례식 8：6 = 12：9에서 외항의 곱과 내항의 곱은 모두 72예요.","answer":"O","reason_options":[{"t":"8 × 9와 6 × 12가 모두 72이기 때문에","correct":true},{"t":"8 × 12와 6 × 9가 같기 때문에","mis":"M6-2-u4-X11"}],"mis":"M6-2-u4-X11","explanation":["외항은 8과 9, 내항은 6과 12예요.","8 × 9 = 72, 6 × 12 = 72예요.","두 곱이 모두 72로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 4：10 = 6：15에서 외항의 곱과 내항의 곱은 모두 60이에요.","answer":"O","reason_options":[{"t":"4 × 15와 10 × 6이 모두 60이기 때문에","correct":true},{"t":"4 × 6과 10 × 15가 같기 때문에","mis":"M6-2-u4-X11"}],"explanation":["외항은 4와 15, 내항은 10과 6이에요.","4 × 15 = 60, 10 × 6 = 60이에요.","두 곱이 모두 60으로 같아요."]},{"stem":"비례식 3：7 = 9：21에서 외항의 곱과 내항의 곱은 모두 27이에요.","answer":"X","reason_options":[{"t":"외항의 곱 3 × 21과 내항의 곱 7 × 9는 모두 63이기 때문에","correct":true},{"t":"3 × 9가 27이라 외항의 곱이 27이기 때문에","mis":"M6-2-u4-X11"}],"explanation":["외항은 3과 21, 내항은 7과 9예요.","3 × 21 = 63, 7 × 9 = 63이에요.","27은 전항끼리 곱한 값이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#7','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',3,'match','auto','비례식의 □에 알맞은 수를 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C6","difficulty":3,"kind":"match","stem":"비례식의 □에 알맞은 수를 이으세요.","pairs":[{"l":"□：4 = 6：8","r":"3"},{"l":"5：□ = 10：14","r":"7"},{"l":"9：12 = 3：□","r":"4"}],"mis":"M6-2-u4-X12","explanation":["□ × 8 = 4 × 6 = 24 → □ = 3이에요.","5 × 14 = □ × 10 = 70 → □ = 7이에요.","9 × □ = 12 × 3 = 36 → □ = 4예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비례식의 □에 알맞은 수를 이으세요.","pairs":[{"l":"□：6 = 4：8","r":"3"},{"l":"2：□ = 6：15","r":"5"},{"l":"8：10 = 12：□","r":"15"}],"explanation":["□ × 8 = 6 × 4 = 24 → □ = 3이에요.","2 × 15 = □ × 6 = 30 → □ = 5예요.","8 × □ = 10 × 12 = 120 → □ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#8','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'mc','auto','어떤 비례식에서 외항의 곱이 72이고 내항 하나가 9예요. 다른 내항은 얼마인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X12']::text[],true,'{"seq":8,"concept":"M6-2-u4-C6","difficulty":4,"kind":"mc","stem":"어떤 비례식에서 외항의 곱이 72이고 내항 하나가 9예요. 다른 내항은 얼마인가요?","options":[{"t":"8","correct":true},{"t":"63","mis":"M6-2-u4-X20"},{"t":"81","mis":"M6-2-u4-X20"},{"t":"648","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 내항의 곱도 72예요.","9 × □ = 72 — □ = 8이에요."],"variant_rule":{"alt":[{"stem":"어떤 비례식에서 외항의 곱이 84이고 내항 하나가 12예요. 다른 내항은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"72","mis":"M6-2-u4-X20"},{"t":"96","mis":"M6-2-u4-X20"},{"t":"1008","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 내항의 곱도 84예요.","12 × □ = 84 — □ = 7이에요."]},{"stem":"어떤 비례식에서 내항의 곱이 90이고 외항 하나가 6이에요. 다른 외항은 얼마인가요?","options":[{"t":"15","correct":true},{"t":"84","mis":"M6-2-u4-X20"},{"t":"96","mis":"M6-2-u4-X20"},{"t":"540","mis":"M6-2-u4-X12"}],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","그래서 외항의 곱도 90이에요.","6 × □ = 90 — □ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#9','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'essay','teacher','민지의 막대는 5 cm, 그림자는 7 cm이고, 다운이의 막대는 10 cm, 그림자는 14 cm예요. 비례식 5：7 = 10：14에서 외항의 곱과 내항의 곱을 구해 견주고, 두 곱이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C6","difficulty":4,"kind":"essay","stem":"민지의 막대는 5 cm, 그림자는 7 cm이고, 다운이의 막대는 10 cm, 그림자는 14 cm예요. 비례식 5：7 = 10：14에서 외항의 곱과 내항의 곱을 구해 견주고, 두 곱이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 외항의 곱은 5 × 14 = 70, 내항의 곱은 7 × 10 = 70으로 같다. 비례식은 두 비의 비율이 같다는 뜻이고, 10：14는 5：7의 두 항에 똑같이 2를 곱한 것이어서 외항의 곱과 내항의 곱이 모두 5 × 7 × 2가 되기 때문이다.","scoring_points":["외항의 곱 70을 구했는가","내항의 곱 70을 구해 같음을 보였는가","비율이 같다(같은 수를 곱했다)는 까닭을 썼는가"]},"explanation":["5 × 14 = 70이에요.","7 × 10 = 70이에요.","비율이 같아서 생기는 결과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L05_challenge#10','math',6,2,'u4','L05','g6_2_math_u4_L05_challenge','lesson_challenge','M6-2-u4-C6',4,'essay','teacher','사과 9개로 사과주스 4병을 만들어요. 친구가 9：4 = □：12를 「9 × 4 = □ × 12」로 풀어 □ = 3이라고 했어요. 잘못된 점을 쓰고 바르게 풀어 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C6","difficulty":4,"kind":"essay","stem":"사과 9개로 사과주스 4병을 만들어요. 친구가 9：4 = □：12를 「9 × 4 = □ × 12」로 풀어 □ = 3이라고 했어요. 잘못된 점을 쓰고 바르게 풀어 보세요.","answer_guide":{"answer":"예: 비례식에서는 외항끼리, 내항끼리 곱해야 하는데 친구는 한 비의 두 수를 곱했다. 외항의 곱 9 × 12 = 108과 내항의 곱 4 × □가 같으므로 □ = 27이다. 사과는 27개 필요하다.","scoring_points":["잘못된 점(외항끼리·내항끼리 곱하지 않음)을 썼는가","9 × 12 = 4 × □를 세웠는가","□ = 27을 구했는가"]},"explanation":["외항끼리, 내항끼리 곱해요.","9 × 12 = 108 = 4 × □예요.","□ = 27 — 사과 27개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#1','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'sa','auto','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 2：8000 = □：40000이에요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 2：8000 = □：40000이에요. □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["구하려는 값을 □라 하고 비례식 2：8000 = □：40000을 세워요.","외항의 곱 2 × 40000 = 80000이므로 8000 × □ = 80000이에요.","□ = 80000 ÷ 8000 = 10 — 10이에요."],"variant_rule":{"alt":[{"stem":"직거래 장터에서 쌀 3 kg을 9000원에 팔아요. 27000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 3：9000 = □：27000이에요. □에 알맞은 수는 얼마인가요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 3：9000 = □：27000을 세워요.","외항의 곱 3 × 27000 = 81000이므로 9000 × □ = 81000이에요.","□ = 81000 ÷ 9000 = 9 — 9예요."]},{"stem":"직거래 장터에서 쌀 4 kg을 12000원에 팔아요. 36000원으로 살 수 있는 쌀의 무게를 □ kg이라 하면 4：12000 = □：36000이에요. □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["구하려는 값을 □라 하고 비례식 4：12000 = □：36000을 세워요.","외항의 곱 4 × 36000 = 144000이므로 12000 × □ = 144000이에요.","□ = 144000 ÷ 12000 = 12 — 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#2','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'mc','auto','어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C7","difficulty":1,"kind":"mc","stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 5 kWh의 전기 에너지로 30 km를 이동해요. 20 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"120 km","correct":true},{"t":"45 km","mis":"M6-2-u4-X14"},{"t":"600 km","mis":"M6-2-u4-X12"},{"t":"240 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 5：30 = 20：□를 세워요.","내항의 곱 30 × 20 = 600이므로 5 × □ = 600이에요.","□ = 600 ÷ 5 = 120 — 120 km예요."]},{"stem":"어느 전기차는 4 kWh의 전기 에너지로 25 km를 이동해요. 12 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"75 km","correct":true},{"t":"33 km","mis":"M6-2-u4-X14"},{"t":"300 km","mis":"M6-2-u4-X12"},{"t":"150 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：25 = 12：□를 세워요.","내항의 곱 25 × 12 = 300이므로 4 × □ = 300이에요.","□ = 300 ÷ 4 = 75 — 75 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#3','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'sa','auto','계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."],"variant_rule":{"alt":[{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 240 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 240：□를 세워요.","내항의 곱 1 × 240 = 240이므로 3 × □ = 240이에요.","□ = 240 ÷ 3 = 80 — 80 g예요."]},{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 150 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["50"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 150：□를 세워요.","내항의 곱 1 × 150 = 150이므로 3 × □ = 150이에요.","□ = 150 ÷ 3 = 50 — 50 g예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#4','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',1,'mc','auto','사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":4,"concept":"M6-2-u4-C7","difficulty":1,"kind":"mc","stem":"사진 속 형의 키는 2.5 cm, 첨성대의 높이는 15 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：6","correct":true},{"t":"25：150","mis":"M6-2-u4-X05"},{"t":"6：1","mis":"M6-2-u4-X03"},{"t":"2.5：150","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 25：150이에요.","25와 150의 최대공약수 25로 나누면 1：6이에요.","그래서 가장 간단한 자연수의 비는 1：6이에요."],"variant_rule":{"alt":[{"stem":"사진 속 형의 키는 1.5 cm, 첨성대의 높이는 12 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：8","correct":true},{"t":"15：120","mis":"M6-2-u4-X05"},{"t":"8：1","mis":"M6-2-u4-X03"},{"t":"1.5：120","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 15：120이에요.","15와 120의 최대공약수 15로 나누면 1：8이에요.","그래서 가장 간단한 자연수의 비는 1：8이에요."]},{"stem":"사진 속 형의 키는 3.5 cm, 첨성대의 높이는 14 cm예요. 사진 속 형의 키와 첨성대 높이의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：4","correct":true},{"t":"35：140","mis":"M6-2-u4-X05"},{"t":"4：1","mis":"M6-2-u4-X03"},{"t":"3.5：140","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 35：140이에요.","35와 140의 최대공약수 35로 나누면 1：4예요.","그래서 가장 간단한 자연수의 비는 1：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#5','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','사진 속 형의 키와 첨성대 높이의 비가 1：6이고 형의 실제 키는 1.5 m예요. 1：6 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"사진 속 형의 키와 첨성대 높이의 비가 1：6이고 형의 실제 키는 1.5 m예요. 1：6 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 1：6 = 1.5：□를 세워요.","내항의 곱 6 × 1.5 = 9이므로 1 × □ = 9예요.","□ = 9 ÷ 1 = 9 — 9예요."],"variant_rule":{"alt":[{"stem":"사진 속 형의 키와 첨성대 높이의 비가 1：4이고 형의 실제 키는 1.5 m예요. 1：4 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["6"],"explanation":["구하려는 값을 □라 하고 비례식 1：4 = 1.5：□를 세워요.","내항의 곱 4 × 1.5 = 6이므로 1 × □ = 6이에요.","□ = 6 ÷ 1 = 6 — 6이에요."]},{"stem":"사진 속 형의 키와 첨성대 높이의 비가 1：8이고 형의 실제 키는 1.5 m예요. 1：8 = 1.5：□에서 첨성대의 실제 높이는 몇 m인가요?","answer":["12"],"explanation":["구하려는 값을 □라 하고 비례식 1：8 = 1.5：□를 세워요.","내항의 곱 8 × 1.5 = 12이므로 1 × □ = 12예요.","□ = 12 ÷ 1 = 12 — 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#6','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X14','M6-2-u4-X12']::text[],true,'{"seq":6,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."],"variant_rule":{"alt":[{"stem":"페인트 3 L로 담장 27 m²를 칠할 수 있어요. 담장 45 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"405 L","mis":"M6-2-u4-X13"},{"t":"21 L","mis":"M6-2-u4-X14"},{"t":"135 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 3：27 = □：45를 세워요.","외항의 곱 3 × 45 = 135이므로 27 × □ = 135예요.","□ = 135 ÷ 27 = 5 — 5 L예요."]},{"stem":"페인트 6 L로 담장 54 m²를 칠할 수 있어요. 담장 72 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"8 L","correct":true},{"t":"648 L","mis":"M6-2-u4-X13"},{"t":"24 L","mis":"M6-2-u4-X14"},{"t":"432 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 6：54 = □：72를 세워요.","외항의 곱 6 × 72 = 432이므로 54 × □ = 432예요.","□ = 432 ÷ 54 = 8 — 8 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#7','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."],"variant_rule":{"alt":[{"stem":"물이 일정하게 나오는 수도로 들이가 10 L인 수조를 가득 채우는 데 18초가 걸려요. 들이가 25 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["45"],"explanation":["구하려는 값을 □라 하고 비례식 10：18 = 25：□를 세워요.","내항의 곱 18 × 25 = 450이므로 10 × □ = 450이에요.","□ = 450 ÷ 10 = 45 — 45초예요."]},{"stem":"물이 일정하게 나오는 수도로 들이가 12 L인 수조를 가득 채우는 데 20초가 걸려요. 들이가 30 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["50"],"explanation":["구하려는 값을 □라 하고 비례식 12：20 = 30：□를 세워요.","내항의 곱 20 × 30 = 600이므로 12 × □ = 600이에요.","□ = 600 ÷ 12 = 50 — 50초예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#8','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'mc','auto','2：8000 = □：40000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"2：8000 = □：40000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2：8000의 전항과 후항에 5를 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"2：8000의 전항과 후항에 5를 곱한다","mis":"M6-2-u4-X19"},{"t":"2：8000의 비율과 □：40000의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["2：8000의 후항 8000에 5를 곱하면 40000이에요.","그래서 전항에도 5를 곱해 □ = 10이에요.","같은 수를 더하는 것은 비의 성질이 아니에요."],"variant_rule":{"alt":[{"stem":"3：9000 = □：27000에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"3：9000의 전항과 후항에 3을 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"3：9000의 전항과 후항에 3을 곱한다","mis":"M6-2-u4-X19"},{"t":"3：9000의 비율과 □：27000의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["3：9000의 후항 9000에 3을 곱하면 27000이에요.","그래서 전항에도 3을 곱해 □ = 9예요.","같은 수를 더하는 것은 비의 성질이 아니에요."]},{"stem":"6：40 = □：160에서 □를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"6：40의 전항과 후항에 4를 더한다","correct":true},{"t":"외항의 곱과 내항의 곱이 같음을 이용한다","mis":"M6-2-u4-X19"},{"t":"6：40의 전항과 후항에 4를 곱한다","mis":"M6-2-u4-X19"},{"t":"6：40의 비율과 □：160의 비율이 같음을 이용한다","mis":"M6-2-u4-X19"}],"explanation":["6：40의 후항 40에 4를 곱하면 160이에요.","그래서 전항에도 4를 곱해 □ = 24예요.","같은 수를 더하는 것은 비의 성질이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#9','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',2,'sa','auto','사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."],"variant_rule":{"alt":[{"stem":"사과 6개로 사과주스 4병을 만들 수 있어요. 사과주스 10병을 만들려면 사과가 몇 개 필요한가요?","answer":["15"],"explanation":["구하려는 값을 □라 하고 비례식 6：4 = □：10을 세워요.","외항의 곱 6 × 10 = 60이므로 4 × □ = 60이에요.","□ = 60 ÷ 4 = 15 — 15개예요."]},{"stem":"사과 8개로 사과주스 3병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["32"],"explanation":["구하려는 값을 □라 하고 비례식 8：3 = □：12를 세워요.","외항의 곱 8 × 12 = 96이므로 3 × □ = 96이에요.","□ = 96 ÷ 3 = 32 — 32개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_basic#10','math',6,2,'u4','L06','g6_2_math_u4_L06_basic','lesson_basic','M6-2-u4-C7',3,'mc','auto','쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":10,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."],"variant_rule":{"alt":[{"stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."]},{"stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#1','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',2,'mc','auto','어느 전기차는 7 kWh의 전기 에너지로 50 km를 이동해요. 28 kWh로는 몇 km를 갈 수 있나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"어느 전기차는 7 kWh의 전기 에너지로 50 km를 이동해요. 28 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"200 km","correct":true},{"t":"71 km","mis":"M6-2-u4-X14"},{"t":"1400 km","mis":"M6-2-u4-X12"},{"t":"400 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 7：50 = 28：□를 세워요.","내항의 곱 50 × 28 = 1400이므로 7 × □ = 1400이에요.","□ = 1400 ÷ 7 = 200 — 200 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 3 kWh의 전기 에너지로 20 km를 이동해요. 15 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"100 km","correct":true},{"t":"32 km","mis":"M6-2-u4-X14"},{"t":"300 km","mis":"M6-2-u4-X12"},{"t":"200 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 3：20 = 15：□를 세워요.","내항의 곱 20 × 15 = 300이므로 3 × □ = 300이에요.","□ = 300 ÷ 3 = 100 — 100 km예요."]},{"stem":"어느 전기차는 8 kWh의 전기 에너지로 60 km를 이동해요. 20 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"150 km","correct":true},{"t":"72 km","mis":"M6-2-u4-X14"},{"t":"1200 km","mis":"M6-2-u4-X12"},{"t":"300 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 8：60 = 20：□를 세워요.","내항의 곱 60 × 20 = 1200이므로 8 × □ = 1200이에요.","□ = 1200 ÷ 8 = 150 — 150 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#2','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',2,'sa','auto','빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C7","difficulty":2,"kind":"sa","stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."],"variant_rule":{"alt":[{"stem":"빵 반죽에 밀가루와 우유를 5：3으로 넣어요. 밀가루를 15컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["9"],"explanation":["구하려는 값을 □라 하고 비례식 5：3 = 15：□를 세워요.","내항의 곱 3 × 15 = 45이므로 5 × □ = 45예요.","□ = 45 ÷ 5 = 9 — 9컵예요."]},{"stem":"빵 반죽에 밀가루와 우유를 4：3으로 넣어요. 밀가루를 20컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["15"],"explanation":["구하려는 값을 □라 하고 비례식 4：3 = 20：□를 세워요.","내항의 곱 3 × 20 = 60이므로 4 × □ = 60이에요.","□ = 60 ÷ 4 = 15 — 15컵예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#3','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','비눗방울 용액과 물을 2：1로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 3컵이라고 했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u4-X02','M6-2-u4-X14','M6-2-u4-X13']::text[],true,'{"seq":3,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"비눗방울 용액과 물을 2：1로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 3컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 2컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 4컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["2：1에서 용액이 2컵 → 4컵이면 2배예요.","물도 2배 — 1 × 2 = 2컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."],"variant_rule":{"alt":[{"stem":"비눗방울 용액과 물을 3：1로 섞었어요. 용액을 3컵 더 넣어 6컵으로 늘리면서 친구는 물도 3컵 더 넣어 4컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 2컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 6컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["3：1에서 용액이 3컵 → 6컵이면 2배예요.","물도 2배 — 1 × 2 = 2컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."]},{"stem":"비눗방울 용액과 물을 2：3으로 섞었어요. 용액을 2컵 더 넣어 4컵으로 늘리면서 친구는 물도 2컵 더 넣어 5컵이라고 했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"같은 수를 더하면 비율이 달라져서 — 물은 6컵이어야 해요","correct":true},{"t":"용액을 더 넣으면 물은 그대로 두어야 해서","mis":"M6-2-u4-X02"},{"t":"물을 4컵 더 넣어야 해서","mis":"M6-2-u4-X14"},{"t":"용액과 물의 순서를 바꾸어야 해서","mis":"M6-2-u4-X13"}],"explanation":["2：3에서 용액이 2컵 → 4컵이면 2배예요.","물도 2배 — 3 × 2 = 6컵이에요.","같은 수만큼 더하는 것은 같은 비율로 늘린 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#4','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','공책 4권이 3600원이에요. 공책 9권은 얼마인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."],"variant_rule":{"alt":[{"stem":"공책 3권이 2400원이에요. 공책 7권은 얼마인가요?","options":[{"t":"5600원","correct":true},{"t":"2404원","mis":"M6-2-u4-X14"},{"t":"16800원","mis":"M6-2-u4-X12"},{"t":"11200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 3：2400 = 7：□를 세워요.","내항의 곱 2400 × 7 = 16800이므로 3 × □ = 16800이에요.","□ = 16800 ÷ 3 = 5600 — 5600원예요."]},{"stem":"공책 5권이 6000원이에요. 공책 8권은 얼마인가요?","options":[{"t":"9600원","correct":true},{"t":"6003원","mis":"M6-2-u4-X14"},{"t":"48000원","mis":"M6-2-u4-X12"},{"t":"19200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 5：6000 = 8：□를 세워요.","내항의 곱 6000 × 8 = 48000이므로 5 × □ = 48000이에요.","□ = 48000 ÷ 5 = 9600 — 9600원예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#5','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."],"variant_rule":{"alt":[{"stem":"지도에서 2 cm는 실제 거리 5 km예요. 지도에서 7 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"17.5 km","correct":true},{"t":"2.8 km","mis":"M6-2-u4-X13"},{"t":"10 km","mis":"M6-2-u4-X14"},{"t":"35 km","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 2：5 = 7：□를 세워요.","내항의 곱 5 × 7 = 35이므로 2 × □ = 35예요.","□ = 35 ÷ 2 = 17.5 — 17.5 km예요."]},{"stem":"지도에서 1 cm는 실제 거리 3 km예요. 지도에서 4.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"13.5 km","correct":true},{"t":"1.5 km","mis":"M6-2-u4-X13"},{"t":"6.5 km","mis":"M6-2-u4-X14"},{"t":"27 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：3 = 4.5：□를 세워요.","내항의 곱 3 × 4.5 = 13.5이므로 1 × □ = 13.5예요.","□ = 13.5 ÷ 1 = 13.5 — 13.5 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#6','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'mc','auto','6：40 = 21：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X02','M6-2-u4-X12']::text[],true,'{"seq":6,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"6：40 = 21：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"6에 3.5를 곱하면 21이니 40에도 3.5를 곱한다","correct":true},{"t":"6에 15를 더하면 21이니 40에도 15를 더한다","mis":"M6-2-u4-X14"},{"t":"6에 3.5를 곱하면 21이니 40은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"40에 21을 곱하고 6으로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","6 × 3.5 = 21이에요.","그래서 □ = 40 × 3.5 = 140이에요."],"variant_rule":{"alt":[{"stem":"2：8000 = 10：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"2에 5를 곱하면 10이니 8000에도 5를 곱한다","correct":true},{"t":"2에 8을 더하면 10이니 8000에도 8을 더한다","mis":"M6-2-u4-X14"},{"t":"2에 5를 곱하면 10이니 8000은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"8000에 10을 곱하고 2로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","2 × 5 = 10이에요.","그래서 □ = 8000 × 5 = 40000이에요."]},{"stem":"3：1 = 180：□를 비의 성질로 풀려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"3에 60을 곱하면 180이니 1에도 60을 곱한다","correct":true},{"t":"3에 177을 더하면 180이니 1에도 177을 더한다","mis":"M6-2-u4-X14"},{"t":"3에 60을 곱하면 180이니 1은 그대로 둔다","mis":"M6-2-u4-X02"},{"t":"1에 180을 곱하고 3으로 나눈다","mis":"M6-2-u4-X12"}],"explanation":["비의 성질로 풀 때는 두 항에 같은 수를 곱해요.","3 × 60 = 180이에요.","그래서 □ = 1 × 60 = 60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#7','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',3,'match','auto','문제와 알맞은 답을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C7","difficulty":3,"kind":"match","stem":"문제와 알맞은 답을 이으세요.","pairs":[{"l":"쌀 2 kg에 8000원 — 10 kg은?","r":"40000원"},{"l":"6 kWh로 40 km — 21 kWh로는?","r":"140 km"},{"l":"사과 9개로 주스 4병 — 12병에는?","r":"사과 27개"}],"mis":"M6-2-u4-X13","explanation":["2：8000 = 10：□ → □ = 40000이에요.","6：40 = 21：□ → □ = 140이에요.","9：4 = □：12 → □ = 27이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 문제와 알맞은 답을 이으세요.","pairs":[{"l":"페인트 4 L로 48 m² — 60 m²에는?","r":"5 L"},{"l":"15 L에 24초 — 50 L는?","r":"80초"},{"l":"계피와 에탄올 3：1 — 계피 180 g이면?","r":"에탄올 60 g"}],"explanation":["4：48 = □：60 → □ = 5예요.","15：24 = 50：□ → □ = 80이에요.","3：1 = 180：□ → □ = 60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#8','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'mc','auto','두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?',ARRAY['M6-2-u4-X14']::text[],true,'{"seq":8,"concept":"M6-2-u4-C7","difficulty":4,"kind":"mc","stem":"두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?","options":[{"t":"형은 12살, 동생은 9살일 때 형이 15살이 되면 동생은 몇 살인지 구하기","correct":true},{"t":"쌀 2 kg이 8000원일 때 6 kg의 값 구하기","mis":"M6-2-u4-X14"},{"t":"사과 9개로 주스 4병일 때 8병에 드는 사과 구하기","mis":"M6-2-u4-X14"},{"t":"6 kWh로 40 km를 갈 때 12 kWh로 가는 거리 구하기","mis":"M6-2-u4-X14"}],"explanation":["비례식은 한 양이 몇 배가 되면 다른 양도 똑같이 몇 배가 될 때 세워요.","나이는 해마다 똑같이 1살씩 늘어 몇 배가 되지 않아요.","그래서 나이 문제는 비례식이 아니라 덧셈으로 풀어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 양이 같은 비율로 늘지 않아 비례식을 세워 풀 수 없는 것은 어느 것인가요?","options":[{"t":"언니는 14살, 나는 10살일 때 언니가 21살이 되면 나는 몇 살인지 구하기","correct":true},{"t":"공책 4권이 3600원일 때 8권의 값 구하기","mis":"M6-2-u4-X14"},{"t":"15 L에 24초가 걸릴 때 30 L에 걸리는 시간 구하기","mis":"M6-2-u4-X14"},{"t":"페인트 4 L로 48 m²를 칠할 때 8 L로 칠하는 넓이 구하기","mis":"M6-2-u4-X14"}],"explanation":["비례식은 한 양이 몇 배가 되면 다른 양도 똑같이 몇 배가 될 때 세워요.","나이는 해마다 똑같이 1살씩 늘어 몇 배가 되지 않아요.","그래서 나이 문제는 비례식이 아니라 덧셈으로 풀어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#9','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'essay','teacher','직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 쌀을 몇 kg 살 수 있는지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"직거래 장터에서 쌀 2 kg을 8000원에 팔아요. 40000원으로 쌀을 몇 kg 살 수 있는지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 살 수 있는 쌀을 □ kg이라 하면 2：8000 = □：40000이다. ① 외항의 곱 2 × 40000 = 80000과 내항의 곱 8000 × □가 같으므로 □ = 10이다. ② 8000에 5를 곱하면 40000이므로 2에도 5를 곱해 □ = 10이다. 쌀 10 kg을 살 수 있다.","scoring_points":["2：8000 = □：40000을 세웠는가","비례식의 성질로 10을 구했는가","비의 성질로 10을 구했는가"]},"explanation":["2：8000 = □：40000이에요.","2 × 40000 = 8000 × □ → □ = 10이에요.","8000 × 5 = 40000 → □ = 2 × 5 = 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L06_challenge#10','math',6,2,'u4','L06','g6_2_math_u4_L06_challenge','lesson_challenge','M6-2-u4-C7',4,'essay','teacher','페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하는 데 필요한 페인트의 양을 비례식을 세워 구하고, 이 문제에서 비례식을 세울 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하는 데 필요한 페인트의 양을 비례식을 세워 구하고, 이 문제에서 비례식을 세울 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 필요한 페인트를 □ L라 하면 4：48 = □：60이다. 4 × 60 = 48 × □ = 240이므로 □ = 5, 페인트는 5 L가 필요하다. 칠하는 넓이가 늘면 페인트의 양도 같은 비율로 늘기 때문에 비례식을 세울 수 있다.","scoring_points":["4：48 = □：60을 세웠는가","□ = 5(L)를 구했는가","두 양이 같은 비율로 변한다는 까닭을 썼는가"]},"explanation":["4：48 = □：60이에요.","4 × 60 = 240 = 48 × □ → □ = 5예요.","넓이와 페인트 양이 같은 비율로 늘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#1','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'sa','auto','삼촌이 보내 주신 꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"삼촌이 보내 주신 꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."],"variant_rule":{"alt":[{"stem":"꿀떡 12개를 리엘이와 동생이 3：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["9"],"explanation":["비 3：1은 한 묶음이 3 + 1 = 4칸이에요.","앞쪽의 몫은 전체의 ⟨3/4⟩이에요.","12 × ⟨3/4⟩ = 9(개)예요."]},{"stem":"꿀떡 15개를 리엘이와 동생이 2：3으로 나누어 먹어요. 동생은 몇 개를 먹나요?","answer":["9"],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨3/5⟩이에요.","15 × ⟨3/5⟩ = 9(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#2','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비 3：4로 나누면 정후네 가족은 몇 개를 가지나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":2,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비 3：4로 나누면 정후네 가족은 몇 개를 가지나요?","options":[{"t":"12개","correct":true},{"t":"16개","mis":"M6-2-u4-X17"},{"t":"4개","mis":"M6-2-u4-X16"},{"t":"21개","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","28 × ⟨3/7⟩ = 12(개)예요."],"variant_rule":{"alt":[{"stem":"정후네 가족 3명과 연아네 가족 4명이 사과 35개를 땄어요. 가족 수의 비 3：4로 나누면 연아네 가족은 몇 개를 가지나요?","options":[{"t":"20개","correct":true},{"t":"15개","mis":"M6-2-u4-X17"},{"t":"5개","mis":"M6-2-u4-X16"},{"t":"25개","mis":"M6-2-u4-X20"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","35 × ⟨4/7⟩ = 20(개)예요."]},{"stem":"정후네 가족 5명과 연아네 가족 3명이 사과 24개를 땄어요. 가족 수의 비 5：3으로 나누면 정후네 가족은 몇 개를 가지나요?","options":[{"t":"15개","correct":true},{"t":"9개","mis":"M6-2-u4-X17"},{"t":"3개","mis":"M6-2-u4-X16"},{"t":"40개","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","24 × ⟨5/8⟩ = 15(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#3','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":3,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."],"variant_rule":{"alt":[{"stem":"용돈 8000원을 학용품과 장난감을 사는 데 5：3으로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"5000원","correct":true},{"t":"1600원","mis":"M6-2-u4-X15"},{"t":"3000원","mis":"M6-2-u4-X17"},{"t":"1000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","8000 × ⟨5/8⟩ = 5000(원)예요."]},{"stem":"용돈 12000원을 학용품과 장난감을 사는 데 1：2로 나누어 써요. 장난감에 쓸 용돈은 얼마인가요?","options":[{"t":"8000원","correct":true},{"t":"6000원","mis":"M6-2-u4-X15"},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"24000원","mis":"M6-2-u4-X16"}],"explanation":["비 1：2는 한 묶음이 1 + 2 = 3칸이에요.","뒤쪽의 몫은 전체의 ⟨2/3⟩예요.","12000 × ⟨2/3⟩ = 8000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#4','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',1,'mc','auto','수지와 형진이가 2800원짜리 장난감 값을 3：4로 나누어 내요. 수지는 얼마를 내야 하나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":4,"concept":"M6-2-u4-C8","difficulty":1,"kind":"mc","stem":"수지와 형진이가 2800원짜리 장난감 값을 3：4로 나누어 내요. 수지는 얼마를 내야 하나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."],"variant_rule":{"alt":[{"stem":"수지와 형진이가 3600원짜리 장난감 값을 4：5로 나누어 내요. 수지는 얼마를 내야 하나요?","options":[{"t":"1600원","correct":true},{"t":"900원","mis":"M6-2-u4-X15"},{"t":"2000원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"}],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨4/9⟩예요.","3600 × ⟨4/9⟩ = 1600(원)예요."]},{"stem":"수지와 형진이가 2000원짜리 장난감 값을 2：3으로 나누어 내요. 형진이는 얼마를 내야 하나요?","options":[{"t":"1200원","correct":true},{"t":"800원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"3000원","mis":"M6-2-u4-X16"}],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨3/5⟩이에요.","2000 × ⟨3/5⟩ = 1200(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#5','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'sa','auto','햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 72장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 72장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."],"variant_rule":{"alt":[{"stem":"햇빛 모둠은 5명, 달빛 모둠은 3명이에요. 색종이 64장을 모둠원 수에 따라 나누면 달빛 모둠은 몇 장을 받나요?","answer":["24"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","뒤쪽의 몫은 전체의 ⟨3/8⟩이에요.","64 × ⟨3/8⟩ = 24(장)예요."]},{"stem":"햇빛 모둠은 4명, 달빛 모둠은 3명이에요. 색종이 56장을 모둠원 수에 따라 나누면 햇빛 모둠은 몇 장을 받나요?","answer":["32"],"explanation":["비 4：3은 한 묶음이 4 + 3 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨4/7⟩예요.","56 × ⟨4/7⟩ = 32(장)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#6','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 7：5일 때 달리기를 한 시간은 몇 분인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 7：5일 때 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."],"variant_rule":{"alt":[{"stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 2：3일 때 달리기를 한 시간은 몇 분인가요?","options":[{"t":"24분","correct":true},{"t":"30분","mis":"M6-2-u4-X15"},{"t":"36분","mis":"M6-2-u4-X17"},{"t":"12분","mis":"M6-2-u4-X16"}],"explanation":["비 2：3은 한 묶음이 2 + 3 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨2/5⟩예요.","60 × ⟨2/5⟩ = 24(분)예요."]},{"stem":"1시간 동안 달리기와 줄넘기를 했어요. 달리기와 줄넘기를 한 시간의 비가 3：7일 때 줄넘기를 한 시간은 몇 분인가요?","options":[{"t":"42분","correct":true},{"t":"18분","mis":"M6-2-u4-X17"},{"t":"6분","mis":"M6-2-u4-X16"},{"t":"140분","mis":"M6-2-u4-X16"}],"explanation":["비 3：7은 한 묶음이 3 + 7 = 10칸이에요.","뒤쪽의 몫은 전체의 ⟨7/10⟩이에요.","60 × ⟨7/10⟩ = 42(분)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#7','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":7,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."],"variant_rule":{"alt":[{"stem":"찰흙 350 g을 2：5로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"250 g","correct":true},{"t":"70 g","mis":"M6-2-u4-X15"},{"t":"100 g","mis":"M6-2-u4-X17"},{"t":"50 g","mis":"M6-2-u4-X16"}],"explanation":["비 2：5는 한 묶음이 2 + 5 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨5/7⟩예요.","350 × ⟨5/7⟩ = 250( g)예요."]},{"stem":"찰흙 360 g을 4：5로 나누어 거북과 악어를 만들어요. 거북을 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"160 g","correct":true},{"t":"90 g","mis":"M6-2-u4-X15"},{"t":"200 g","mis":"M6-2-u4-X17"},{"t":"40 g","mis":"M6-2-u4-X16"}],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨4/9⟩예요.","360 × ⟨4/9⟩ = 160( g)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#8','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":8,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"2400 ÷ 3을 하여 800씩 나눈다","correct":true},{"t":"전체를 8칸으로 갈라 3칸과 5칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"2400 × ⟨3/8⟩과 2400 × ⟨5/8⟩를 각각 구한다","mis":"M6-2-u4-X19"},{"t":"900과 1500으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["3：5는 한 묶음이 8칸이라는 뜻이에요.","그래서 2400 × ⟨3/8⟩ = 900, 2400 × ⟨5/8⟩ = 1500이에요.","2400 ÷ 3처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#9','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',2,'mc','auto','꿀떡 9개를 2：1로 나누면 각각 몇 개인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":9,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"꿀떡 9개를 2：1로 나누면 각각 몇 개인가요?","options":[{"t":"6개와 3개","correct":true},{"t":"3개와 6개","mis":"M6-2-u4-X17"},{"t":"9개와 0개","mis":"M6-2-u4-X20"},{"t":"6개와 6개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 2 + 1 = 3칸이에요.","9 × ⟨2/3⟩ = 6, 9 × ⟨1/3⟩ = 3이에요.","두 몫을 더하면 9 — 전체와 같아요."],"variant_rule":{"alt":[{"stem":"구슬 20개를 3：2로 나누면 각각 몇 개인가요?","options":[{"t":"12개와 8개","correct":true},{"t":"8개와 12개","mis":"M6-2-u4-X17"},{"t":"16개와 4개","mis":"M6-2-u4-X20"},{"t":"12개와 12개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 3 + 2 = 5칸이에요.","20 × ⟨3/5⟩ = 12, 20 × ⟨2/5⟩ = 8이에요.","두 몫을 더하면 20 — 전체와 같아요."]},{"stem":"스티커 30장을 1：4로 나누면 각각 몇 장인가요?","options":[{"t":"6장과 24장","correct":true},{"t":"24장과 6장","mis":"M6-2-u4-X17"},{"t":"12장과 18장","mis":"M6-2-u4-X20"},{"t":"6장과 30장","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 1 + 4 = 5칸이에요.","30 × ⟨1/5⟩ = 6, 30 × ⟨4/5⟩ = 24예요.","두 몫을 더하면 30 — 전체와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_basic#10','math',6,2,'u4','L07','g6_2_math_u4_L07_basic','lesson_basic','M6-2-u4-C8',3,'ox','auto','꿀떡 9개를 2：1로 나누면 리엘이는 9 ÷ 2개를 먹어요.',ARRAY['M6-2-u4-X15']::text[],true,'{"seq":10,"concept":"M6-2-u4-C8","difficulty":3,"kind":"ox","stem":"꿀떡 9개를 2：1로 나누면 리엘이는 9 ÷ 2개를 먹어요.","answer":"X","reason_options":[{"t":"한 묶음이 2 + 1 = 3칸이라 9 × ⟨2/3⟩ = 6개를 먹기 때문에","correct":true},{"t":"비의 앞 수로 전체를 나누면 되기 때문에","mis":"M6-2-u4-X15"}],"mis":"M6-2-u4-X15","explanation":["2：1은 한 묶음이 3칸이에요.","리엘이는 전체의 ⟨2/3⟩를 먹어요.","9 × ⟨2/3⟩ = 6 — 6개예요."],"variant_rule":{"alt":[{"stem":"구슬 20개를 3：2로 나누면 앞쪽은 20 ÷ 3개를 가져요.","answer":"X","reason_options":[{"t":"한 묶음이 3 + 2 = 5칸이라 20 × ⟨3/5⟩ = 12개를 가지기 때문에","correct":true},{"t":"비의 앞 수로 전체를 나누면 되기 때문에","mis":"M6-2-u4-X15"}],"explanation":["3：2는 한 묶음이 5칸이에요.","앞쪽은 전체의 ⟨3/5⟩을 가져요.","20 × ⟨3/5⟩ = 12 — 12개예요."]},{"stem":"사탕 24개를 1：3으로 나누면 앞쪽은 24 × ⟨1/4⟩ = 6개를 가져요.","answer":"O","reason_options":[{"t":"한 묶음이 1 + 3 = 4칸이라 앞쪽은 전체의 ⟨1/4⟩이기 때문에","correct":true},{"t":"비의 앞 수로 전체를 나누면 되기 때문에","mis":"M6-2-u4-X15"}],"explanation":["1：3은 한 묶음이 4칸이에요.","앞쪽은 전체의 ⟨1/4⟩이에요.","24 × ⟨1/4⟩ = 6 — 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#1','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',2,'sa','auto','연필 45자루를 형과 동생이 4：5로 나누어 가져요. 동생은 몇 자루를 가지나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C8","difficulty":2,"kind":"sa","stem":"연필 45자루를 형과 동생이 4：5로 나누어 가져요. 동생은 몇 자루를 가지나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."],"variant_rule":{"alt":[{"stem":"연필 36자루를 형과 동생이 5：4로 나누어 가져요. 형은 몇 자루를 가지나요?","answer":["20"],"explanation":["비 5：4는 한 묶음이 5 + 4 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨5/9⟩예요.","36 × ⟨5/9⟩ = 20(자루)예요."]},{"stem":"연필 42자루를 형과 동생이 2：5로 나누어 가져요. 동생은 몇 자루를 가지나요?","answer":["30"],"explanation":["비 2：5는 한 묶음이 2 + 5 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨5/7⟩예요.","42 × ⟨5/7⟩ = 30(자루)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#2','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',2,'mc','auto','사탕 40개를 3：5로 나누면 각각 몇 개인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"사탕 40개를 3：5로 나누면 각각 몇 개인가요?","options":[{"t":"15개와 25개","correct":true},{"t":"25개와 15개","mis":"M6-2-u4-X17"},{"t":"20개와 20개","mis":"M6-2-u4-X20"},{"t":"15개와 30개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 3 + 5 = 8칸이에요.","40 × ⟨3/8⟩ = 15, 40 × ⟨5/8⟩ = 25예요.","두 몫을 더하면 40 — 전체와 같아요."],"variant_rule":{"alt":[{"stem":"사탕 48개를 5：3으로 나누면 각각 몇 개인가요?","options":[{"t":"30개와 18개","correct":true},{"t":"18개와 30개","mis":"M6-2-u4-X17"},{"t":"36개와 12개","mis":"M6-2-u4-X20"},{"t":"30개와 24개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 5 + 3 = 8칸이에요.","48 × ⟨5/8⟩ = 30, 48 × ⟨3/8⟩ = 18이에요.","두 몫을 더하면 48 — 전체와 같아요."]},{"stem":"사탕 63개를 4：3으로 나누면 각각 몇 개인가요?","options":[{"t":"36개와 27개","correct":true},{"t":"27개와 36개","mis":"M6-2-u4-X17"},{"t":"45개와 18개","mis":"M6-2-u4-X20"},{"t":"36개와 36개","mis":"M6-2-u4-X20"}],"explanation":["한 묶음은 4 + 3 = 7칸이에요.","63 × ⟨4/7⟩ = 36, 63 × ⟨3/7⟩ = 27이에요.","두 몫을 더하면 63 — 전체와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#3','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','어떤 수를 3：4로 비례배분했더니 작은 쪽이 18이 되었어요. 처음 수는 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X15','M6-2-u4-X16']::text[],true,'{"seq":3,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"어떤 수를 3：4로 비례배분했더니 작은 쪽이 18이 되었어요. 처음 수는 얼마인가요?","options":[{"t":"42","correct":true},{"t":"24","mis":"M6-2-u4-X17"},{"t":"54","mis":"M6-2-u4-X15"},{"t":"72","mis":"M6-2-u4-X16"}],"explanation":["3：4에서 작은 쪽은 한 묶음 7칸 가운데 3칸이에요.","3칸이 18이니 1칸은 6이에요.","전체 7칸은 42예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 2：5로 비례배분했더니 작은 쪽이 14가 되었어요. 처음 수는 얼마인가요?","options":[{"t":"49","correct":true},{"t":"35","mis":"M6-2-u4-X17"},{"t":"28","mis":"M6-2-u4-X15"},{"t":"70","mis":"M6-2-u4-X16"}],"explanation":["2：5에서 작은 쪽은 한 묶음 7칸 가운데 2칸이에요.","2칸이 14니 1칸은 7이에요.","전체 7칸은 49예요."]},{"stem":"어떤 수를 5：3으로 비례배분했더니 작은 쪽이 21이 되었어요. 처음 수는 얼마인가요?","options":[{"t":"56","correct":true},{"t":"35","mis":"M6-2-u4-X17"},{"t":"63","mis":"M6-2-u4-X15"},{"t":"105","mis":"M6-2-u4-X16"}],"explanation":["5：3에서 작은 쪽은 한 묶음 8칸 가운데 3칸이에요.","3칸이 21이니 1칸은 7이에요.","전체 8칸은 56이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#4','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','용돈을 형과 동생이 5：3으로 나누었더니 형이 동생보다 2000원 더 많았어요. 처음 용돈은 모두 얼마인가요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":4,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"용돈을 형과 동생이 5：3으로 나누었더니 형이 동생보다 2000원 더 많았어요. 처음 용돈은 모두 얼마인가요?","options":[{"t":"8000원","correct":true},{"t":"10000원","mis":"M6-2-u4-X15"},{"t":"5000원","mis":"M6-2-u4-X17"},{"t":"16000원","mis":"M6-2-u4-X20"}],"explanation":["형은 5칸, 동생은 3칸 — 2칸만큼 차이가 나요.","2칸이 2000원이니 1칸은 1000원이에요.","전체 8칸은 8000원이에요."],"variant_rule":{"alt":[{"stem":"용돈을 형과 동생이 4：1로 나누었더니 형이 동생보다 3000원 더 많았어요. 처음 용돈은 모두 얼마인가요?","options":[{"t":"5000원","correct":true},{"t":"12000원","mis":"M6-2-u4-X15"},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"10000원","mis":"M6-2-u4-X20"}],"explanation":["형은 4칸, 동생은 1칸 — 3칸만큼 차이가 나요.","3칸이 3000원이니 1칸은 1000원이에요.","전체 5칸은 5000원이에요."]},{"stem":"용돈을 형과 동생이 7：4로 나누었더니 형이 동생보다 1500원 더 많았어요. 처음 용돈은 모두 얼마인가요?","options":[{"t":"5500원","correct":true},{"t":"10500원","mis":"M6-2-u4-X15"},{"t":"3500원","mis":"M6-2-u4-X17"},{"t":"11000원","mis":"M6-2-u4-X20"}],"explanation":["형은 7칸, 동생은 4칸 — 3칸만큼 차이가 나요.","3칸이 1500원이니 1칸은 500원이에요.","전체 11칸은 5500원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#5','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'ox','auto','전체를 가：나로 비례배분하면 두 몫의 합은 언제나 전체와 같아요.',ARRAY['M6-2-u4-X16']::text[],true,'{"seq":5,"concept":"M6-2-u4-C8","difficulty":3,"kind":"ox","stem":"전체를 가：나로 비례배분하면 두 몫의 합은 언제나 전체와 같아요.","answer":"O","reason_options":[{"t":"전체를 (가+나)칸으로 갈라 가칸과 나칸으로 나누기 때문에","correct":true},{"t":"가 × 나만큼 나누기 때문에","mis":"M6-2-u4-X16"}],"mis":"M6-2-u4-X16","explanation":["비례배분은 전체를 (가+나)칸으로 갈라요.","두 몫은 가칸과 나칸이에요.","가칸 + 나칸 = (가+나)칸 — 전체와 같아요."],"variant_rule":{"alt":[{"stem":"24를 1：3으로 비례배분하면 24 × ⟨1/3⟩ = 8과 나머지 16이에요.","answer":"X","reason_options":[{"t":"한 묶음이 1 + 3 = 4칸이라 24 × ⟨1/4⟩ = 6과 18이기 때문에","correct":true},{"t":"(가 ÷ 나)를 곱해 앞쪽 몫을 구하기 때문에","mis":"M6-2-u4-X16"}],"explanation":["1：3은 한 묶음이 4칸이에요.","앞쪽은 ⟨1/4⟩, 뒤쪽은 ⟨3/4⟩이에요.","24 × ⟨1/4⟩ = 6, 24 × ⟨3/4⟩ = 18이에요."]},{"stem":"35를 2：5로 비례배분하면 35 × ⟨2/5⟩ = 14와 나머지 21이에요.","answer":"X","reason_options":[{"t":"한 묶음이 2 + 5 = 7칸이라 35 × ⟨2/7⟩ = 10과 25이기 때문에","correct":true},{"t":"(가 ÷ 나)를 곱해 앞쪽 몫을 구하기 때문에","mis":"M6-2-u4-X16"}],"explanation":["2：5는 한 묶음이 7칸이에요.","앞쪽은 ⟨2/7⟩, 뒤쪽은 ⟨5/7⟩예요.","35 × ⟨2/7⟩ = 10, 35 × ⟨5/7⟩ = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#6','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'mc','auto','구슬 60개를 세 사람이 1：2：3으로 나누어 가져요. 셋째 사람은 몇 개를 가지나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X16','M6-2-u4-X20']::text[],true,'{"seq":6,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"구슬 60개를 세 사람이 1：2：3으로 나누어 가져요. 셋째 사람은 몇 개를 가지나요?","options":[{"t":"30개","correct":true},{"t":"20개","mis":"M6-2-u4-X15"},{"t":"10개","mis":"M6-2-u4-X16"},{"t":"40개","mis":"M6-2-u4-X20"}],"explanation":["1：2：3은 한 묶음이 6칸이에요.","셋째 사람은 3칸 — 전체의 ⟨3/6⟩이에요.","60 × ⟨3/6⟩ = 30(개)예요."],"variant_rule":{"alt":[{"stem":"구슬 48개를 세 사람이 1：3：4로 나누어 가져요. 둘째 사람은 몇 개를 가지나요?","options":[{"t":"18개","correct":true},{"t":"16개","mis":"M6-2-u4-X15"},{"t":"6개","mis":"M6-2-u4-X16"},{"t":"24개","mis":"M6-2-u4-X20"}],"explanation":["1：3：4는 한 묶음이 8칸이에요.","둘째 사람은 3칸 — 전체의 ⟨3/8⟩이에요.","48 × ⟨3/8⟩ = 18(개)예요."]},{"stem":"구슬 72개를 세 사람이 2：3：4로 나누어 가져요. 첫째 사람은 몇 개를 가지나요?","options":[{"t":"16개","correct":true},{"t":"24개","mis":"M6-2-u4-X15"},{"t":"8개","mis":"M6-2-u4-X16"},{"t":"36개","mis":"M6-2-u4-X15"}],"explanation":["2：3：4는 한 묶음이 9칸이에요.","첫째 사람은 2칸 — 전체의 ⟨2/9⟩예요.","72 × ⟨2/9⟩ = 16(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#7','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',3,'match','auto','20을 비례배분했을 때 앞쪽 몫을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C8","difficulty":3,"kind":"match","stem":"20을 비례배분했을 때 앞쪽 몫을 이으세요.","pairs":[{"l":"20을 1：4로","r":"4"},{"l":"20을 2：3으로","r":"8"},{"l":"20을 3：1로","r":"15"}],"mis":"M6-2-u4-X16","explanation":["1：4는 5칸 — 20 × ⟨1/5⟩ = 4예요.","2：3은 5칸 — 20 × ⟨2/5⟩ = 8이에요.","3：1은 4칸 — 20 × ⟨3/4⟩ = 15예요."],"variant_rule":{"alt":[{"stem":"30을 비례배분했을 때 앞쪽 몫을 이으세요.","pairs":[{"l":"30을 1：2로","r":"10"},{"l":"30을 3：2로","r":"18"},{"l":"30을 1：5로","r":"5"}],"explanation":["1：2는 3칸 — 30 × ⟨1/3⟩ = 10이에요.","3：2는 5칸 — 30 × ⟨3/5⟩ = 18이에요.","1：5는 6칸 — 30 × ⟨1/6⟩ = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#8','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'mc','auto','둘레가 48 cm인 직사각형의 가로와 세로의 비가 5：3이에요. 가로는 몇 cm인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":8,"concept":"M6-2-u4-C8","difficulty":4,"kind":"mc","stem":"둘레가 48 cm인 직사각형의 가로와 세로의 비가 5：3이에요. 가로는 몇 cm인가요?","options":[{"t":"15 cm","correct":true},{"t":"30 cm","mis":"M6-2-u4-X20"},{"t":"9 cm","mis":"M6-2-u4-X17"},{"t":"3 cm","mis":"M6-2-u4-X16"}],"explanation":["둘레는 (가로 + 세로) × 2라서 가로와 세로의 합은 48 ÷ 2 = 24 (cm)예요.","24를 5：3으로 비례배분해요.","24 × ⟨5/8⟩ = 15 (cm)예요."],"variant_rule":{"alt":[{"stem":"둘레가 56 cm인 직사각형의 가로와 세로의 비가 3：4예요. 세로는 몇 cm인가요?","options":[{"t":"16 cm","correct":true},{"t":"32 cm","mis":"M6-2-u4-X20"},{"t":"12 cm","mis":"M6-2-u4-X17"},{"t":"7 cm","mis":"M6-2-u4-X15"}],"explanation":["둘레는 (가로 + 세로) × 2라서 가로와 세로의 합은 56 ÷ 2 = 28 (cm)예요.","28을 3：4로 비례배분해요.","28 × ⟨4/7⟩ = 16 (cm)예요."]},{"stem":"둘레가 60 cm인 직사각형의 가로와 세로의 비가 7：3이에요. 가로는 몇 cm인가요?","options":[{"t":"21 cm","correct":true},{"t":"42 cm","mis":"M6-2-u4-X20"},{"t":"9 cm","mis":"M6-2-u4-X17"},{"t":"3 cm","mis":"M6-2-u4-X16"}],"explanation":["둘레는 (가로 + 세로) × 2라서 가로와 세로의 합은 60 ÷ 2 = 30 (cm)예요.","30을 7：3으로 비례배분해요.","30 × ⟨7/10⟩ = 21 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#9','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'essay','teacher','1200을 2：3으로 비례배분하려는데 친구가 1200 ÷ 2 = 600으로 계산했어요. 이 방법이 왜 잘못되었는지 쓰고, 바르게 비례배분해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C8","difficulty":4,"kind":"essay","stem":"1200을 2：3으로 비례배분하려는데 친구가 1200 ÷ 2 = 600으로 계산했어요. 이 방법이 왜 잘못되었는지 쓰고, 바르게 비례배분해 보세요.","answer_guide":{"answer":"예: 2：3은 한 묶음이 2 + 3 = 5칸이라는 뜻이어서 전체를 5칸으로 갈라야 한다. 1200 ÷ 2는 한 항으로만 나눈 것이다. 바르게 하면 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이다.","scoring_points":["한 묶음이 5칸임을 밝혔는가","480을 구했는가","720을 구했는가"]},"explanation":["2：3은 5칸이에요.","1200 × ⟨2/5⟩ = 480이에요.","1200 × ⟨3/5⟩ = 720이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L07_challenge#10','math',6,2,'u4','L07','g6_2_math_u4_L07_challenge','lesson_challenge','M6-2-u4-C8',4,'essay','teacher','정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비로 나누면 두 가족이 각각 몇 개씩 가지는지 구하고, 구한 두 몫이 맞는지 확인하는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C8","difficulty":4,"kind":"essay","stem":"정후네 가족 3명과 연아네 가족 4명이 사과 28개를 땄어요. 가족 수의 비로 나누면 두 가족이 각각 몇 개씩 가지는지 구하고, 구한 두 몫이 맞는지 확인하는 방법을 써 보세요.","answer_guide":{"answer":"예: 3：4는 한 묶음이 7칸이므로 정후네는 28 × ⟨3/7⟩ = 12개, 연아네는 28 × ⟨4/7⟩ = 16개이다. 두 몫을 더하면 28로 전체와 같고, 12：16을 4로 나누면 3：4가 되어 맞다.","scoring_points":["12개를 구했는가","16개를 구했는가","합이 28·비가 3：4임으로 확인했는가"]},"explanation":["3：4는 7칸이에요.","28 × ⟨3/7⟩ = 12, 28 × ⟨4/7⟩ = 16이에요.","12 + 16 = 28, 12：16 = 3：4로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#1','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원을 회사와 사용자가 7：3으로 나누어요. 두 친구가 얻은 수익은 몇 원인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16','M6-2-u4-X20']::text[],true,'{"seq":1,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 500000원을 회사와 사용자가 7：3으로 나누어요. 두 친구가 얻은 수익은 몇 원인가요?","options":[{"t":"150000원","correct":true},{"t":"350000원","mis":"M6-2-u4-X17"},{"t":"50000원","mis":"M6-2-u4-X16"},{"t":"200000원","mis":"M6-2-u4-X20"}],"explanation":["비 7：3은 한 묶음이 7 + 3 = 10칸이에요.","뒤쪽의 몫은 전체의 ⟨3/10⟩이에요.","500000 × ⟨3/10⟩ = 150000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 600000원을 회사와 사용자가 7：3으로 나누어요. 두 친구가 얻은 수익은 몇 원인가요?","options":[{"t":"180000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X15"},{"t":"420000원","mis":"M6-2-u4-X17"},{"t":"60000원","mis":"M6-2-u4-X16"}],"explanation":["비 7：3은 한 묶음이 7 + 3 = 10칸이에요.","뒤쪽의 몫은 전체의 ⟨3/10⟩이에요.","600000 × ⟨3/10⟩ = 180000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품으로 얻은 전체 수익 400000원을 회사와 사용자가 3：2로 나누어요. 두 친구가 얻은 수익은 몇 원인가요?","options":[{"t":"160000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X15"},{"t":"240000원","mis":"M6-2-u4-X17"},{"t":"80000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨2/5⟩예요.","400000 × ⟨2/5⟩ = 160000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#2','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','태리는 12000원, 동하는 8000원의 사용료를 냈어요. 두 사람이 낸 금액의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":2,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"태리는 12000원, 동하는 8000원의 사용료를 냈어요. 두 사람이 낸 금액의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"6000：4000","mis":"M6-2-u4-X05"},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"3：8000","mis":"M6-2-u4-X02"}],"explanation":["12000과 8000의 최대공약수는 4000이에요.","전항과 후항을 똑같이 4000으로 나누면 3：2예요.","3과 2는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"태리는 10000원, 동하는 6000원의 사용료를 냈어요. 두 사람이 낸 금액의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"5000：3000","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：6000","mis":"M6-2-u4-X02"}],"explanation":["10000과 6000의 최대공약수는 2000이에요.","전항과 후항을 똑같이 2000으로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"태리는 15000원, 동하는 6000원의 사용료를 냈어요. 두 사람이 낸 금액의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"7500：3000","mis":"M6-2-u4-X05"},{"t":"2：5","mis":"M6-2-u4-X03"},{"t":"5：6000","mis":"M6-2-u4-X02"}],"explanation":["15000과 6000의 최대공약수는 3000이에요.","전항과 후항을 똑같이 3000으로 나누면 5：2예요.","5와 2는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#3','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','두 친구가 얻은 150000원을 낸 사용료의 비 3：2로 나누면 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":3,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"두 친구가 얻은 150000원을 낸 사용료의 비 3：2로 나누면 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"50000원","mis":"M6-2-u4-X15"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","150000 × ⟨3/5⟩ = 90000(원)예요."],"variant_rule":{"alt":[{"stem":"두 친구가 얻은 160000원을 낸 사용료의 비 5：3으로 나누면 태리는 몇 원을 받나요?","options":[{"t":"100000원","correct":true},{"t":"32000원","mis":"M6-2-u4-X15"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"20000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","160000 × ⟨5/8⟩ = 100000(원)예요."]},{"stem":"두 친구가 얻은 180000원을 낸 사용료의 비 5：4로 나누면 태리는 몇 원을 받나요?","options":[{"t":"100000원","correct":true},{"t":"36000원","mis":"M6-2-u4-X15"},{"t":"80000원","mis":"M6-2-u4-X17"},{"t":"20000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：4는 한 묶음이 5 + 4 = 9칸이에요.","앞쪽의 몫은 전체의 ⟨5/9⟩예요.","180000 × ⟨5/9⟩ = 100000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#4','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',1,'mc','auto','태리는 그림 4장, 동하는 2장을 그렸어요. 그린 그림 수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":4,"concept":"M6-2-u4-C9","difficulty":1,"kind":"mc","stem":"태리는 그림 4장, 동하는 2장을 그렸어요. 그린 그림 수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：2","mis":"M6-2-u4-X02"},{"t":"4：1","mis":"M6-2-u4-X02"}],"explanation":["4와 2의 최대공약수는 2예요.","전항과 후항을 똑같이 2로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"태리는 그림 6장, 동하는 4장을 그렸어요. 그린 그림 수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"3：4","mis":"M6-2-u4-X02"},{"t":"6：2","mis":"M6-2-u4-X02"}],"explanation":["6과 4의 최대공약수는 2예요.","전항과 후항을 똑같이 2로 나누면 3：2예요.","3과 2는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"태리는 그림 8장, 동하는 6장을 그렸어요. 그린 그림 수의 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：3","correct":true},{"t":"3：4","mis":"M6-2-u4-X03"},{"t":"4：6","mis":"M6-2-u4-X02"},{"t":"8：3","mis":"M6-2-u4-X02"}],"explanation":["8과 6의 최대공약수는 2예요.","전항과 후항을 똑같이 2로 나누면 4：3이에요.","4와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#5','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','두 친구가 얻은 150000원을 그린 그림 수의 비 2：1로 나누면 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":5,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"두 친구가 얻은 150000원을 그린 그림 수의 비 2：1로 나누면 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"150000원","mis":"M6-2-u4-X15"},{"t":"100000원","mis":"M6-2-u4-X17"},{"t":"75000원","mis":"M6-2-u4-X16"}],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","뒤쪽의 몫은 전체의 ⟨1/3⟩이에요.","150000 × ⟨1/3⟩ = 50000(원)예요."],"variant_rule":{"alt":[{"stem":"두 친구가 얻은 150000원을 그린 그림 수의 비 3：2로 나누면 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"75000원","mis":"M6-2-u4-X15"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","뒤쪽의 몫은 전체의 ⟨2/5⟩예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]},{"stem":"두 친구가 얻은 140000원을 그린 그림 수의 비 4：3으로 나누면 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"80000원","mis":"M6-2-u4-X17"},{"t":"20000원","mis":"M6-2-u4-X16"},{"t":"105000원","mis":"M6-2-u4-X16"}],"explanation":["비 4：3은 한 묶음이 4 + 3 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨3/7⟩이에요.","140000 × ⟨3/7⟩ = 60000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#6','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','두 친구가 받은 150000원을 낸 사용료(태리 12000원, 동하 8000원)의 비와 그린 그림 수(태리 4장, 동하 2장)의 비로 각각 나누어 견주었어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M6-2-u4-X19','M6-2-u4-X17']::text[],true,'{"seq":6,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"두 친구가 받은 150000원을 낸 사용료(태리 12000원, 동하 8000원)의 비와 그린 그림 수(태리 4장, 동하 2장)의 비로 각각 나누어 견주었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"사용료의 비로 나누면 태리가 90000원, 그림 수의 비로 나누면 100000원이에요","correct":true},{"t":"두 방법으로 나눈 결과가 서로 같아요","mis":"M6-2-u4-X19"},{"t":"그림 수의 비로 나누면 동하가 태리보다 많이 받아요","mis":"M6-2-u4-X17"},{"t":"사용료의 비로 나누면 동하가 90000원을 받아요","mis":"M6-2-u4-X17"}],"explanation":["사용료의 비 3：2 — 태리 90000원, 동하 60000원이에요.","그림 수의 비 2：1 — 태리 100000원, 동하 50000원이에요.","나누는 비가 달라 결과도 달라요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 160000원을 낸 사용료(태리 10000원, 동하 6000원)의 비와 그린 그림 수(태리 6장, 동하 2장)의 비로 각각 나누어 견주었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"사용료의 비로 나누면 태리가 100000원, 그림 수의 비로 나누면 120000원이에요","correct":true},{"t":"두 방법으로 나눈 결과가 서로 같아요","mis":"M6-2-u4-X19"},{"t":"그림 수의 비로 나누면 동하가 태리보다 많이 받아요","mis":"M6-2-u4-X17"},{"t":"사용료의 비로 나누면 동하가 100000원을 받아요","mis":"M6-2-u4-X17"}],"explanation":["사용료의 비 5：3 — 태리 100000원, 동하 60000원이에요.","그림 수의 비 3：1 — 태리 120000원, 동하 40000원이에요.","나누는 비가 달라 결과도 달라요."]},{"stem":"두 친구가 받은 180000원을 낸 사용료(태리 8000원, 동하 4000원)의 비와 그린 그림 수(태리 5장, 동하 4장)의 비로 각각 나누어 견주었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"사용료의 비로 나누면 태리가 120000원, 그림 수의 비로 나누면 100000원이에요","correct":true},{"t":"두 방법으로 나눈 결과가 서로 같아요","mis":"M6-2-u4-X19"},{"t":"그림 수의 비로 나누면 동하가 태리보다 많이 받아요","mis":"M6-2-u4-X17"},{"t":"사용료의 비로 나누면 동하가 120000원을 받아요","mis":"M6-2-u4-X17"}],"explanation":["사용료의 비 2：1 — 태리 120000원, 동하 60000원이에요.","그림 수의 비 5：4 — 태리 100000원, 동하 80000원이에요.","나누는 비가 달라 결과도 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#7','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'sa','auto','다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액의 비로 나누면 다현이는 몇 장을 가져야 하나요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":2,"kind":"sa","stem":"다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액의 비로 나누면 다현이는 몇 장을 가져야 하나요?","answer":["25"],"explanation":["낸 금액의 비 1500：600을 간단히 하면 5：2예요.","한 묶음은 7칸 — 전체의 ⟨5/7⟩예요.","35 × ⟨5/7⟩ = 25(장)예요."],"variant_rule":{"alt":[{"stem":"다현이가 1200원, 윤수가 800원을 내서 도화지 40장을 샀어요. 낸 금액의 비로 나누면 다현이는 몇 장을 가져야 하나요?","answer":["24"],"explanation":["낸 금액의 비 1200：800을 간단히 하면 3：2예요.","한 묶음은 5칸 — 전체의 ⟨3/5⟩이에요.","40 × ⟨3/5⟩ = 24(장)예요."]},{"stem":"다현이가 2000원, 윤수가 1000원을 내서 도화지 36장을 샀어요. 낸 금액의 비로 나누면 윤수는 몇 장을 가져야 하나요?","answer":["12"],"explanation":["낸 금액의 비 2000：1000을 간단히 하면 2：1이에요.","한 묶음은 3칸 — 전체의 ⟨1/3⟩이에요.","36 × ⟨1/3⟩ = 12(장)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#8','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":8,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"120000원","correct":true},{"t":"400000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"180000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000(원)예요.","12000원：6000원을 간단히 하면 2：1이에요.","180000 × ⟨2/3⟩ = 120000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#9','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',2,'mc','auto','수익을 나누는 방법에 대한 생각으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":9,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"수익을 나누는 방법에 대한 생각으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"나누는 방법이 달라도 각자 받는 금액은 언제나 같다","correct":true},{"t":"작품에 낸 금액만큼 나누면 공정하다고 생각할 수 있다","mis":"M6-2-u4-X19"},{"t":"그린 그림 수만큼 나누면 공정하다고 생각할 수 있다","mis":"M6-2-u4-X19"},{"t":"어느 방법이 공정한지는 사람마다 생각이 다를 수 있다","mis":"M6-2-u4-X19"}],"explanation":["같은 수익이라도 어떤 비로 나누느냐에 따라 각자의 몫이 달라져요.","낸 금액으로 나누든 만든 수로 나누든 공정하다고 볼 수 있는 까닭이 있어요.","「방법이 달라도 몫은 언제나 같다」는 말은 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수익을 나누는 방법에 대한 생각으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"낸 금액이 많은 사람은 언제나 그림도 많이 그린다","correct":true},{"t":"낸 금액의 비로 나누는 방법이 있다","mis":"M6-2-u4-X19"},{"t":"그린 그림 수의 비로 나누는 방법이 있다","mis":"M6-2-u4-X19"},{"t":"나누기 전에 기준을 함께 정하면 좋다","mis":"M6-2-u4-X19"}],"explanation":["같은 수익이라도 어떤 비로 나누느냐에 따라 각자의 몫이 달라져요.","낸 금액으로 나누든 만든 수로 나누든 공정하다고 볼 수 있는 까닭이 있어요.","「방법이 달라도 몫은 언제나 같다」는 말은 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 수익을 나누는 방법에 대한 생각으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"비례배분을 하면 두 사람의 몫은 언제나 똑같다","correct":true},{"t":"비가 다르면 두 사람의 몫도 달라진다","mis":"M6-2-u4-X19"},{"t":"어떤 기준으로 나눌지 먼저 정해야 한다","mis":"M6-2-u4-X19"},{"t":"두 사람의 몫을 더하면 나눈 전체 금액이 된다","mis":"M6-2-u4-X19"}],"explanation":["같은 수익이라도 어떤 비로 나누느냐에 따라 각자의 몫이 달라져요.","낸 금액으로 나누든 만든 수로 나누든 공정하다고 볼 수 있는 까닭이 있어요.","「방법이 달라도 몫은 언제나 같다」는 말은 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_basic#10','math',6,2,'u4','L08','g6_2_math_u4_L08_basic','lesson_basic','M6-2-u4-C9',3,'ox','auto','두 친구가 받은 150000원을 그린 그림 수(태리 4장, 동하 2장)의 비로 나누면 동하가 태리보다 많이 받아요.',ARRAY['M6-2-u4-X17']::text[],true,'{"seq":10,"concept":"M6-2-u4-C9","difficulty":3,"kind":"ox","stem":"두 친구가 받은 150000원을 그린 그림 수(태리 4장, 동하 2장)의 비로 나누면 동하가 태리보다 많이 받아요.","answer":"X","reason_options":[{"t":"4：2 = 2：1이라 태리 100000원, 동하 50000원이기 때문에","correct":true},{"t":"그림 수가 적을수록 몫이 커지기 때문에","mis":"M6-2-u4-X17"}],"mis":"M6-2-u4-X17","explanation":["4：2를 간단히 하면 2：1이에요.","태리는 150000 × ⟨2/3⟩ = 100000(원)이에요.","동하는 50000원 — 태리가 더 많이 받아요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 150000원을 낸 사용료(태리 12000원, 동하 8000원)의 비로 나누면 동하가 태리보다 많이 받아요.","answer":"X","reason_options":[{"t":"12000：8000 = 3：2라 태리 90000원, 동하 60000원이기 때문에","correct":true},{"t":"사용료를 적게 낸 사람이 몫이 커지기 때문에","mis":"M6-2-u4-X17"}],"explanation":["12000：8000을 간단히 하면 3：2예요.","태리는 150000 × ⟨3/5⟩ = 90000(원)이에요.","동하는 60000원 — 태리가 더 많이 받아요."]},{"stem":"두 친구가 받은 150000원을 그린 그림 수(태리 4장, 동하 2장)의 비로 나누면 태리가 동하의 2배를 받아요.","answer":"O","reason_options":[{"t":"4：2 = 2：1이라 태리 100000원, 동하 50000원이기 때문에","correct":true},{"t":"그림 수가 적을수록 몫이 커지기 때문에","mis":"M6-2-u4-X17"}],"explanation":["4：2를 간단히 하면 2：1이에요.","태리 100000원, 동하 50000원이에요.","100000은 50000의 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#1','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',2,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":1,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"150000원","correct":true},{"t":"600000원","mis":"M6-2-u4-X18"},{"t":"50000원","mis":"M6-2-u4-X17"},{"t":"200000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨3/4⟩ = 150000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 900000원을 회사와 사용자가 2：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 6000원, 동하 4000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"180000원","correct":true},{"t":"540000원","mis":"M6-2-u4-X18"},{"t":"120000원","mis":"M6-2-u4-X17"},{"t":"300000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 900000 × ⟨1/3⟩ = 300000(원)예요.","6000원：4000원을 간단히 하면 3：2예요.","300000 × ⟨3/5⟩ = 180000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#2','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',2,'mc','auto','두 친구가 얻은 200000원을 낸 사용료의 비 3：1로 나누면 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":2,"concept":"M6-2-u4-C9","difficulty":2,"kind":"mc","stem":"두 친구가 얻은 200000원을 낸 사용료의 비 3：1로 나누면 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X15"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["비 3：1은 한 묶음이 3 + 1 = 4칸이에요.","뒤쪽의 몫은 전체의 ⟨1/4⟩이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."],"variant_rule":{"alt":[{"stem":"두 친구가 얻은 210000원을 낸 사용료의 비 4：3으로 나누면 동하는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"70000원","mis":"M6-2-u4-X15"},{"t":"120000원","mis":"M6-2-u4-X17"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["비 4：3은 한 묶음이 4 + 3 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨3/7⟩이에요.","210000 × ⟨3/7⟩ = 90000(원)예요."]},{"stem":"두 친구가 얻은 240000원을 낸 사용료의 비 5：3으로 나누면 동하는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"80000원","mis":"M6-2-u4-X15"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"30000원","mis":"M6-2-u4-X16"}],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","뒤쪽의 몫은 전체의 ⟨3/8⟩이에요.","240000 × ⟨3/8⟩ = 90000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#3','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','두 친구가 받은 150000원을 나눌 때 태리(사용료 12000원·그림 4장)에게 더 유리한 방법은 어느 것인가요? 동하는 사용료 8000원·그림 2장이에요.',ARRAY['M6-2-u4-X17','M6-2-u4-X19','M6-2-u4-X20']::text[],true,'{"seq":3,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"두 친구가 받은 150000원을 나눌 때 태리(사용료 12000원·그림 4장)에게 더 유리한 방법은 어느 것인가요? 동하는 사용료 8000원·그림 2장이에요.","options":[{"t":"그린 그림 수의 비 — 10000원 더 많이 받아요","correct":true},{"t":"낸 사용료의 비 — 10000원 더 많이 받아요","mis":"M6-2-u4-X17"},{"t":"두 방법 모두 같아요","mis":"M6-2-u4-X19"},{"t":"그린 그림 수의 비 — 20000원 더 많이 받아요","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비로 나누면 태리는 90000원이에요.","그림 수의 비로 나누면 태리는 100000원이에요.","그린 그림 수의 비로 나눌 때 10000원 더 많아요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 160000원을 나눌 때 태리(사용료 6000원·그림 5장)에게 더 유리한 방법은 어느 것인가요? 동하는 사용료 10000원·그림 3장이에요.","options":[{"t":"그린 그림 수의 비 — 40000원 더 많이 받아요","correct":true},{"t":"낸 사용료의 비 — 40000원 더 많이 받아요","mis":"M6-2-u4-X17"},{"t":"두 방법 모두 같아요","mis":"M6-2-u4-X19"},{"t":"그린 그림 수의 비 — 80000원 더 많이 받아요","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비로 나누면 태리는 60000원이에요.","그림 수의 비로 나누면 태리는 100000원이에요.","그린 그림 수의 비로 나눌 때 40000원 더 많아요."]},{"stem":"두 친구가 받은 180000원을 나눌 때 태리(사용료 10000원·그림 2장)에게 더 유리한 방법은 어느 것인가요? 동하는 사용료 8000원·그림 4장이에요.","options":[{"t":"낸 사용료의 비 — 40000원 더 많이 받아요","correct":true},{"t":"그린 그림 수의 비 — 40000원 더 많이 받아요","mis":"M6-2-u4-X17"},{"t":"두 방법 모두 같아요","mis":"M6-2-u4-X19"},{"t":"낸 사용료의 비 — 80000원 더 많이 받아요","mis":"M6-2-u4-X20"}],"explanation":["사용료의 비로 나누면 태리는 100000원이에요.","그림 수의 비로 나누면 태리는 60000원이에요.","낸 사용료의 비로 나눌 때 40000원 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#4','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','두 친구가 받은 150000원 가운데 동하가 60000원을 받았어요. 태리와 동하가 나눈 비를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X18','M6-2-u4-X05']::text[],true,'{"seq":4,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"두 친구가 받은 150000원 가운데 동하가 60000원을 받았어요. 태리와 동하가 나눈 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：2","correct":true},{"t":"2：3","mis":"M6-2-u4-X03"},{"t":"5：2","mis":"M6-2-u4-X18"},{"t":"9：6","mis":"M6-2-u4-X05"}],"explanation":["태리는 150000 − 60000 = 90000(원)을 받았어요.","태리：동하 = 90000：60000이에요.","간단히 하면 3：2예요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 150000원 가운데 동하가 50000원을 받았어요. 태리와 동하가 나눈 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X18"},{"t":"10：5","mis":"M6-2-u4-X05"}],"explanation":["태리는 150000 − 50000 = 100000(원)을 받았어요.","태리：동하 = 100000：50000이에요.","간단히 하면 2：1이에요."]},{"stem":"두 친구가 받은 160000원 가운데 동하가 60000원을 받았어요. 태리와 동하가 나눈 비를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"8：3","mis":"M6-2-u4-X18"},{"t":"10：6","mis":"M6-2-u4-X05"}],"explanation":["태리는 160000 − 60000 = 100000(원)을 받았어요.","태리：동하 = 100000：60000이에요.","간단히 하면 5：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#5','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'mc','auto','세 사람이 3000원, 2000원, 1000원을 내어 얻은 수익 120000원을 낸 금액의 비로 나누어요. 돈을 첫째로 많이 낸 사람은 몇 원을 받나요?',ARRAY['M6-2-u4-X15','M6-2-u4-X16','M6-2-u4-X20']::text[],true,'{"seq":5,"concept":"M6-2-u4-C9","difficulty":3,"kind":"mc","stem":"세 사람이 3000원, 2000원, 1000원을 내어 얻은 수익 120000원을 낸 금액의 비로 나누어요. 돈을 첫째로 많이 낸 사람은 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"40000원","mis":"M6-2-u4-X15"},{"t":"20000원","mis":"M6-2-u4-X16"},{"t":"120000원","mis":"M6-2-u4-X20"}],"explanation":["3000원：2000원：1000원을 간단히 하면 3：2：1이에요.","한 묶음은 6칸 — 첫째 사람은 3칸이에요.","120000 × ⟨3/6⟩ = 60000(원)예요."],"variant_rule":{"alt":[{"stem":"세 사람이 4000원, 3000원, 2000원을 내어 얻은 수익 90000원을 낸 금액의 비로 나누어요. 돈을 둘째로 많이 낸 사람은 몇 원을 받나요?","options":[{"t":"30000원","correct":true},{"t":"10000원","mis":"M6-2-u4-X16"},{"t":"60000원","mis":"M6-2-u4-X20"},{"t":"40000원","mis":"M6-2-u4-X20"}],"explanation":["4000원：3000원：2000원을 간단히 하면 4：3：2예요.","한 묶음은 9칸 — 둘째 사람은 3칸이에요.","90000 × ⟨3/9⟩ = 30000(원)예요."]},{"stem":"세 사람이 5000원, 3000원, 2000원을 내어 얻은 수익 150000원을 낸 금액의 비로 나누어요. 돈을 첫째로 많이 낸 사람은 몇 원을 받나요?","options":[{"t":"75000원","correct":true},{"t":"50000원","mis":"M6-2-u4-X15"},{"t":"15000원","mis":"M6-2-u4-X16"},{"t":"150000원","mis":"M6-2-u4-X20"}],"explanation":["5000원：3000원：2000원을 간단히 하면 5：3：2예요.","한 묶음은 10칸 — 첫째 사람은 5칸이에요.","150000 × ⟨5/10⟩ = 75000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#6','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'ox','auto','전체 수익 500000원을 바로 낸 사용료의 비 3：2로 나누면 태리의 몫 90000원을 구할 수 있어요.',ARRAY['M6-2-u4-X18']::text[],true,'{"seq":6,"concept":"M6-2-u4-C9","difficulty":3,"kind":"ox","stem":"전체 수익 500000원을 바로 낸 사용료의 비 3：2로 나누면 태리의 몫 90000원을 구할 수 있어요.","answer":"X","reason_options":[{"t":"먼저 회사와 7：3으로 나눈 두 친구의 몫 150000원을 3：2로 나누어야 하기 때문에","correct":true},{"t":"전체 수익을 바로 두 친구의 비로 나누면 되기 때문에","mis":"M6-2-u4-X18"}],"mis":"M6-2-u4-X18","explanation":["500000원을 바로 3：2로 나누면 태리는 300000원이 되어 버려요.","먼저 두 친구의 몫 500000 × ⟨3/10⟩ = 150000(원)을 구해요.","150000 × ⟨3/5⟩ = 90000(원)이에요."],"variant_rule":{"alt":[{"stem":"전체 수익 500000원을 바로 그린 그림 수의 비 2：1로 나누면 태리의 몫 100000원을 구할 수 있어요.","answer":"X","reason_options":[{"t":"먼저 회사와 7：3으로 나눈 두 친구의 몫 150000원을 2：1로 나누어야 하기 때문에","correct":true},{"t":"전체 수익을 바로 두 친구의 비로 나누면 되기 때문에","mis":"M6-2-u4-X18"}],"explanation":["500000원을 바로 2：1로 나누면 태리는 약 333333원이 되어 버려요.","먼저 두 친구의 몫 150000원을 구해요.","150000 × ⟨2/3⟩ = 100000(원)이에요."]},{"stem":"두 번 나누는 문제에서는 먼저 전체에서 두 친구의 몫을 구한 뒤 그 몫을 두 친구의 비로 나누어요.","answer":"O","reason_options":[{"t":"두 친구가 나누는 것은 전체가 아니라 회사 몫을 뺀 두 친구의 몫이기 때문에","correct":true},{"t":"전체 수익을 바로 두 친구의 비로 나누면 되기 때문에","mis":"M6-2-u4-X18"}],"explanation":["전체 수익은 먼저 회사와 사용자가 나눠요.","두 친구는 사용자 몫만 나누어 가져요.","그래서 두 단계로 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#7','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',3,'match','auto','나누는 기준과 태리의 몫을 이으세요(두 친구의 몫 150000원).','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C9","difficulty":3,"kind":"match","stem":"나누는 기준과 태리의 몫을 이으세요(두 친구의 몫 150000원).","pairs":[{"l":"낸 사용료의 비 3：2","r":"90000원"},{"l":"그린 그림 수의 비 2：1","r":"100000원"},{"l":"똑같이 1：1","r":"75000원"}],"mis":"M6-2-u4-X17","explanation":["150000 × ⟨3/5⟩ = 90000(원)이에요.","150000 × ⟨2/3⟩ = 100000(원)이에요.","150000 × ⟨1/2⟩ = 75000(원)이에요."],"variant_rule":{"alt":[{"stem":"나누는 기준과 태리의 몫을 이으세요(두 친구의 몫 120000원).","pairs":[{"l":"낸 사용료의 비 5：3","r":"75000원"},{"l":"그린 그림 수의 비 1：1","r":"60000원"},{"l":"참여한 시간의 비 3：1","r":"90000원"}],"explanation":["120000 × ⟨5/8⟩ = 75000(원)이에요.","120000 × ⟨1/2⟩ = 60000(원)이에요.","120000 × ⟨3/4⟩ = 90000(원)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#8','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'mc','auto','두 친구가 받은 몫을 사용료의 비로 나누면 태리 90000원·동하 60000원, 그림 수의 비로 나누면 태리 100000원·동하 50000원이에요. 두 방법으로 나눈 몫의 평균을 받기로 했다면 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X20','M6-2-u4-X19']::text[],true,'{"seq":8,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"두 친구가 받은 몫을 사용료의 비로 나누면 태리 90000원·동하 60000원, 그림 수의 비로 나누면 태리 100000원·동하 50000원이에요. 두 방법으로 나눈 몫의 평균을 받기로 했다면 동하는 몇 원을 받나요?","options":[{"t":"55000원","correct":true},{"t":"95000원","mis":"M6-2-u4-X17"},{"t":"110000원","mis":"M6-2-u4-X20"},{"t":"60000원","mis":"M6-2-u4-X19"}],"explanation":["동하의 두 몫은 60000원과 50000원이에요.","평균은 두 몫을 더해 2로 나눠요.","(60000 + 50000) ÷ 2 = 55000(원)예요."],"variant_rule":{"alt":[{"stem":"두 친구가 받은 몫을 사용료의 비로 나누면 태리 90000원·동하 60000원, 그림 수의 비로 나누면 태리 100000원·동하 50000원이에요. 두 방법으로 나눈 몫의 평균을 받기로 했다면 태리는 몇 원을 받나요?","options":[{"t":"95000원","correct":true},{"t":"55000원","mis":"M6-2-u4-X17"},{"t":"190000원","mis":"M6-2-u4-X20"},{"t":"90000원","mis":"M6-2-u4-X19"}],"explanation":["태리의 두 몫은 90000원과 100000원이에요.","평균은 두 몫을 더해 2로 나눠요.","(90000 + 100000) ÷ 2 = 95000(원)예요."]},{"stem":"두 친구가 받은 몫을 사용료의 비로 나누면 태리 75000원·동하 45000원, 그림 수의 비로 나누면 태리 80000원·동하 40000원이에요. 두 방법으로 나눈 몫의 평균을 받기로 했다면 동하는 몇 원을 받나요?","options":[{"t":"42500원","correct":true},{"t":"77500원","mis":"M6-2-u4-X17"},{"t":"85000원","mis":"M6-2-u4-X20"},{"t":"45000원","mis":"M6-2-u4-X19"}],"explanation":["동하의 두 몫은 45000원과 40000원이에요.","평균은 두 몫을 더해 2로 나눠요.","(45000 + 40000) ÷ 2 = 42500(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#9','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'essay','teacher','태리와 동하의 협동 작품 수익 500000원을 회사와 사용자가 7：3으로 나눠요. 두 친구의 몫을 낸 사용료(태리 12000원, 동하 8000원)의 비와 그린 그림 수(태리 4장, 동하 2장)의 비로 각각 나누어 보고, 어느 방법이 더 공정하다고 생각하는지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하의 협동 작품 수익 500000원을 회사와 사용자가 7：3으로 나눠요. 두 친구의 몫을 낸 사용료(태리 12000원, 동하 8000원)의 비와 그린 그림 수(태리 4장, 동하 2장)의 비로 각각 나누어 보고, 어느 방법이 더 공정하다고 생각하는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000원이다. 사용료의 비 3：2로 나누면 태리 90000원, 동하 60000원이고, 그림 수의 비 2：1로 나누면 태리 100000원, 동하 50000원이다. (예) 그림을 많이 그린 노력이 작품에 더 크게 들어갔으므로 그림 수의 비가 공정하다고 생각한다 — 또는 돈을 낸 만큼 나누는 사용료의 비가 공정하다고 볼 수도 있다.","scoring_points":["두 친구의 몫 150000원을 구했는가","두 방법의 몫을 모두 바르게 구했는가","자기 생각과 그 까닭을 썼는가"]},"explanation":["먼저 150000원을 구해요.","사용료 비 → 90000·60000, 그림 수 비 → 100000·50000이에요.","어느 쪽이 공정한지는 까닭을 들어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_L08_challenge#10','math',6,2,'u4','L08','g6_2_math_u4_L08_challenge','lesson_challenge','M6-2-u4-C9',4,'essay','teacher','다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액의 비로 도화지를 나누는 과정을 쓰고, 두 사람이 똑같이 나누는 것과 견주어 어느 쪽이 공정한지 생각을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"다현이가 1500원, 윤수가 600원을 내서 도화지 35장을 샀어요. 낸 금액의 비로 도화지를 나누는 과정을 쓰고, 두 사람이 똑같이 나누는 것과 견주어 어느 쪽이 공정한지 생각을 써 보세요.","answer_guide":{"answer":"예: 1500：600을 간단히 하면 5：2이고 한 묶음은 7칸이다. 다현이는 35 × ⟨5/7⟩ = 25장, 윤수는 35 × ⟨2/7⟩ = 10장이다. 똑같이 나누면 17장과 18장으로 딱 나누어지지 않고 돈을 더 낸 다현이에게 불리하므로 낸 금액의 비로 나누는 것이 공정하다고 생각한다.","scoring_points":["5：2로 간단히 했는가","25장과 10장을 구했는가","똑같이 나누는 것과 견주어 자기 생각을 썼는가"]},"explanation":["1500：600 = 5：2예요.","35 × ⟨5/7⟩ = 25, 35 × ⟨2/7⟩ = 10이에요.","낸 만큼 나누는 방법을 견주어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#1','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',1,'sa','auto','3：11의 전항과 후항에 똑같이 3을 곱했어요. 9：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"3：11의 전항과 후항에 똑같이 3을 곱했어요. 9：□에서 □에 알맞은 수는 얼마인가요?","answer":["33"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 3을 곱해 9가 되었으니 후항 11에도 3을 곱해요.","11 × 3 = 33 — 9：33이에요."],"variant_rule":{"alt":[{"stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."]},{"stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#2','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',1,'sa','auto','35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."],"variant_rule":{"alt":[{"stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."]},{"stem":"48：36의 전항과 후항을 똑같이 12로 나누었어요. 4：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 48을 12로 나누면 4예요.","후항도 36 ÷ 12 = 3 — 4：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#3','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',2,'mc','auto','2：3과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#4','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C1',3,'ox','auto','2：3의 전항과 후항에 똑같이 2를 더한 4：5는 2：3과 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"2：3의 전항과 후항에 똑같이 2를 더한 4：5는 2：3과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨2/3⟩와 ⟨4/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","2：3의 비율은 ⟨2/3⟩, 4：5의 비율은 ⟨4/5⟩예요.","그래서 비율이 같지 않아요."],"variant_rule":{"alt":[{"stem":"3：5의 전항과 후항에 똑같이 2를 더한 5：7은 3：5와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨3/5⟩과 ⟨5/7⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","3：5의 비율은 ⟨3/5⟩, 5：7의 비율은 ⟨5/7⟩예요.","그래서 비율이 같지 않아요."]},{"stem":"5：2의 전항과 후항에 똑같이 3을 더한 8：5는 5：2와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨5/2⟩와 ⟨8/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","5：2의 비율은 ⟨5/2⟩, 8：5의 비율은 ⟨8/5⟩이에요.","그래서 비율이 같지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#5','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C2',1,'mc','auto','54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"18：9","mis":"M6-2-u4-X05"},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：27","mis":"M6-2-u4-X02"}],"explanation":["54와 27의 최대공약수는 27이에요.","전항과 후항을 똑같이 27로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"4：63","mis":"M6-2-u4-X02"},{"t":"28：9","mis":"M6-2-u4-X02"}],"explanation":["28과 63의 최대공약수는 7이에요.","전항과 후항을 똑같이 7로 나누면 4：9예요.","4와 9는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"6：10","mis":"M6-2-u4-X05"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["12와 20의 최대공약수는 4예요.","전항과 후항을 똑같이 4로 나누면 3：5예요.","3과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#6','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C2',2,'mc','auto','84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：3","correct":true},{"t":"42：18","mis":"M6-2-u4-X05"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：36","mis":"M6-2-u4-X02"}],"explanation":["84와 36의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 7：3이에요.","7과 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"24：36","mis":"M6-2-u4-X05"},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"2：72","mis":"M6-2-u4-X02"}],"explanation":["48과 72의 최대공약수는 24예요.","전항과 후항을 똑같이 24로 나누면 2：3이에요.","2와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"45：27","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：54","mis":"M6-2-u4-X02"}],"explanation":["90과 54의 최대공약수는 18이에요.","전항과 후항을 똑같이 18로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#7','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C3',1,'sa','auto','0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.8：0.4에 10을 곱하면 8：4예요.","두 항을 4로 나누면 2：1이에요."],"variant_rule":{"alt":[{"stem":"3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","3.5：4.9에 10을 곱하면 35：49예요.","두 항을 7로 나누면 5：7이에요."]},{"stem":"0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.6：1.5에 10을 곱하면 6：15예요.","두 항을 3으로 나누면 2：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#8','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C3',2,'mc','auto','2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."],"variant_rule":{"alt":[{"stem":"1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"14：12","mis":"M6-2-u4-X05"},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"14：1.2","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 14：12예요.","14와 12의 최대공약수 2로 나누면 7：6이에요.","그래서 가장 간단한 자연수의 비는 7：6이에요."]},{"stem":"0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"25：75","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"2.5：7.5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 25：75예요.","25와 75의 최대공약수 25로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#9','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C4',2,'mc','auto','⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03']::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"},{"t":"9：14","mis":"M6-2-u4-X03"}],"explanation":["두 분모 3과 7의 공배수 21을 전항과 후항에 똑같이 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 가장 간단한 자연수의 비는 14：9예요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["두 분모 6과 4의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 가장 간단한 자연수의 비는 2：3이에요."]},{"stem":"⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"9：10","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"10：9","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨3/4⟩ × 12 = 9, ⟨5/6⟩ × 12 = 10이에요.","그래서 가장 간단한 자연수의 비는 9：10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#10','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C4',3,'mc','auto','⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X06"},{"t":"16：16","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨3/4⟩을 소수 0.75로 바꾸면 0.75：0.8이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 15：16이에요."],"variant_rule":{"alt":[{"stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"7：2","mis":"M6-2-u4-X06"},{"t":"8：4","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.7：0.4예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 7：4예요."]},{"stem":"0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X06"},{"t":"4：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨1/2⟩을 소수 0.5로 바꾸면 0.3：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#11','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',1,'mc','auto','비례식 8：7 = 24：21에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":11,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 8：7 = 24：21에서 외항은 어느 것인가요?","options":[{"t":"8과 21","correct":true},{"t":"7과 24","mis":"M6-2-u4-X10"},{"t":"8과 7","mis":"M6-2-u4-X10"},{"t":"24와 21","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","8：7 = 24：21에서 바깥쪽은 8과 21, 안쪽은 7과 24예요.","그래서 외항은 8과 21이에요."],"variant_rule":{"alt":[{"stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."]},{"stem":"비례식 9：12 = 3：4에서 내항은 어느 것인가요?","options":[{"t":"12와 3","correct":true},{"t":"9와 4","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"},{"t":"3과 4","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","9：12 = 3：4에서 바깥쪽은 9와 4, 안쪽은 12와 3이에요.","그래서 내항은 12와 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#12','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X02']::text[],true,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"50：20 = 25：10","correct":true},{"t":"7：4 = 4：7","mis":"M6-2-u4-X09"},{"t":"5：8 = 10：24","mis":"M6-2-u4-X02"},{"t":"3：2 = 2：3","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","50：20과 25：10의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 6：15","correct":true},{"t":"2：5 = 5：2","mis":"M6-2-u4-X09"},{"t":"2：5 = 4：7","mis":"M6-2-u4-X01"},{"t":"2：5 = 4：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5와 6：15의 비율은 모두 ⟨2/5⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 4：3","correct":true},{"t":"8：6 = 6：8","mis":"M6-2-u4-X09"},{"t":"8：6 = 10：8","mis":"M6-2-u4-X01"},{"t":"8：6 = 16：6","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","8：6과 4：3의 비율은 모두 ⟨4/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#13','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C5',3,'mc','auto','5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X20','M6-2-u4-X07','M6-2-u4-X09']::text[],true,'{"seq":13,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = 2.4：2.1","mis":"M6-2-u4-X20"},{"t":"⟨1/5⟩：⟨1/6⟩ = 5：6","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"}],"explanation":["각 비의 비율을 견주어 봐요.","8：7 = 2.4：2.1의 두 비는 간단히 하면 모두 8：7이에요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"3：4 = 1.2：1.6","correct":true},{"t":"⟨1/3⟩：⟨1/4⟩ = 3：4","mis":"M6-2-u4-X07"},{"t":"3：4 = 9：8","mis":"M6-2-u4-X20"},{"t":"9：8 = 1.2：1.6","mis":"M6-2-u4-X20"}],"explanation":["각 비의 비율을 견주어 봐요.","3：4 = 1.2：1.6의 두 비는 간단히 하면 모두 3：4예요.","나머지는 비율이 서로 달라요."]},{"stem":"2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"2：5 = 0.4：1","correct":true},{"t":"⟨1/2⟩：⟨1/5⟩ = 2：5","mis":"M6-2-u4-X07"},{"t":"2：5 = 5：3","mis":"M6-2-u4-X20"},{"t":"⟨1/2⟩：⟨1/5⟩ = 0.4：1","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","2：5 = 0.4：1의 두 비는 간단히 하면 모두 2：5예요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#14','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."]},{"stem":"비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?","answer":["24"],"explanation":["내항은 3과 8이에요.","내항의 곱은 3 × 8 = 24예요.","외항의 곱도 24로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#15','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',2,'sa','auto','4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."],"variant_rule":{"alt":[{"stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."]},{"stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#16','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C6',3,'mc','auto','8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."],"variant_rule":{"alt":[{"stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."]},{"stem":"6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 6 × 10으로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","6 × □ = 9 × 10이에요.","□ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#17','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',1,'sa','auto','사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."],"variant_rule":{"alt":[{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."]},{"stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#18','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',2,'mc','auto','어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."],"variant_rule":{"alt":[{"stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."]},{"stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#19','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',3,'mc','auto','쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."],"variant_rule":{"alt":[{"stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."]},{"stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#20','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',1,'sa','auto','꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."],"variant_rule":{"alt":[{"stem":"색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."]},{"stem":"사과 28개를 정후네와 연아네가 3：4로 나누어요. 연아네는 몇 개를 받나요?","answer":["16"],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","28 × ⟨4/7⟩ = 16(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#21','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',2,'mc','auto','찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?',ARRAY['M6-2-u4-X15','M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."],"variant_rule":{"alt":[{"stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."]},{"stem":"1시간 동안 달리기와 줄넘기를 7：5의 시간으로 했어요. 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#22','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C8',3,'mc','auto','1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"2400 ÷ 3을 하여 800씩 나눈다","correct":true},{"t":"전체를 8칸으로 갈라 3칸과 5칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"2400 × ⟨3/8⟩과 2400 × ⟨5/8⟩를 각각 구한다","mis":"M6-2-u4-X19"},{"t":"900과 1500으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["3：5는 한 묶음이 8칸이라는 뜻이에요.","그래서 2400 × ⟨3/8⟩ = 900, 2400 × ⟨5/8⟩ = 1500이에요.","2400 ÷ 3처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#23','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"120000원","correct":true},{"t":"400000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"180000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000(원)예요.","12000원：6000원을 간단히 하면 2：1이에요.","180000 × ⟨2/3⟩ = 120000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#24','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 500000원을 회사와 사용자가 7：3으로 나누어요. 두 친구의 몫을 낸 사용료(태리 12000원, 동하 8000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 4장, 동하 2장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 500000원을 회사와 사용자가 7：3으로 나누어요. 두 친구의 몫을 낸 사용료(태리 12000원, 동하 8000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 4장, 동하 2장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000원이다. 사용료의 비 3：2로 나누면 태리 90000원, 동하 60000원이다. 그림 수의 비 2：1로 나누면 태리 100000원이므로 그림 수의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 150000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 150000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_a#25','math',6,2,'u4','','g6_2_math_u4_review_a','unit_review','M6-2-u4-C7',4,'essay','teacher','사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 9：4 = □：12이다. ① 외항의 곱과 내항의 곱이 같으므로 9 × 12 = 4 × □, □ = 27이다. ② 후항에 3을 곱했으므로 전항에도 3을 곱해 □ = 27이다.","scoring_points":["9：4 = □：12를 세웠는가","비례식의 성질로 27을 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["9：4 = □：12예요.","9 × 12 = 4 × □ → □ = 27이에요.","3배 해도 □ = 27이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#1','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',1,'sa','auto','7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."],"variant_rule":{"alt":[{"stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."]},{"stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#2','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',1,'sa','auto','45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."],"variant_rule":{"alt":[{"stem":"48：36의 전항과 후항을 똑같이 12로 나누었어요. 4：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 48을 12로 나누면 4예요.","후항도 36 ÷ 12 = 3 — 4：3이에요."]},{"stem":"56：21의 전항과 후항을 똑같이 7로 나누었어요. 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 56을 7로 나누면 8이에요.","후항도 21 ÷ 7 = 3 — 8：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#3','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',2,'mc','auto','4：3과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"3：7과 비율이 같은 비는 어느 것인가요?","options":[{"t":"9：21","correct":true},{"t":"6：10","mis":"M6-2-u4-X01"},{"t":"21：9","mis":"M6-2-u4-X03"},{"t":"9：7","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","3：7의 두 항에 똑같이 3을 곱하면 9：21이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#4','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C1',3,'ox','auto','3：5의 전항과 후항에 똑같이 2를 더한 5：7은 3：5와 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"3：5의 전항과 후항에 똑같이 2를 더한 5：7은 3：5와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨3/5⟩과 ⟨5/7⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","3：5의 비율은 ⟨3/5⟩, 5：7의 비율은 ⟨5/7⟩예요.","그래서 비율이 같지 않아요."],"variant_rule":{"alt":[{"stem":"5：2의 전항과 후항에 똑같이 3을 더한 8：5는 5：2와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨5/2⟩와 ⟨8/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","5：2의 비율은 ⟨5/2⟩, 8：5의 비율은 ⟨8/5⟩이에요.","그래서 비율이 같지 않아요."]},{"stem":"4：7의 전항과 후항에 똑같이 1을 더한 5：8은 4：7과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨4/7⟩와 ⟨5/8⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","4：7의 비율은 ⟨4/7⟩, 5：8의 비율은 ⟨5/8⟩예요.","그래서 비율이 같지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#5','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C2',1,'mc','auto','28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"4：63","mis":"M6-2-u4-X02"},{"t":"28：9","mis":"M6-2-u4-X02"}],"explanation":["28과 63의 최대공약수는 7이에요.","전항과 후항을 똑같이 7로 나누면 4：9예요.","4와 9는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"6：10","mis":"M6-2-u4-X05"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["12와 20의 최대공약수는 4예요.","전항과 후항을 똑같이 4로 나누면 3：5예요.","3과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"36：48을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"18：24","mis":"M6-2-u4-X05"},{"t":"4：3","mis":"M6-2-u4-X03"},{"t":"3：48","mis":"M6-2-u4-X02"}],"explanation":["36과 48의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 3：4예요.","3과 4는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#6','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C2',2,'mc','auto','48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"24：36","mis":"M6-2-u4-X05"},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"2：72","mis":"M6-2-u4-X02"}],"explanation":["48과 72의 최대공약수는 24예요.","전항과 후항을 똑같이 24로 나누면 2：3이에요.","2와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"45：27","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：54","mis":"M6-2-u4-X02"}],"explanation":["90과 54의 최대공약수는 18이에요.","전항과 후항을 똑같이 18로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"96：60을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：5","correct":true},{"t":"48：30","mis":"M6-2-u4-X05"},{"t":"5：8","mis":"M6-2-u4-X03"},{"t":"8：60","mis":"M6-2-u4-X02"}],"explanation":["96과 60의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 8：5예요.","8과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#7','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C3',1,'sa','auto','3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","3.5：4.9에 10을 곱하면 35：49예요.","두 항을 7로 나누면 5：7이에요."],"variant_rule":{"alt":[{"stem":"0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.6：1.5에 10을 곱하면 6：15예요.","두 항을 3으로 나누면 2：5예요."]},{"stem":"1.2：1.6의 전항과 후항에 10을 곱하면 12：16이에요. 다시 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","1.2：1.6에 10을 곱하면 12：16이에요.","두 항을 4로 나누면 3：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#8','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C3',2,'mc','auto','1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"14：12","mis":"M6-2-u4-X05"},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"14：1.2","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 14：12예요.","14와 12의 최대공약수 2로 나누면 7：6이에요.","그래서 가장 간단한 자연수의 비는 7：6이에요."],"variant_rule":{"alt":[{"stem":"0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"25：75","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"2.5：7.5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 25：75예요.","25와 75의 최대공약수 25로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."]},{"stem":"0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：5","correct":true},{"t":"12：30","mis":"M6-2-u4-X05"},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"1.2：3","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 12：30이에요.","12와 30의 최대공약수 6으로 나누면 2：5예요.","그래서 가장 간단한 자연수의 비는 2：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#9','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C4',2,'mc','auto','⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03']::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["두 분모 6과 4의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 가장 간단한 자연수의 비는 2：3이에요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"9：10","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"10：9","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨3/4⟩ × 12 = 9, ⟨5/6⟩ × 12 = 10이에요.","그래서 가장 간단한 자연수의 비는 9：10이에요."]},{"stem":"⟨1/5⟩：⟨1/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"5：7","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"8：5","mis":"M6-2-u4-X20"}],"explanation":["두 분모 5와 7의 공배수 35를 전항과 후항에 똑같이 곱해요.","⟨1/5⟩ × 35 = 7, ⟨1/7⟩ × 35 = 5예요.","그래서 가장 간단한 자연수의 비는 7：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#10','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C4',3,'mc','auto','0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"7：2","mis":"M6-2-u4-X06"},{"t":"8：4","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.7：0.4예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 7：4예요."],"variant_rule":{"alt":[{"stem":"0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X06"},{"t":"4：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨1/2⟩을 소수 0.5로 바꾸면 0.3：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：5예요."]},{"stem":"⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-2-u4-X03"},{"t":"2：5","mis":"M6-2-u4-X06"},{"t":"5：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.4：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 4：5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#11','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',1,'mc','auto','비례식 56：21 = 8：3에서 외항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":11,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."],"variant_rule":{"alt":[{"stem":"비례식 9：12 = 3：4에서 내항은 어느 것인가요?","options":[{"t":"12와 3","correct":true},{"t":"9와 4","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"},{"t":"3과 4","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","9：12 = 3：4에서 바깥쪽은 9와 4, 안쪽은 12와 3이에요.","그래서 내항은 12와 3이에요."]},{"stem":"비례식 6：8 = 9：12에서 내항은 어느 것인가요?","options":[{"t":"8과 9","correct":true},{"t":"6과 12","mis":"M6-2-u4-X10"},{"t":"6과 8","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","6：8 = 9：12에서 바깥쪽은 6과 12, 안쪽은 8과 9예요.","그래서 내항은 8과 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#12','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 6：15","correct":true},{"t":"2：5 = 5：2","mis":"M6-2-u4-X09"},{"t":"2：5 = 4：7","mis":"M6-2-u4-X01"},{"t":"2：5 = 4：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5와 6：15의 비율은 모두 ⟨2/5⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 4：3","correct":true},{"t":"8：6 = 6：8","mis":"M6-2-u4-X09"},{"t":"8：6 = 10：8","mis":"M6-2-u4-X01"},{"t":"8：6 = 16：6","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","8：6과 4：3의 비율은 모두 ⟨4/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"9：12 = 12：9","mis":"M6-2-u4-X09"},{"t":"9：12 = 10：13","mis":"M6-2-u4-X01"},{"t":"9：12 = 3：12","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","9：12와 3：4의 비율은 모두 ⟨3/4⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#13','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C5',3,'mc','auto','3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":13,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"3：4 = 1.2：1.6","correct":true},{"t":"⟨1/3⟩：⟨1/4⟩ = 3：4","mis":"M6-2-u4-X07"},{"t":"3：4 = 9：8","mis":"M6-2-u4-X20"},{"t":"9：8 = 1.2：1.6","mis":"M6-2-u4-X20"}],"explanation":["각 비의 비율을 견주어 봐요.","3：4 = 1.2：1.6의 두 비는 간단히 하면 모두 3：4예요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"2：5 = 0.4：1","correct":true},{"t":"⟨1/2⟩：⟨1/5⟩ = 2：5","mis":"M6-2-u4-X07"},{"t":"2：5 = 5：3","mis":"M6-2-u4-X20"},{"t":"⟨1/2⟩：⟨1/5⟩ = 0.4：1","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","2：5 = 0.4：1의 두 비는 간단히 하면 모두 2：5예요.","나머지는 비율이 서로 달라요."]},{"stem":"4：3, ⟨1/4⟩：⟨1/3⟩, 1.6：1.2, 3：5 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"4：3 = 1.6：1.2","correct":true},{"t":"⟨1/4⟩：⟨1/3⟩ = 4：3","mis":"M6-2-u4-X07"},{"t":"4：3 = 3：5","mis":"M6-2-u4-X20"},{"t":"⟨1/4⟩：⟨1/3⟩ = 1.6：1.2","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","4：3 = 1.6：1.2의 두 비는 간단히 하면 모두 4：3이에요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#14','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?","answer":["24"],"explanation":["내항은 3과 8이에요.","내항의 곱은 3 × 8 = 24예요.","외항의 곱도 24로 같아요."]},{"stem":"비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?","answer":["40"],"explanation":["내항은 5와 8이에요.","내항의 곱은 5 × 8 = 40이에요.","외항의 곱도 40으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#15','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',2,'sa','auto','10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."],"variant_rule":{"alt":[{"stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."]},{"stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#16','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C6',3,'mc','auto','4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."],"variant_rule":{"alt":[{"stem":"6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 6 × 10으로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","6 × □ = 9 × 10이에요.","□ = 15예요."]},{"stem":"9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 9 × 18로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","9 × □ = 4 × 18이에요.","□ = 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#17','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',1,'sa','auto','계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."],"variant_rule":{"alt":[{"stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."]},{"stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#18','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',2,'mc','auto','페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?',ARRAY['M6-2-u4-X13','M6-2-u4-X14','M6-2-u4-X12']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."],"variant_rule":{"alt":[{"stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."]},{"stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#19','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',3,'mc','auto','전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."],"variant_rule":{"alt":[{"stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."]},{"stem":"페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"4：48 = □：60","correct":true},{"t":"4：48 = 60：□","mis":"M6-2-u4-X13"},{"t":"48：4 = □：60","mis":"M6-2-u4-X13"},{"t":"4：60 = □：48","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 4：48 = □：60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#20','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',1,'sa','auto','색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."],"variant_rule":{"alt":[{"stem":"사과 28개를 정후네와 연아네가 3：4로 나누어요. 연아네는 몇 개를 받나요?","answer":["16"],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","28 × ⟨4/7⟩ = 16(개)예요."]},{"stem":"연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#21','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',2,'mc','auto','용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."],"variant_rule":{"alt":[{"stem":"1시간 동안 달리기와 줄넘기를 7：5의 시간으로 했어요. 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."]},{"stem":"2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#22','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C8',3,'mc','auto','1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"2400 ÷ 3을 하여 800씩 나눈다","correct":true},{"t":"전체를 8칸으로 갈라 3칸과 5칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"2400 × ⟨3/8⟩과 2400 × ⟨5/8⟩를 각각 구한다","mis":"M6-2-u4-X19"},{"t":"900과 1500으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["3：5는 한 묶음이 8칸이라는 뜻이에요.","그래서 2400 × ⟨3/8⟩ = 900, 2400 × ⟨5/8⟩ = 1500이에요.","2400 ÷ 3처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1800 ÷ 2를 하여 900씩 나눈다","correct":true},{"t":"전체를 9칸으로 갈라 2칸과 7칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1800 × ⟨2/9⟩와 1800 × ⟨7/9⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"400과 1400으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：7은 한 묶음이 9칸이라는 뜻이에요.","그래서 1800 × ⟨2/9⟩ = 400, 1800 × ⟨7/9⟩ = 1400이에요.","1800 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#23','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"120000원","correct":true},{"t":"400000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"180000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000(원)예요.","12000원：6000원을 간단히 하면 2：1이에요.","180000 × ⟨2/3⟩ = 120000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#24','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 600000원을 회사와 사용자가 7：3으로 나누어요. 두 친구의 몫을 낸 사용료(태리 10000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 6장, 동하 2장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 600000원을 회사와 사용자가 7：3으로 나누어요. 두 친구의 몫을 낸 사용료(태리 10000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 6장, 동하 2장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000원이다. 사용료의 비 5：3으로 나누면 태리 112500원, 동하 67500원이다. 그림 수의 비 3：1로 나누면 태리 135000원이므로 그림 수의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 180000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 180000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_b#25','math',6,2,'u4','','g6_2_math_u4_review_b','unit_review','M6-2-u4-C7',4,'essay','teacher','쌀 2 kg으로 떡 3판을 만들 수 있어요. 떡 12판을 만들려면 쌀이 몇 kg 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"쌀 2 kg으로 떡 3판을 만들 수 있어요. 떡 12판을 만들려면 쌀이 몇 kg 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 2：3 = □：12이다. ① 외항의 곱과 내항의 곱이 같으므로 2 × 12 = 3 × □, □ = 8이다. ② 후항에 4를 곱했으므로 전항에도 4를 곱해 □ = 8이다.","scoring_points":["2：3 = □：12를 세웠는가","비례식의 성질로 8을 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["2：3 = □：12예요.","2 × 12 = 3 × □ → □ = 8이에요.","4배 해도 □ = 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#1','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',1,'sa','auto','4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"4：9의 전항과 후항에 똑같이 3을 곱했어요. 12：□에서 □에 알맞은 수는 얼마인가요?","answer":["27"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 4에 3을 곱해 12가 되었으니 후항 9에도 3을 곱해요.","9 × 3 = 27 — 12：27이에요."],"variant_rule":{"alt":[{"stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."]},{"stem":"3：11의 전항과 후항에 똑같이 3을 곱했어요. 9：□에서 □에 알맞은 수는 얼마인가요?","answer":["33"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 3을 곱해 9가 되었으니 후항 11에도 3을 곱해요.","11 × 3 = 33 — 9：33이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#2','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',1,'sa','auto','48：36의 전항과 후항을 똑같이 12로 나누었어요. 4：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"48：36의 전항과 후항을 똑같이 12로 나누었어요. 4：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 48을 12로 나누면 4예요.","후항도 36 ÷ 12 = 3 — 4：3이에요."],"variant_rule":{"alt":[{"stem":"56：21의 전항과 후항을 똑같이 7로 나누었어요. 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 56을 7로 나누면 8이에요.","후항도 21 ÷ 7 = 3 — 8：3이에요."]},{"stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#3','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',2,'mc','auto','5：2와 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"5：2와 비율이 같은 비는 어느 것인가요?","options":[{"t":"10：4","correct":true},{"t":"7：4","mis":"M6-2-u4-X01"},{"t":"4：10","mis":"M6-2-u4-X03"},{"t":"10：2","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","5：2의 두 항에 똑같이 2를 곱하면 10：4예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"3：7과 비율이 같은 비는 어느 것인가요?","options":[{"t":"9：21","correct":true},{"t":"6：10","mis":"M6-2-u4-X01"},{"t":"21：9","mis":"M6-2-u4-X03"},{"t":"9：7","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","3：7의 두 항에 똑같이 3을 곱하면 9：21이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#4','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C1',3,'ox','auto','5：2의 전항과 후항에 똑같이 3을 더한 8：5는 5：2와 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"5：2의 전항과 후항에 똑같이 3을 더한 8：5는 5：2와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨5/2⟩와 ⟨8/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","5：2의 비율은 ⟨5/2⟩, 8：5의 비율은 ⟨8/5⟩이에요.","그래서 비율이 같지 않아요."],"variant_rule":{"alt":[{"stem":"4：7의 전항과 후항에 똑같이 1을 더한 5：8은 4：7과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨4/7⟩와 ⟨5/8⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","4：7의 비율은 ⟨4/7⟩, 5：8의 비율은 ⟨5/8⟩예요.","그래서 비율이 같지 않아요."]},{"stem":"2：3의 전항과 후항에 똑같이 2를 더한 4：5는 2：3과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨2/3⟩와 ⟨4/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","2：3의 비율은 ⟨2/3⟩, 4：5의 비율은 ⟨4/5⟩예요.","그래서 비율이 같지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#5','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C2',1,'mc','auto','12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"12：20을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"6：10","mis":"M6-2-u4-X05"},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：20","mis":"M6-2-u4-X02"}],"explanation":["12와 20의 최대공약수는 4예요.","전항과 후항을 똑같이 4로 나누면 3：5예요.","3과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"36：48을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"18：24","mis":"M6-2-u4-X05"},{"t":"4：3","mis":"M6-2-u4-X03"},{"t":"3：48","mis":"M6-2-u4-X02"}],"explanation":["36과 48의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 3：4예요.","3과 4는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"18：9","mis":"M6-2-u4-X05"},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：27","mis":"M6-2-u4-X02"}],"explanation":["54와 27의 최대공약수는 27이에요.","전항과 후항을 똑같이 27로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#6','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C2',2,'mc','auto','90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"90：54를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"5：3","correct":true},{"t":"45：27","mis":"M6-2-u4-X05"},{"t":"3：5","mis":"M6-2-u4-X03"},{"t":"5：54","mis":"M6-2-u4-X02"}],"explanation":["90과 54의 최대공약수는 18이에요.","전항과 후항을 똑같이 18로 나누면 5：3이에요.","5와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"96：60을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：5","correct":true},{"t":"48：30","mis":"M6-2-u4-X05"},{"t":"5：8","mis":"M6-2-u4-X03"},{"t":"8：60","mis":"M6-2-u4-X02"}],"explanation":["96과 60의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 8：5예요.","8과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：3","correct":true},{"t":"42：18","mis":"M6-2-u4-X05"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：36","mis":"M6-2-u4-X02"}],"explanation":["84와 36의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 7：3이에요.","7과 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#7','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C3',1,'sa','auto','0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"0.6：1.5의 전항과 후항에 10을 곱하면 6：15예요. 다시 3으로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["5"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.6：1.5에 10을 곱하면 6：15예요.","두 항을 3으로 나누면 2：5예요."],"variant_rule":{"alt":[{"stem":"1.2：1.6의 전항과 후항에 10을 곱하면 12：16이에요. 다시 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","1.2：1.6에 10을 곱하면 12：16이에요.","두 항을 4로 나누면 3：4예요."]},{"stem":"0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.8：0.4에 10을 곱하면 8：4예요.","두 항을 4로 나누면 2：1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#8','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C3',2,'mc','auto','0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X06']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.25：0.75를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"1：3","correct":true},{"t":"25：75","mis":"M6-2-u4-X05"},{"t":"3：1","mis":"M6-2-u4-X03"},{"t":"2.5：7.5","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 25：75예요.","25와 75의 최대공약수 25로 나누면 1：3이에요.","그래서 가장 간단한 자연수의 비는 1：3이에요."],"variant_rule":{"alt":[{"stem":"0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：5","correct":true},{"t":"12：30","mis":"M6-2-u4-X05"},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"1.2：3","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 12：30이에요.","12와 30의 최대공약수 6으로 나누면 2：5예요.","그래서 가장 간단한 자연수의 비는 2：5예요."]},{"stem":"2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#9','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C4',2,'mc','auto','⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X03']::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩：⟨5/6⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"9：10","correct":true},{"t":"4：6","mis":"M6-2-u4-X07"},{"t":"3：5","mis":"M6-2-u4-X07"},{"t":"10：9","mis":"M6-2-u4-X03"}],"explanation":["두 분모 4와 6의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨3/4⟩ × 12 = 9, ⟨5/6⟩ × 12 = 10이에요.","그래서 가장 간단한 자연수의 비는 9：10이에요."],"variant_rule":{"alt":[{"stem":"⟨1/5⟩：⟨1/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"5：7","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"8：5","mis":"M6-2-u4-X20"}],"explanation":["두 분모 5와 7의 공배수 35를 전항과 후항에 똑같이 곱해요.","⟨1/5⟩ × 35 = 7, ⟨1/7⟩ × 35 = 5예요.","그래서 가장 간단한 자연수의 비는 7：5예요."]},{"stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"},{"t":"9：14","mis":"M6-2-u4-X03"}],"explanation":["두 분모 3과 7의 공배수 21을 전항과 후항에 똑같이 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 가장 간단한 자연수의 비는 14：9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#10','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C4',3,'mc','auto','0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"0.3：⟨1/2⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：5","correct":true},{"t":"5：3","mis":"M6-2-u4-X03"},{"t":"3：1","mis":"M6-2-u4-X06"},{"t":"4：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨1/2⟩을 소수 0.5로 바꾸면 0.3：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 3：5예요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-2-u4-X03"},{"t":"2：5","mis":"M6-2-u4-X06"},{"t":"5：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.4：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 4：5예요."]},{"stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X06"},{"t":"16：16","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨3/4⟩을 소수 0.75로 바꾸면 0.75：0.8이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 15：16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#11','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',1,'mc','auto','비례식 9：12 = 3：4에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":11,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 9：12 = 3：4에서 내항은 어느 것인가요?","options":[{"t":"12와 3","correct":true},{"t":"9와 4","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"},{"t":"3과 4","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","9：12 = 3：4에서 바깥쪽은 9와 4, 안쪽은 12와 3이에요.","그래서 내항은 12와 3이에요."],"variant_rule":{"alt":[{"stem":"비례식 6：8 = 9：12에서 내항은 어느 것인가요?","options":[{"t":"8과 9","correct":true},{"t":"6과 12","mis":"M6-2-u4-X10"},{"t":"6과 8","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","6：8 = 9：12에서 바깥쪽은 6과 12, 안쪽은 8과 9예요.","그래서 내항은 8과 9예요."]},{"stem":"비례식 8：7 = 24：21에서 외항은 어느 것인가요?","options":[{"t":"8과 21","correct":true},{"t":"7과 24","mis":"M6-2-u4-X10"},{"t":"8과 7","mis":"M6-2-u4-X10"},{"t":"24와 21","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","8：7 = 24：21에서 바깥쪽은 8과 21, 안쪽은 7과 24예요.","그래서 외항은 8과 21이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#12','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"8：6 = 4：3","correct":true},{"t":"8：6 = 6：8","mis":"M6-2-u4-X09"},{"t":"8：6 = 10：8","mis":"M6-2-u4-X01"},{"t":"8：6 = 16：6","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","8：6과 4：3의 비율은 모두 ⟨4/3⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"9：12 = 12：9","mis":"M6-2-u4-X09"},{"t":"9：12 = 10：13","mis":"M6-2-u4-X01"},{"t":"9：12 = 3：12","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","9：12와 3：4의 비율은 모두 ⟨3/4⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"50：20 = 25：10","correct":true},{"t":"7：4 = 4：7","mis":"M6-2-u4-X09"},{"t":"5：8 = 10：24","mis":"M6-2-u4-X02"},{"t":"3：2 = 2：3","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","50：20과 25：10의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#13','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C5',3,'mc','auto','2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":13,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"2：5, ⟨1/2⟩：⟨1/5⟩, 0.4：1, 5：3 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"2：5 = 0.4：1","correct":true},{"t":"⟨1/2⟩：⟨1/5⟩ = 2：5","mis":"M6-2-u4-X07"},{"t":"2：5 = 5：3","mis":"M6-2-u4-X20"},{"t":"⟨1/2⟩：⟨1/5⟩ = 0.4：1","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","2：5 = 0.4：1의 두 비는 간단히 하면 모두 2：5예요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"4：3, ⟨1/4⟩：⟨1/3⟩, 1.6：1.2, 3：5 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"4：3 = 1.6：1.2","correct":true},{"t":"⟨1/4⟩：⟨1/3⟩ = 4：3","mis":"M6-2-u4-X07"},{"t":"4：3 = 3：5","mis":"M6-2-u4-X20"},{"t":"⟨1/4⟩：⟨1/3⟩ = 1.6：1.2","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","4：3 = 1.6：1.2의 두 비는 간단히 하면 모두 4：3이에요.","나머지는 비율이 서로 달라요."]},{"stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = 2.4：2.1","mis":"M6-2-u4-X20"},{"t":"⟨1/5⟩：⟨1/6⟩ = 5：6","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"}],"explanation":["각 비의 비율을 견주어 봐요.","8：7 = 2.4：2.1의 두 비는 간단히 하면 모두 8：7이에요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#14','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 2：3 = 8：12에서 내항의 곱은 얼마인가요?","answer":["24"],"explanation":["내항은 3과 8이에요.","내항의 곱은 3 × 8 = 24예요.","외항의 곱도 24로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?","answer":["40"],"explanation":["내항은 5와 8이에요.","내항의 곱은 5 × 8 = 40이에요.","외항의 곱도 40으로 같아요."]},{"stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#15','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',2,'sa','auto','3：11 = □：22에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"3：11 = □：22에서 □에 알맞은 수는 얼마인가요?","answer":["6"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","외항의 곱은 3 × 22 = 66이므로 11 × □ = 66이에요.","□ = 66 ÷ 11 = 6이에요."],"variant_rule":{"alt":[{"stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."]},{"stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#16','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C6',3,'mc','auto','6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"6：9 = 10：□를 푸는데 친구가 「6 × 10 = 9 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 6 × 10으로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","6 × □ = 9 × 10이에요.","□ = 15예요."],"variant_rule":{"alt":[{"stem":"9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 9 × 18로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","9 × □ = 4 × 18이에요.","□ = 8이에요."]},{"stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#17','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',1,'sa','auto','물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"물이 일정하게 나오는 수도로 들이가 15 L인 수조를 가득 채우는 데 24초가 걸려요. 들이가 50 L인 수조를 가득 채우려면 몇 초가 걸리나요?","answer":["80"],"explanation":["구하려는 값을 □라 하고 비례식 15：24 = 50：□를 세워요.","내항의 곱 24 × 50 = 1200이므로 15 × □ = 1200이에요.","□ = 1200 ÷ 15 = 80 — 80초예요."],"variant_rule":{"alt":[{"stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."]},{"stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#18','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',2,'mc','auto','공책 4권이 3600원이에요. 공책 9권은 얼마인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X12','M6-2-u4-X20']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"공책 4권이 3600원이에요. 공책 9권은 얼마인가요?","options":[{"t":"8100원","correct":true},{"t":"3605원","mis":"M6-2-u4-X14"},{"t":"32400원","mis":"M6-2-u4-X12"},{"t":"16200원","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 4：3600 = 9：□를 세워요.","내항의 곱 3600 × 9 = 32400이므로 4 × □ = 32400이에요.","□ = 32400 ÷ 4 = 8100 — 8100원예요."],"variant_rule":{"alt":[{"stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."]},{"stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#19','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',3,'mc','auto','사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"사과 9개로 주스 4병을 만들어요. 주스 12병에 드는 사과를 □개라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"9：4 = □：12","correct":true},{"t":"9：4 = 12：□","mis":"M6-2-u4-X13"},{"t":"4：9 = □：12","mis":"M6-2-u4-X13"},{"t":"9：12 = □：4","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 9：4 = □：12예요."],"variant_rule":{"alt":[{"stem":"페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"4：48 = □：60","correct":true},{"t":"4：48 = 60：□","mis":"M6-2-u4-X13"},{"t":"48：4 = □：60","mis":"M6-2-u4-X13"},{"t":"4：60 = □：48","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 4：48 = □：60이에요."]},{"stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#20','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',1,'sa','auto','사과 28개를 정후네와 연아네가 3：4로 나누어요. 연아네는 몇 개를 받나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"사과 28개를 정후네와 연아네가 3：4로 나누어요. 연아네는 몇 개를 받나요?","answer":["16"],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","28 × ⟨4/7⟩ = 16(개)예요."],"variant_rule":{"alt":[{"stem":"연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."]},{"stem":"꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#21','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',2,'mc','auto','1시간 동안 달리기와 줄넘기를 7：5의 시간으로 했어요. 달리기를 한 시간은 몇 분인가요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"1시간 동안 달리기와 줄넘기를 7：5의 시간으로 했어요. 달리기를 한 시간은 몇 분인가요?","options":[{"t":"35분","correct":true},{"t":"25분","mis":"M6-2-u4-X17"},{"t":"5분","mis":"M6-2-u4-X16"},{"t":"84분","mis":"M6-2-u4-X16"}],"explanation":["비 7：5는 한 묶음이 7 + 5 = 12칸이에요.","앞쪽의 몫은 전체의 ⟨7/12⟩이에요.","60 × ⟨7/12⟩ = 35(분)예요."],"variant_rule":{"alt":[{"stem":"2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."]},{"stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#22','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C8',3,'mc','auto','2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"2400을 3：5로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"2400 ÷ 3을 하여 800씩 나눈다","correct":true},{"t":"전체를 8칸으로 갈라 3칸과 5칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"2400 × ⟨3/8⟩과 2400 × ⟨5/8⟩를 각각 구한다","mis":"M6-2-u4-X19"},{"t":"900과 1500으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["3：5는 한 묶음이 8칸이라는 뜻이에요.","그래서 2400 × ⟨3/8⟩ = 900, 2400 × ⟨5/8⟩ = 1500이에요.","2400 ÷ 3처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1800 ÷ 2를 하여 900씩 나눈다","correct":true},{"t":"전체를 9칸으로 갈라 2칸과 7칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1800 × ⟨2/9⟩와 1800 × ⟨7/9⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"400과 1400으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：7은 한 묶음이 9칸이라는 뜻이에요.","그래서 1800 × ⟨2/9⟩ = 400, 1800 × ⟨7/9⟩ = 1400이에요.","1800 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#23','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 600000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 6000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"120000원","correct":true},{"t":"400000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"180000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 600000 × ⟨3/10⟩ = 180000(원)예요.","12000원：6000원을 간단히 하면 2：1이에요.","180000 × ⟨2/3⟩ = 120000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#24','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 800000원을 회사와 사용자가 3：1로 나누어요. 두 친구의 몫을 낸 사용료(태리 6000원, 동하 10000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 5장, 동하 3장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 800000원을 회사와 사용자가 3：1로 나누어요. 두 친구의 몫을 낸 사용료(태리 6000원, 동하 10000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 5장, 동하 3장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000원이다. 사용료의 비 3：5로 나누면 태리 75000원, 동하 125000원이다. 그림 수의 비 5：3으로 나누면 태리 125000원이므로 그림 수의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 200000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 200000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_c#25','math',6,2,'u4','','g6_2_math_u4_review_c','unit_review','M6-2-u4-C7',4,'essay','teacher','밀가루 3컵로 빵 2개를 만들 수 있어요. 빵 10개를 만들려면 밀가루가 몇 컵 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"밀가루 3컵로 빵 2개를 만들 수 있어요. 빵 10개를 만들려면 밀가루가 몇 컵 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 3：2 = □：10이다. ① 외항의 곱과 내항의 곱이 같으므로 3 × 10 = 2 × □, □ = 15이다. ② 후항에 5를 곱했으므로 전항에도 5를 곱해 □ = 15이다.","scoring_points":["3：2 = □：10을 세웠는가","비례식의 성질로 15를 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["3：2 = □：10이에요.","3 × 10 = 2 × □ → □ = 15예요.","5배 해도 □ = 15예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#1','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',1,'sa','auto','5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"5：6의 전항과 후항에 똑같이 4를 곱했어요. 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["24"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 5에 4를 곱해 20이 되었으니 후항 6에도 4를 곱해요.","6 × 4 = 24 — 20：24예요."],"variant_rule":{"alt":[{"stem":"3：11의 전항과 후항에 똑같이 3을 곱했어요. 9：□에서 □에 알맞은 수는 얼마인가요?","answer":["33"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 3에 3을 곱해 9가 되었으니 후항 11에도 3을 곱해요.","11 × 3 = 33 — 9：33이에요."]},{"stem":"7：2의 전항과 후항에 똑같이 5를 곱했어요. 35：□에서 □에 알맞은 수는 얼마인가요?","answer":["10"],"explanation":["비의 전항과 후항에 0이 아닌 같은 수를 곱해도 비율은 같아요.","전항 7에 5를 곱해 35가 되었으니 후항 2에도 5를 곱해요.","2 × 5 = 10 — 35：10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#2','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',1,'sa','auto','56：21의 전항과 후항을 똑같이 7로 나누었어요. 8：□에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u4-C1","difficulty":1,"kind":"sa","stem":"56：21의 전항과 후항을 똑같이 7로 나누었어요. 8：□에서 □에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 56을 7로 나누면 8이에요.","후항도 21 ÷ 7 = 3 — 8：3이에요."],"variant_rule":{"alt":[{"stem":"35：14의 전항과 후항을 똑같이 7로 나누었어요. 5：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 35를 7로 나누면 5예요.","후항도 14 ÷ 7 = 2 — 5：2예요."]},{"stem":"45：30의 전항과 후항을 똑같이 15로 나누었어요. 3：□에서 □에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["비의 전항과 후항을 0이 아닌 같은 수로 나누어도 비율은 같아요.","전항 45를 15로 나누면 3이에요.","후항도 30 ÷ 15 = 2 — 3：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#3','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',2,'mc','auto','3：7과 비율이 같은 비는 어느 것인가요?',ARRAY['M6-2-u4-X01','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":3,"concept":"M6-2-u4-C1","difficulty":2,"kind":"mc","stem":"3：7과 비율이 같은 비는 어느 것인가요?","options":[{"t":"9：21","correct":true},{"t":"6：10","mis":"M6-2-u4-X01"},{"t":"21：9","mis":"M6-2-u4-X03"},{"t":"9：7","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","3：7의 두 항에 똑같이 3을 곱하면 9：21이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."],"variant_rule":{"alt":[{"stem":"2：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"4：6","correct":true},{"t":"4：5","mis":"M6-2-u4-X01"},{"t":"6：4","mis":"M6-2-u4-X03"},{"t":"4：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","2：3의 두 항에 똑같이 2를 곱하면 4：6이에요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]},{"stem":"4：3과 비율이 같은 비는 어느 것인가요?","options":[{"t":"12：9","correct":true},{"t":"7：6","mis":"M6-2-u4-X01"},{"t":"9：12","mis":"M6-2-u4-X03"},{"t":"12：3","mis":"M6-2-u4-X02"}],"explanation":["전항과 후항에 0이 아닌 같은 수를 곱하면 비율이 같아요.","4：3의 두 항에 똑같이 3을 곱하면 12：9예요.","같은 수를 더하거나 한 항만 바꾼 비는 비율이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#4','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C1',3,'ox','auto','4：7의 전항과 후항에 똑같이 1을 더한 5：8은 4：7과 비율이 같아요.',ARRAY['M6-2-u4-X01']::text[],true,'{"seq":4,"concept":"M6-2-u4-C1","difficulty":3,"kind":"ox","stem":"4：7의 전항과 후항에 똑같이 1을 더한 5：8은 4：7과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨4/7⟩와 ⟨5/8⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"mis":"M6-2-u4-X01","explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","4：7의 비율은 ⟨4/7⟩, 5：8의 비율은 ⟨5/8⟩예요.","그래서 비율이 같지 않아요."],"variant_rule":{"alt":[{"stem":"2：3의 전항과 후항에 똑같이 2를 더한 4：5는 2：3과 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨2/3⟩와 ⟨4/5⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","2：3의 비율은 ⟨2/3⟩, 4：5의 비율은 ⟨4/5⟩예요.","그래서 비율이 같지 않아요."]},{"stem":"3：5의 전항과 후항에 똑같이 2를 더한 5：7은 3：5와 비율이 같아요.","answer":"X","reason_options":[{"t":"같은 수를 더하는 것은 비의 성질이 아니어서 비율이 ⟨3/5⟩과 ⟨5/7⟩로 달라지기 때문에","correct":true},{"t":"두 항을 똑같이 바꾸었으니 비율이 그대로이기 때문에","mis":"M6-2-u4-X01"}],"explanation":["비의 성질은 같은 수를 곱하거나 나눌 때만 써요.","3：5의 비율은 ⟨3/5⟩, 5：7의 비율은 ⟨5/7⟩예요.","그래서 비율이 같지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#5','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C2',1,'mc','auto','36：48을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":5,"concept":"M6-2-u4-C2","difficulty":1,"kind":"mc","stem":"36：48을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"18：24","mis":"M6-2-u4-X05"},{"t":"4：3","mis":"M6-2-u4-X03"},{"t":"3：48","mis":"M6-2-u4-X02"}],"explanation":["36과 48의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 3：4예요.","3과 4는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"54：27을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：1","correct":true},{"t":"18：9","mis":"M6-2-u4-X05"},{"t":"1：2","mis":"M6-2-u4-X03"},{"t":"2：27","mis":"M6-2-u4-X02"}],"explanation":["54와 27의 최대공약수는 27이에요.","전항과 후항을 똑같이 27로 나누면 2：1이에요.","2와 1은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"28：63을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：9","correct":true},{"t":"9：4","mis":"M6-2-u4-X03"},{"t":"4：63","mis":"M6-2-u4-X02"},{"t":"28：9","mis":"M6-2-u4-X02"}],"explanation":["28과 63의 최대공약수는 7이에요.","전항과 후항을 똑같이 7로 나누면 4：9예요.","4와 9는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#6','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C2',2,'mc','auto','96：60을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X02']::text[],true,'{"seq":6,"concept":"M6-2-u4-C2","difficulty":2,"kind":"mc","stem":"96：60을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"8：5","correct":true},{"t":"48：30","mis":"M6-2-u4-X05"},{"t":"5：8","mis":"M6-2-u4-X03"},{"t":"8：60","mis":"M6-2-u4-X02"}],"explanation":["96과 60의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 8：5예요.","8과 5는 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."],"variant_rule":{"alt":[{"stem":"84：36을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：3","correct":true},{"t":"42：18","mis":"M6-2-u4-X05"},{"t":"3：7","mis":"M6-2-u4-X03"},{"t":"7：36","mis":"M6-2-u4-X02"}],"explanation":["84와 36의 최대공약수는 12예요.","전항과 후항을 똑같이 12로 나누면 7：3이에요.","7과 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]},{"stem":"48：72를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"24：36","mis":"M6-2-u4-X05"},{"t":"3：2","mis":"M6-2-u4-X03"},{"t":"2：72","mis":"M6-2-u4-X02"}],"explanation":["48과 72의 최대공약수는 24예요.","전항과 후항을 똑같이 24로 나누면 2：3이에요.","2와 3은 더 나눌 공약수가 없으니 가장 간단한 자연수의 비예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#7','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C3',1,'sa','auto','1.2：1.6의 전항과 후항에 10을 곱하면 12：16이에요. 다시 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u4-C3","difficulty":1,"kind":"sa","stem":"1.2：1.6의 전항과 후항에 10을 곱하면 12：16이에요. 다시 4로 나누면 3：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["4"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","1.2：1.6에 10을 곱하면 12：16이에요.","두 항을 4로 나누면 3：4예요."],"variant_rule":{"alt":[{"stem":"0.8：0.4의 전항과 후항에 10을 곱하면 8：4예요. 다시 4로 나누면 2：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["1"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","0.8：0.4에 10을 곱하면 8：4예요.","두 항을 4로 나누면 2：1이에요."]},{"stem":"3.5：4.9의 전항과 후항에 10을 곱하면 35：49예요. 다시 7로 나누면 5：□가 돼요. □에 알맞은 수는 얼마인가요?","answer":["7"],"explanation":["소수의 비는 10, 100을 곱해 자연수의 비로 만들어요.","3.5：4.9에 10을 곱하면 35：49예요.","두 항을 7로 나누면 5：7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#8','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C3',2,'mc','auto','0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X05','M6-2-u4-X03','M6-2-u4-X06']::text[],true,'{"seq":8,"concept":"M6-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.12：0.3을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：5","correct":true},{"t":"12：30","mis":"M6-2-u4-X05"},{"t":"5：2","mis":"M6-2-u4-X03"},{"t":"1.2：3","mis":"M6-2-u4-X06"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 100을 곱하면 12：30이에요.","12와 30의 최대공약수 6으로 나누면 2：5예요.","그래서 가장 간단한 자연수의 비는 2：5예요."],"variant_rule":{"alt":[{"stem":"2.1：5.6을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"3：8","correct":true},{"t":"21：56","mis":"M6-2-u4-X05"},{"t":"8：3","mis":"M6-2-u4-X03"},{"t":"21：5.6","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 21：56이에요.","21과 56의 최대공약수 7로 나누면 3：8이에요.","그래서 가장 간단한 자연수의 비는 3：8이에요."]},{"stem":"1.4：1.2를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：6","correct":true},{"t":"14：12","mis":"M6-2-u4-X05"},{"t":"6：7","mis":"M6-2-u4-X03"},{"t":"14：1.2","mis":"M6-2-u4-X02"}],"explanation":["두 항이 모두 자연수가 되도록 전항과 후항에 똑같이 10을 곱하면 14：12예요.","14와 12의 최대공약수 2로 나누면 7：6이에요.","그래서 가장 간단한 자연수의 비는 7：6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#9','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C4',2,'mc','auto','⟨1/5⟩：⟨1/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":9,"concept":"M6-2-u4-C4","difficulty":2,"kind":"mc","stem":"⟨1/5⟩：⟨1/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：5","correct":true},{"t":"5：7","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"8：5","mis":"M6-2-u4-X20"}],"explanation":["두 분모 5와 7의 공배수 35를 전항과 후항에 똑같이 곱해요.","⟨1/5⟩ × 35 = 7, ⟨1/7⟩ × 35 = 5예요.","그래서 가장 간단한 자연수의 비는 7：5예요."],"variant_rule":{"alt":[{"stem":"⟨2/3⟩：⟨3/7⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"14：9","correct":true},{"t":"3：7","mis":"M6-2-u4-X07"},{"t":"2：3","mis":"M6-2-u4-X07"},{"t":"9：14","mis":"M6-2-u4-X03"}],"explanation":["두 분모 3과 7의 공배수 21을 전항과 후항에 똑같이 곱해요.","⟨2/3⟩ × 21 = 14, ⟨3/7⟩ × 21 = 9예요.","그래서 가장 간단한 자연수의 비는 14：9예요."]},{"stem":"⟨1/6⟩：⟨1/4⟩을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"2：3","correct":true},{"t":"6：4","mis":"M6-2-u4-X07"},{"t":"1：1","mis":"M6-2-u4-X07"},{"t":"3：2","mis":"M6-2-u4-X03"}],"explanation":["두 분모 6과 4의 공배수 12를 전항과 후항에 똑같이 곱해요.","⟨1/6⟩ × 12 = 2, ⟨1/4⟩ × 12 = 3이에요.","그래서 가장 간단한 자연수의 비는 2：3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#10','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C4',3,'mc','auto','⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?',ARRAY['M6-2-u4-X03','M6-2-u4-X06','M6-2-u4-X20']::text[],true,'{"seq":10,"concept":"M6-2-u4-C4","difficulty":3,"kind":"mc","stem":"⟨2/5⟩：0.5를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-2-u4-X03"},{"t":"2：5","mis":"M6-2-u4-X06"},{"t":"5：5","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.4：0.5예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 4：5예요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩：0.8을 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"15：16","correct":true},{"t":"16：15","mis":"M6-2-u4-X03"},{"t":"3：8","mis":"M6-2-u4-X06"},{"t":"16：16","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","전항 ⟨3/4⟩을 소수 0.75로 바꾸면 0.75：0.8이에요.","두 항을 자연수로 만들어 가장 간단히 나타내면 15：16이에요."]},{"stem":"0.7：⟨2/5⟩를 간단한 자연수의 비로 나타내면 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"4：7","mis":"M6-2-u4-X03"},{"t":"7：2","mis":"M6-2-u4-X06"},{"t":"8：4","mis":"M6-2-u4-X20"}],"explanation":["소수와 분수가 섞인 비는 먼저 한쪽을 같은 꼴로 바꿔요.","후항 ⟨2/5⟩를 소수 0.4로 바꾸면 0.7：0.4예요.","두 항을 자연수로 만들어 가장 간단히 나타내면 7：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#11','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',1,'mc','auto','비례식 6：8 = 9：12에서 내항은 어느 것인가요?',ARRAY['M6-2-u4-X10']::text[],true,'{"seq":11,"concept":"M6-2-u4-C5","difficulty":1,"kind":"mc","stem":"비례식 6：8 = 9：12에서 내항은 어느 것인가요?","options":[{"t":"8과 9","correct":true},{"t":"6과 12","mis":"M6-2-u4-X10"},{"t":"6과 8","mis":"M6-2-u4-X10"},{"t":"9와 12","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","6：8 = 9：12에서 바깥쪽은 6과 12, 안쪽은 8과 9예요.","그래서 내항은 8과 9예요."],"variant_rule":{"alt":[{"stem":"비례식 8：7 = 24：21에서 외항은 어느 것인가요?","options":[{"t":"8과 21","correct":true},{"t":"7과 24","mis":"M6-2-u4-X10"},{"t":"8과 7","mis":"M6-2-u4-X10"},{"t":"24와 21","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","8：7 = 24：21에서 바깥쪽은 8과 21, 안쪽은 7과 24예요.","그래서 외항은 8과 21이에요."]},{"stem":"비례식 56：21 = 8：3에서 외항은 어느 것인가요?","options":[{"t":"56과 3","correct":true},{"t":"21과 8","mis":"M6-2-u4-X10"},{"t":"56과 21","mis":"M6-2-u4-X10"},{"t":"8과 3","mis":"M6-2-u4-X10"}],"explanation":["비례식에서 바깥쪽 두 수를 외항, 안쪽 두 수를 내항이라고 해요.","56：21 = 8：3에서 바깥쪽은 56과 3, 안쪽은 21과 8이에요.","그래서 외항은 56과 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#12','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',2,'mc','auto','다음 중 비례식인 것은 어느 것인가요?',ARRAY['M6-2-u4-X09','M6-2-u4-X01','M6-2-u4-X02']::text[],true,'{"seq":12,"concept":"M6-2-u4-C5","difficulty":2,"kind":"mc","stem":"다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"9：12 = 3：4","correct":true},{"t":"9：12 = 12：9","mis":"M6-2-u4-X09"},{"t":"9：12 = 10：13","mis":"M6-2-u4-X01"},{"t":"9：12 = 3：12","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","9：12와 3：4의 비율은 모두 ⟨3/4⟩으로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"50：20 = 25：10","correct":true},{"t":"7：4 = 4：7","mis":"M6-2-u4-X09"},{"t":"5：8 = 10：24","mis":"M6-2-u4-X02"},{"t":"3：2 = 2：3","mis":"M6-2-u4-X09"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","50：20과 25：10의 비율은 모두 ⟨5/2⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]},{"stem":"이번에는 다른 보기예요. 다음 중 비례식인 것은 어느 것인가요?","options":[{"t":"2：5 = 6：15","correct":true},{"t":"2：5 = 5：2","mis":"M6-2-u4-X09"},{"t":"2：5 = 4：7","mis":"M6-2-u4-X01"},{"t":"2：5 = 4：5","mis":"M6-2-u4-X02"}],"explanation":["비례식은 비율이 같은 두 비를 등호로 이은 식이에요.","2：5와 6：15의 비율은 모두 ⟨2/5⟩로 같아요.","수의 모양이 아니라 비율을 견주어 판단해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#13','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C5',3,'mc','auto','4：3, ⟨1/4⟩：⟨1/3⟩, 1.6：1.2, 3：5 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?',ARRAY['M6-2-u4-X07','M6-2-u4-X20']::text[],true,'{"seq":13,"concept":"M6-2-u4-C5","difficulty":3,"kind":"mc","stem":"4：3, ⟨1/4⟩：⟨1/3⟩, 1.6：1.2, 3：5 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"4：3 = 1.6：1.2","correct":true},{"t":"⟨1/4⟩：⟨1/3⟩ = 4：3","mis":"M6-2-u4-X07"},{"t":"4：3 = 3：5","mis":"M6-2-u4-X20"},{"t":"⟨1/4⟩：⟨1/3⟩ = 1.6：1.2","mis":"M6-2-u4-X07"}],"explanation":["각 비의 비율을 견주어 봐요.","4：3 = 1.6：1.2의 두 비는 간단히 하면 모두 4：3이에요.","나머지는 비율이 서로 달라요."],"variant_rule":{"alt":[{"stem":"5：6, 8：7, ⟨1/5⟩：⟨1/6⟩, 2.4：2.1 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"8：7 = 2.4：2.1","correct":true},{"t":"5：6 = 2.4：2.1","mis":"M6-2-u4-X20"},{"t":"⟨1/5⟩：⟨1/6⟩ = 5：6","mis":"M6-2-u4-X07"},{"t":"5：6 = 8：7","mis":"M6-2-u4-X09"}],"explanation":["각 비의 비율을 견주어 봐요.","8：7 = 2.4：2.1의 두 비는 간단히 하면 모두 8：7이에요.","나머지는 비율이 서로 달라요."]},{"stem":"3：4, 9：8, ⟨1/3⟩：⟨1/4⟩, 1.2：1.6 가운데 비율이 같은 두 비를 이은 비례식은 어느 것인가요?","options":[{"t":"3：4 = 1.2：1.6","correct":true},{"t":"⟨1/3⟩：⟨1/4⟩ = 3：4","mis":"M6-2-u4-X07"},{"t":"3：4 = 9：8","mis":"M6-2-u4-X20"},{"t":"9：8 = 1.2：1.6","mis":"M6-2-u4-X20"}],"explanation":["각 비의 비율을 견주어 봐요.","3：4 = 1.2：1.6의 두 비는 간단히 하면 모두 3：4예요.","나머지는 비율이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#14','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',1,'sa','auto','비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u4-C6","difficulty":1,"kind":"sa","stem":"비례식 4：5 = 8：10에서 내항의 곱은 얼마인가요?","answer":["40"],"explanation":["내항은 5와 8이에요.","내항의 곱은 5 × 8 = 40이에요.","외항의 곱도 40으로 같아요."],"variant_rule":{"alt":[{"stem":"비례식 5：7 = 10：14에서 외항의 곱은 얼마인가요?","answer":["70"],"explanation":["외항은 5와 14예요.","외항의 곱은 5 × 14 = 70이에요.","내항의 곱도 70으로 같아요."]},{"stem":"비례식 9：12 = 3：4에서 외항의 곱은 얼마인가요?","answer":["36"],"explanation":["외항은 9와 4예요.","외항의 곱은 9 × 4 = 36이에요.","내항의 곱도 36으로 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#15','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',2,'sa','auto','□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u4-C6","difficulty":2,"kind":"sa","stem":"□：6 = 12：9에서 □에 알맞은 수는 얼마인가요?","answer":["8"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 6 × 12 = 72이므로 9 × □ = 72예요.","□ = 72 ÷ 9 = 8이에요."],"variant_rule":{"alt":[{"stem":"4：5 = 20：□에서 □에 알맞은 수는 얼마인가요?","answer":["25"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 5 × 20 = 100이므로 4 × □ = 100이에요.","□ = 100 ÷ 4 = 25예요."]},{"stem":"10：8 = 15：□에서 □에 알맞은 수는 얼마인가요?","answer":["12"],"explanation":["비례식에서 외항의 곱과 내항의 곱은 같아요.","내항의 곱은 8 × 15 = 120이므로 10 × □ = 120이에요.","□ = 120 ÷ 10 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#16','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C6',3,'mc','auto','9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['M6-2-u4-X20','M6-2-u4-X09','M6-2-u4-X12']::text[],true,'{"seq":16,"concept":"M6-2-u4-C6","difficulty":3,"kind":"mc","stem":"9：4 = 18：□를 푸는데 친구가 「9 × 18 = 4 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 9 × 18로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","9 × □ = 4 × 18이에요.","□ = 8이에요."],"variant_rule":{"alt":[{"stem":"8：6 = 12：□를 푸는데 친구가 「8 × 12 = 6 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 8 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","8 × □ = 6 × 12예요.","□ = 9예요."]},{"stem":"4：5 = 12：□를 푸는데 친구가 「4 × 12 = 5 × □」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외항끼리·내항끼리가 아니라 전항끼리·후항끼리 곱했다","correct":true},{"t":"외항의 곱을 잘못 계산했다","mis":"M6-2-u4-X20"},{"t":"이 식은 비례식이 아니다","mis":"M6-2-u4-X09"},{"t":"□는 4 × 12로 구한다","mis":"M6-2-u4-X12"}],"explanation":["비례식에서는 외항끼리, 내항끼리 곱해요.","4 × □ = 5 × 12예요.","□ = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#17','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',1,'sa','auto','빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u4-C7","difficulty":1,"kind":"sa","stem":"빵 반죽에 밀가루와 우유를 3：2로 넣어요. 밀가루를 12컵 넣으면 우유는 몇 컵을 넣어야 하나요?","answer":["8"],"explanation":["구하려는 값을 □라 하고 비례식 3：2 = 12：□를 세워요.","내항의 곱 2 × 12 = 24이므로 3 × □ = 24예요.","□ = 24 ÷ 3 = 8 — 8컵예요."],"variant_rule":{"alt":[{"stem":"사과 9개로 사과주스 4병을 만들 수 있어요. 사과주스 12병을 만들려면 사과가 몇 개 필요한가요?","answer":["27"],"explanation":["구하려는 값을 □라 하고 비례식 9：4 = □：12를 세워요.","외항의 곱 9 × 12 = 108이므로 4 × □ = 108이에요.","□ = 108 ÷ 4 = 27 — 27개예요."]},{"stem":"계피와 에탄올을 3：1로 섞어 천연 모기 기피제를 만들어요. 계피 180 g을 쓰면 에탄올은 몇 g이 필요한가요?","answer":["60"],"explanation":["구하려는 값을 □라 하고 비례식 3：1 = 180：□를 세워요.","내항의 곱 1 × 180 = 180이므로 3 × □ = 180이에요.","□ = 180 ÷ 3 = 60 — 60 g예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#18','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',2,'mc','auto','지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?',ARRAY['M6-2-u4-X14','M6-2-u4-X20']::text[],true,'{"seq":18,"concept":"M6-2-u4-C7","difficulty":2,"kind":"mc","stem":"지도에서 1 cm는 실제 거리 2 km예요. 지도에서 7.5 cm인 거리는 실제로 몇 km인가요?","options":[{"t":"15 km","correct":true},{"t":"8.5 km","mis":"M6-2-u4-X14"},{"t":"30 km","mis":"M6-2-u4-X20"},{"t":"22.5 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 1：2 = 7.5：□를 세워요.","내항의 곱 2 × 7.5 = 15이므로 1 × □ = 15예요.","□ = 15 ÷ 1 = 15 — 15 km예요."],"variant_rule":{"alt":[{"stem":"어느 전기차는 6 kWh의 전기 에너지로 40 km를 이동해요. 21 kWh로는 몇 km를 갈 수 있나요?","options":[{"t":"140 km","correct":true},{"t":"55 km","mis":"M6-2-u4-X14"},{"t":"840 km","mis":"M6-2-u4-X12"},{"t":"280 km","mis":"M6-2-u4-X20"}],"explanation":["구하려는 값을 □라 하고 비례식 6：40 = 21：□를 세워요.","내항의 곱 40 × 21 = 840이므로 6 × □ = 840이에요.","□ = 840 ÷ 6 = 140 — 140 km예요."]},{"stem":"페인트 4 L로 담장 48 m²를 칠할 수 있어요. 담장 60 m²를 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"720 L","mis":"M6-2-u4-X13"},{"t":"16 L","mis":"M6-2-u4-X14"},{"t":"240 L","mis":"M6-2-u4-X12"}],"explanation":["구하려는 값을 □라 하고 비례식 4：48 = □：60을 세워요.","외항의 곱 4 × 60 = 240이므로 48 × □ = 240이에요.","□ = 240 ÷ 48 = 5 — 5 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#19','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',3,'mc','auto','페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?',ARRAY['M6-2-u4-X13']::text[],true,'{"seq":19,"concept":"M6-2-u4-C7","difficulty":3,"kind":"mc","stem":"페인트 4 L로 담장 48 m²를 칠해요. 담장 60 m²에 드는 페인트를 □ L라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"4：48 = □：60","correct":true},{"t":"4：48 = 60：□","mis":"M6-2-u4-X13"},{"t":"48：4 = □：60","mis":"M6-2-u4-X13"},{"t":"4：60 = □：48","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 4：48 = □：60이에요."],"variant_rule":{"alt":[{"stem":"쌀 2 kg이 8000원이에요. 40000원으로 살 수 있는 쌀의 무게를 □ kg이라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"2：8000 = □：40000","correct":true},{"t":"2：8000 = 40000：□","mis":"M6-2-u4-X13"},{"t":"8000：2 = □：40000","mis":"M6-2-u4-X13"},{"t":"2：40000 = □：8000","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 2：8000 = □：40000이에요."]},{"stem":"전기차가 6 kWh로 40 km를 가요. 21 kWh로 갈 수 있는 거리를 □ km라 할 때 비례식을 바르게 세운 것은 어느 것인가요?","options":[{"t":"6：40 = 21：□","correct":true},{"t":"6：40 = □：21","mis":"M6-2-u4-X13"},{"t":"40：6 = 21：□","mis":"M6-2-u4-X13"},{"t":"6：□ = 40：21","mis":"M6-2-u4-X13"}],"explanation":["같은 종류의 양끼리 같은 자리에 놓아요.","앞의 비와 뒤의 비가 같은 순서(무게：값, 에너지：거리)여야 해요.","그래서 6：40 = 21：□예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#20','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',1,'sa','auto','연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?','{}'::text[],true,'{"seq":20,"concept":"M6-2-u4-C8","difficulty":1,"kind":"sa","stem":"연필 45자루를 형과 동생이 4：5로 나누어요. 동생은 몇 자루를 받나요?","answer":["25"],"explanation":["비 4：5는 한 묶음이 4 + 5 = 9칸이에요.","뒤쪽의 몫은 전체의 ⟨5/9⟩예요.","45 × ⟨5/9⟩ = 25(자루)예요."],"variant_rule":{"alt":[{"stem":"꿀떡 9개를 리엘이와 동생이 2：1로 나누어 먹어요. 리엘이는 몇 개를 먹나요?","answer":["6"],"explanation":["비 2：1은 한 묶음이 2 + 1 = 3칸이에요.","앞쪽의 몫은 전체의 ⟨2/3⟩예요.","9 × ⟨2/3⟩ = 6(개)예요."]},{"stem":"색종이 72장을 햇빛 모둠과 달빛 모둠이 5：3으로 나누어요. 햇빛 모둠은 몇 장을 받나요?","answer":["45"],"explanation":["비 5：3은 한 묶음이 5 + 3 = 8칸이에요.","앞쪽의 몫은 전체의 ⟨5/8⟩예요.","72 × ⟨5/8⟩ = 45(장)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#21','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',2,'mc','auto','2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?',ARRAY['M6-2-u4-X17','M6-2-u4-X16']::text[],true,'{"seq":21,"concept":"M6-2-u4-C8","difficulty":2,"kind":"mc","stem":"2800원짜리 장난감 값을 수지와 형진이가 3：4로 나누어 내요. 수지는 얼마를 내나요?","options":[{"t":"1200원","correct":true},{"t":"1600원","mis":"M6-2-u4-X17"},{"t":"400원","mis":"M6-2-u4-X16"},{"t":"2100원","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","앞쪽의 몫은 전체의 ⟨3/7⟩이에요.","2800 × ⟨3/7⟩ = 1200(원)예요."],"variant_rule":{"alt":[{"stem":"찰흙 420 g을 3：4로 나누어 거북과 악어를 만들어요. 악어를 만드는 데 필요한 찰흙은 몇 g인가요?","options":[{"t":"240 g","correct":true},{"t":"105 g","mis":"M6-2-u4-X15"},{"t":"180 g","mis":"M6-2-u4-X17"},{"t":"60 g","mis":"M6-2-u4-X16"}],"explanation":["비 3：4는 한 묶음이 3 + 4 = 7칸이에요.","뒤쪽의 몫은 전체의 ⟨4/7⟩예요.","420 × ⟨4/7⟩ = 240( g)예요."]},{"stem":"용돈 10000원을 학용품과 장난감을 사는 데 3：2로 나누어 써요. 학용품에 쓸 용돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"4000원","mis":"M6-2-u4-X17"},{"t":"2000원","mis":"M6-2-u4-X16"},{"t":"15000원","mis":"M6-2-u4-X16"}],"explanation":["비 3：2는 한 묶음이 3 + 2 = 5칸이에요.","앞쪽의 몫은 전체의 ⟨3/5⟩이에요.","10000 × ⟨3/5⟩ = 6000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#22','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C8',3,'mc','auto','1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?',ARRAY['M6-2-u4-X19']::text[],true,'{"seq":22,"concept":"M6-2-u4-C8","difficulty":3,"kind":"mc","stem":"1800을 2：7로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1800 ÷ 2를 하여 900씩 나눈다","correct":true},{"t":"전체를 9칸으로 갈라 2칸과 7칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1800 × ⟨2/9⟩와 1800 × ⟨7/9⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"400과 1400으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：7은 한 묶음이 9칸이라는 뜻이에요.","그래서 1800 × ⟨2/9⟩ = 400, 1800 × ⟨7/9⟩ = 1400이에요.","1800 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."],"variant_rule":{"alt":[{"stem":"1200을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1200 ÷ 2를 하여 600씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1200 × ⟨2/5⟩와 1200 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"480과 720으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1200 × ⟨2/5⟩ = 480, 1200 × ⟨3/5⟩ = 720이에요.","1200 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]},{"stem":"1500을 2：3으로 비례배분하려고 해요. 잘못된 방법은 어느 것인가요?","options":[{"t":"1500 ÷ 2를 하여 750씩 나눈다","correct":true},{"t":"전체를 5칸으로 갈라 2칸과 3칸으로 나눈다","mis":"M6-2-u4-X19"},{"t":"1500 × ⟨2/5⟩와 1500 × ⟨3/5⟩을 각각 구한다","mis":"M6-2-u4-X19"},{"t":"600과 900으로 나눈다","mis":"M6-2-u4-X19"}],"explanation":["2：3은 한 묶음이 5칸이라는 뜻이에요.","그래서 1500 × ⟨2/5⟩ = 600, 1500 × ⟨3/5⟩ = 900이에요.","1500 ÷ 2처럼 한 항으로 나누면 비례배분이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#23','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',4,'mc','auto','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?',ARRAY['M6-2-u4-X18','M6-2-u4-X17','M6-2-u4-X20']::text[],true,'{"seq":23,"concept":"M6-2-u4-C9","difficulty":4,"kind":"mc","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 800000원을 회사와 사용자가 3：1로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 9000원, 동하 3000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"50000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"150000원","mis":"M6-2-u4-X17"},{"t":"100000원","mis":"M6-2-u4-X20"}],"explanation":["먼저 두 친구의 몫은 800000 × ⟨1/4⟩ = 200000(원)예요.","9000원：3000원을 간단히 하면 3：1이에요.","200000 × ⟨1/4⟩ = 50000(원)예요."],"variant_rule":{"alt":[{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 태리는 몇 원을 받나요?","options":[{"t":"90000원","correct":true},{"t":"300000원","mis":"M6-2-u4-X18"},{"t":"60000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨3/5⟩ = 90000(원)예요."]},{"stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 전체 수익 500000원을 회사와 사용자가 7：3으로 나누고, 두 친구가 받은 몫을 다시 낸 사용료의 비(태리 12000원, 동하 8000원)로 나누어요. 동하는 몇 원을 받나요?","options":[{"t":"60000원","correct":true},{"t":"200000원","mis":"M6-2-u4-X18"},{"t":"90000원","mis":"M6-2-u4-X17"},{"t":"150000원","mis":"M6-2-u4-X18"}],"explanation":["먼저 두 친구의 몫은 500000 × ⟨3/10⟩ = 150000(원)예요.","12000원：8000원을 간단히 하면 3：2예요.","150000 × ⟨2/5⟩ = 60000(원)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#24','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C9',4,'essay','teacher','태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 400000원을 회사와 사용자가 3：2로 나누어요. 두 친구의 몫을 낸 사용료(태리 9000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 1장, 동하 1장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u4-C9","difficulty":4,"kind":"essay","stem":"태리와 동하가 이미지 생성 인공지능으로 그린 그림을 이어 붙여 협동 작품을 만들었어요. 작품 수익 400000원을 회사와 사용자가 3：2로 나누어요. 두 친구의 몫을 낸 사용료(태리 9000원, 동하 6000원)의 비로 나누는 과정을 쓰고, 그린 그림 수(태리 1장, 동하 1장)의 비로 나눌 때와 태리의 몫을 견주어 보세요.","answer_guide":{"answer":"예: 두 친구의 몫은 400000 × ⟨2/5⟩ = 160000원이다. 사용료의 비 3：2로 나누면 태리 96000원, 동하 64000원이다. 그림 수의 비 1：1로 나누면 태리 80000원이므로 사용료의 비로 나눌 때 태리가 더 많이 받는다.","scoring_points":["두 친구의 몫 160000원을 먼저 구했는가","사용료의 비로 두 몫을 바르게 구했는가","그림 수의 비로 나눈 태리의 몫과 견주었는가"]},"explanation":["먼저 두 친구의 몫 160000원을 구해요.","사용료의 비로 나누어요.","그림 수의 비로 나눈 몫과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u4_review_d#25','math',6,2,'u4','','g6_2_math_u4_review_d','unit_review','M6-2-u4-C7',4,'essay','teacher','설탕 4숟가락로 레몬차 5잔을 만들 수 있어요. 레몬차 15잔을 만들려면 설탕이 몇 숟가락 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u4-C7","difficulty":4,"kind":"essay","stem":"설탕 4숟가락로 레몬차 5잔을 만들 수 있어요. 레몬차 15잔을 만들려면 설탕이 몇 숟가락 필요한지 비례식을 세워 비례식의 성질과 비의 성질 두 가지 방법으로 구해 보세요.","answer_guide":{"answer":"예: 필요한 양을 □라 하면 4：5 = □：15이다. ① 외항의 곱과 내항의 곱이 같으므로 4 × 15 = 5 × □, □ = 12이다. ② 후항에 3을 곱했으므로 전항에도 3을 곱해 □ = 12이다.","scoring_points":["4：5 = □：15를 세웠는가","비례식의 성질로 12를 구했는가","비의 성질로 같은 답을 구했는가"]},"explanation":["4：5 = □：15예요.","4 × 15 = 5 × □ → □ = 12예요.","3배 해도 □ = 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
